    `;

    function parseOptions(text) {
        const options = [];
        const regex = /\[([^\|\]]+)\|([^\]]+)\]/g;
        let match;
        while ((match = regex.exec(text)) !== null) {
            options.push({
                type: match[1].trim(),
                text: match[2].trim()
            });
        }
        return options;
    }

    function createHearts(container) {
      for (let i = 0; i < 15; i++) {
        const el = $('<div class="effect-heart">❤</div>');
        const rotAngle = (Math.random() * 720 - 360);
        el.css({
          left: Math.random() * 100 + '%',
          top: '-50px',
          fontSize: (Math.random() * 20 + 20) + 'px',
          animationDuration: (Math.random() * 15 + 10) + 's',
          animationDelay: (Math.random() * 10 - 5) + 's'
        });
        el.css('--rot', rotAngle + 'deg');
        container.append(el);
      }
    }

    function createSnow(container) {
      for (let i = 0; i < 30; i++) {
        const el = $('<div class="effect-snow">❄</div>');
        const drift = (Math.random() * 200 - 100) + 'px';
        const rotAngle = (Math.random() * 720 - 360);
        el.css({
          left: Math.random() * 100 + '%',
          top: '-50px',
          fontSize: (Math.random() * 10 + 10) + 'px',
          opacity: Math.random() * 0.5 + 0.5,
          animationDuration: (Math.random() * 10 + 5) + 's',
          animationDelay: (Math.random() * 10 - 5) + 's'
        });
        el.css('--drift', drift);
        el.css('--rot', rotAngle + 'deg');
        container.append(el);
      }
    }

    function createRain(container) {
      for (let i = 0; i < 40; i++) {
        const el = $('<div class="effect-rain"></div>');
        el.css({
          left: Math.random() * 100 + '%',
          top: '-50px',
          height: (Math.random() * 15 + 10) + 'px',
          animationDuration: (Math.random() * 0.8 + 0.5) + 's',
