      const el = $('<div class="effect-fog"></div>');
      container.append(el);
      const el2 = $('<div class="effect-fog" style="animation-direction:reverse; opacity:0.5; animation-duration: 25s; top:10%"></div>');
      container.append(el2);
    }

    function createWind(container) {
      for (let i = 0; i < 15; i++) {
