    function updateTimeBackground(timeStr) {
      if (!timeStr || typeof timeStr !== 'string') return;

      const regex = /(\d{1,2}):\d{2}\s*(AM|PM)?/;
      const match = timeStr.match(regex);

      if (!match) return;

      let hour = parseInt(match[1], 10);
      const period = match[2];

      if (period === 'AM') {
        if (hour === 12) hour = 0;
      } else if (period === 'PM') {
        if (hour < 12) hour += 12;
      }

      const container = $('.dating-container');
      container.removeClass('bg-morning bg-day bg-dusk bg-night');

      if (hour >= 5 && hour < 8) {
        container.addClass('bg-morning');
      } else if (hour >= 8 && hour < 17) {
        container.addClass('bg-day');
      } else if (hour >= 17 && hour < 20) {
        container.addClass('bg-dusk');
      } else {
        container.addClass('bg-night');
      }
    }

    function populateCharacterData() {
      const all_variables = getAllVariables();

      const eventName = _.get(all_variables, 'stat_data.当前事件.事件名称', '暂无事件');
      $('#main-title').text(eventName);

      const timeStr = _.get(all_variables, 'stat_data.世界状态.时间', '--:--');
      $('#val-time').text(timeStr);

      updateTimeBackground(timeStr);

      const locationStr = _.get(all_variables, 'stat_data.世界状态.地点', '未知');
      $('#val-location').text(locationStr);

      const weatherStr = _.get(all_variables, 'stat_data.世界状态.天气', '未知');
      $('#val-weather').text(weatherStr);

      $('#weather-toggle').text(isWeatherDisabled ? '☀️' : '☁️');
      $('#type-toggle').text(isTypeDisabled ? '🗓️' : '⏰');
      $('#privacy-toggle').text(isPrivacyDisabled ? '🌍' : '📍');

      const eventId = _.get(all_variables, 'stat_data.当前事件.事件编号', '');
      const eventContent = _.get(all_variables, 'stat_data.当前事件.事件内容', '...');
      if (eventId) {
          $('#event-desc').html(`<span style="color: #FFB8CC;">${eventId}:</span> ${eventContent}`);
      } else {
          $('#event-desc').text(eventContent);
      }

      const realActiveObjName = _.get(all_variables, 'stat_data.当前活跃对象', '');
      const displayObjName = manualSelectedName || realActiveObjName;

      $('#obj-name').text(displayObjName || '无对象');
      $('#obj-preview-tag').toggle(!!(manualSelectedName && manualSelectedName !== realActiveObjName));
      $('#obj-preview-tag .active-checkbox').text('☐');

      const currentObject = displayObjName ? _.get(all_variables, `stat_data.交往对象列表.${displayObjName}`, null) : null;

      let activeLust = 0;
      let targetEffect = null;
      let overlayMode = '';

      if (!currentObject) {
        $('#obj-content').hide();
        $('#obj-empty').show();
        $('#obj-age-val').hide();
        $('.eaten-checkbox').hide();
        $('#obj-tags').empty();
      } else {
        $('#obj-content').show();
        $('#obj-empty').hide();
        $('#obj-age-val').show();

        const age = _.get(currentObject, '年龄', 0);
        $('#obj-age-val').text(`${age}岁`);

        const isEaten = _.get(currentObject, '是否得吃', false);
        $('.eaten-checkbox').show();
        if (isEaten) {
            $('.eaten-checkbox').text('⚤').css({color: '#00FFCA', textShadow: '0 0 5px #00FFCA'});
        } else {
            $('.eaten-checkbox').text('♀').css({color: '#00FFCA', textShadow: 'none'});
        }

        let tagsHtml = '';
        if (!isTypeDisabled) {
            const types = _.get(currentObject, '对象类型', []);
            tagsHtml += types.map(t => `<span class="tag-base tag-type">${t}</span>`).join('');
        }

        const score = _.get(currentObject, '综合评分', 0);
        tagsHtml += `<span class="tag-base tag-score">${score}分</span>`;

        const rawCup = _.get(currentObject, '罩杯', '');
        const cupVal = String(rawCup).replace(/罩杯/g, '').trim();
        if (cupVal) {
            tagsHtml += `<span class="tag-base tag-cup">${cupVal}罩杯</span>`;
        }

        if (!isPrivacyDisabled) {
            const cash = _.get(currentObject, '现金余额', 0);
            tagsHtml += `<span class="tag-base tag-cash">￥${cash}</span>`;
        }

        const status = _.get(currentObject, '交往状态', '未知');
        tagsHtml += `<span class="tag-base tag-status">${status}</span>`;
        $('#obj-tags').html(tagsHtml);

        const aff = _.get(currentObject, '好感度', 0);
        const lust = _.get(currentObject, '情欲值', 0);
        activeLust = lust;
        const affPct = Math.min(Math.max(aff, 0), 100);
        const lustPct = Math.min(Math.max(lust, 0), 100);

        $('#bar-aff').css('width', affPct + '%');
        $('#val-aff').text(aff + '%');
        $('#bar-lust').css('width', lustPct + '%');
        $('#val-lust').text(lust + '%');

        $('#val-quick-duration').text(`${_.get(currentObject, '交往时长', 0)}天`);
        $('#val-quick-invest').text(`${_.get(currentObject, '投入金额', 0)}元`);

        if (isPrivacyDisabled) {
            $('#obj-thoughts-row').hide();
            $('#obj-hidden-row').hide();
            $('#obj-xp-row').hide();
        } else {
            $('#obj-thoughts-row').show();
            $('#obj-hidden-row').show();
            $('#obj-xp-row').show();
            $('#obj-thoughts').text(_.get(currentObject, '内心想法', '无'));
            $('#obj-hidden-text').text(_.get(currentObject, '隐瞒事项', []).join('; ') || '无');
            $('#obj-xp').text(_.get(currentObject, '特殊性癖', []).join('; ') || '无');
        }

        $('#obj-clothing').text(_.get(currentObject, '当前着装', '未知'));
        $('#obj-cash-val').text(`${_.get(currentObject, '现金余额', 0)}元`);
      }

      if (currentObject && activeLust >= 80) {
        targetEffect = 'heart';
      } else {
        if (isWeatherDisabled) {
          targetEffect = null;
          overlayMode = '';
        } else {
          if (weatherStr.includes('雪')) {
            targetEffect = 'snow';
          } else if (weatherStr.includes('雷')) {
            targetEffect = 'storm';
            overlayMode = 'mode-flash';
          } else if (weatherStr.includes('雨')) {
            targetEffect = 'rain';
          } else if (weatherStr.includes('雾')) {
            targetEffect = 'fog';
          } else if (weatherStr.includes('风')) {
            targetEffect = 'wind';
          } else if (weatherStr.includes('云')) {
            targetEffect = 'cloud';
          } else if (weatherStr.includes('阴')) {
            targetEffect = 'cloudy';
            overlayMode = 'mode-cloudy';
          } else {
            targetEffect = null;
          }
        }
      }

      if (targetEffect !== currentEffectType) {
        const container = $('#heartContainer');
        container.empty();
        currentEffectType = targetEffect;

        if (targetEffect === 'heart') createHearts(container);
        else if (targetEffect === 'snow') createSnow(container);
        else if (targetEffect === 'rain') createRain(container);
        else if (targetEffect === 'storm') createRain(container);
        else if (targetEffect === 'fog') createFog(container);
        else if (targetEffect === 'wind') createWind(container);
        else if (targetEffect === 'cloud') createClouds(container);
      }

      $('#weatherOverlay').removeClass().addClass('weather-overlay ' + overlayMode);

      const playerData = _.get(all_variables, 'stat_data.玩家数据', {});
      const pName = _.get(playerData, '姓名', '玩家');
      $('#player-name').text(pName);

      if (pName && pName.trim() !== '') {
          $('.player-gender').show();
      } else {
          $('.player-gender').hide();
      }

      $('#player-age-val').text(`${_.get(playerData, '年龄', 0)}岁`);

      let pTagsHtml = '';
      const titles = Object.keys(_.get(playerData, '称号列表', {}));
      if (titles.length > 0) {
          pTagsHtml += titles.map(t => `<span class="tag-base tag-type">${t}</span>`).join('');
      }
      pTagsHtml += `<span class="tag-base tag-score">${_.get(playerData, '综合评分', 0)}分</span>`;
      const pCash = _.get(playerData, '现金余额', 0);
      pTagsHtml += `<span class="tag-base tag-cash">￥${pCash}</span>`;
      pTagsHtml += `<span class="tag-base tag-status">${_.get(playerData, '恋爱阶段', '单身')}</span>`;
      $('#player-tags').html(pTagsHtml);

      $('#player-duration').text(`${_.get(playerData, '总相亲时长', 0)}天`);
      $('#player-count').text(`${_.get(playerData, '总相亲人数', 0)}人`);
      $('#player-money').text(`${_.get(playerData, '总花费金额', 0)}元`);
      $('#player-win').text(`${_.get(playerData, '总得吃人数', 0)}人`);

      const pHidden = _.get(playerData, '隐瞒事项', []);
      $('#player-hidden-text').text(pHidden.join('; ') || '无');
      const pXP = _.get(playerData, '特殊性癖', []);
      $('#player-xp').text(pXP.join('; ') || '无');

      renderLists(displayObjName, all_variables);
      renderActionLists();
    }

    function renderLists(currentName, all_variables) {
      const allObjects = _.get(all_variables, 'stat_data.交往对象列表', {});
      const validObjects = Object.entries(allObjects).filter(([_, v]) => v !== '待初始化' && typeof v === 'object');

      let objHtml = '';
      if(validObjects.length > 0) {
        $('#objects-header').show();
        validObjects.forEach(([name, data]) => {
           const active = name === currentName ? 'active-selected' : '';
           const score = _.get(data, '综合评分', 0);
           const status = _.get(data, '交往状态', '未知');
           const age = _.get(data, '年龄', 0);
           const types = _.get(data, '对象类型', []);

           const typeStr = (!isTypeDisabled && types.length > 0) ? types.join(' ; ') : '';
           const rawCup = _.get(data, '罩杯', '');
           const cupStr = rawCup ? String(rawCup).replace(/罩杯/g, '').trim() + '罩杯' : '';
           const duration = _.get(data, '交往时长', 0);
           const invest = _.get(data, '投入金额', 0);

           let secondLineParts = [];
           if (typeStr) secondLineParts.push(typeStr);
           if (cupStr) secondLineParts.push(cupStr);
           secondLineParts.push(`交往${duration}天`);
           secondLineParts.push(`投入${invest}元`);
           secondLineParts.push(status);

           const secondLineText = secondLineParts.join('<span style="color:#FFB8CC"> | </span>');

           objHtml += `<div class="list-item clickable ${active}" data-name="${name}">
             <div style="display:flex;justify-content:space-between;align-items:baseline;">
               <div>
                 <span style="color:#FF9DBE;font-weight:bold">${name}</span>
                 <span style="color:#FFD54F;font-size:10px;margin-left:5px;">${age}岁</span>
               </div>
               <span>★${score}</span>
             </div>
             <div style="color:#FFD54F;font-size:11px;margin-top:2px;">${secondLineText}</div>
           </div>`;
        });
        $('#list-objects').html(objHtml);
        $('#count-objects').text(`(${validObjects.length})`);
      } else {
        $('#objects-header').hide();
        $('#list-objects').hide();
        $('#list-objects').empty();
      }

      const historyData = _.get(all_variables, 'stat_data.历史对象列表', []);
      let histHtml = '';

      if(historyData.length > 0) {
        $('#history-header').show();
        historyData.forEach(item => {
           const type = !isTypeDisabled ? (item.对象类型 || '未知') : '';
           const eatenIcon = item.是否得吃 ? '⚤' : '♀';
           const eatenStyle = item.是否得吃 ? 'color:#00FFCA; text-shadow:0 0 5px #00FFCA; font-size:12px;' : 'color:#00FFCA; text-shadow:none; font-size:12px;';
           const duration = item.交往时长 || 0;
           const invest = item.投入金额 || 0;
           const failReason = item.失败原因 || '结束';

           const secondLineText = `交往${duration}天<span style="color:#FFB8CC"> | </span>投入${invest}元<span style="color:#FFB8CC"> | </span>${failReason}`;

           histHtml += `<div class="list-item">
             <div style="display:flex;justify-content:space-between;align-items:baseline;">
               <div>
                 <span style="color:#FF9DBE">${item.对象姓名}</span>
                 ${type ? `<span style="color:#FFD54F;font-size:10px;margin-left:5px;">${type}</span>` : ''}
               </div>
               <span style="${eatenStyle}">${eatenIcon}</span>
             </div>
             <div style="color:#FFD54F;font-size:11px;margin-top:2px;">${secondLineText}</div>
           </div>`;
        });
        $('#list-history').html(histHtml);
        $('#count-history').text(`(${historyData.length})`);
      } else {
        $('#history-header').hide();
        $('#list-history').hide();
        $('#list-history').empty();
      }
    }

    function renderActionLists() {
      const options = parseOptions(rawOptionsText);
      let validActions = [];

      options.forEach(item => {
        if (item.text && item.text !== '') {
          validActions.push({ label: item.type, content: item.text });
        }
      });

      if (validActions.length > 0) {
        $('#actions-header').show();
        $('#count-actions').text(`(${validActions.length})`);

        let actHtml = '';
        validActions.forEach(act => {
          const encodedContent = btoa(unescape(encodeURIComponent(act.content)));
          actHtml += `<div class="list-item action-clickable" data-content="${encodedContent}">
            <div style="display:flex; align-items:baseline; padding: 2px 0;">
               <span style="color:#FF9DBE; font-weight:bold; margin-right:6px; flex-shrink:0;">${act.label}:</span>
               <span style="color:#FFD54F; font-size:12px; line-height:1.3;">${act.content}</span>
            </div>
          </div>`;
        });
        $('#list-actions').html(actHtml);

      } else {
        $('#actions-header').hide();
        $('#list-actions').empty();
      }
    }

    async function init() {
      await waitGlobalInitialized('Mvu');
      populateCharacterData();

      eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => populateCharacterData());

      $('.dating-container').on('click', function(e) {
        if (!$(this).hasClass('collapsed') && $(e.target).closest('.header-section').length === 0) return;
        if($(e.target).closest('.collapsible-header,.collapsible-content,.clickable,.action-clickable,.section-content,.set-active-text,.edit-icon,.editable-text,.interactive-toggle').length) return;
        $('.collapsible-header').removeClass('active');
        $('.collapsible-header').find('.toggle-icon').removeClass('rotated');
        $('.collapsible-content').slideUp(200);
        $(this).toggleClass('collapsed');
      });

      $(document).on('click', '#weather-toggle', function(e) {
        e.stopPropagation();
        isWeatherDisabled = !isWeatherDisabled;
        localStorage.setItem('disableWeatherEffect', isWeatherDisabled);
        populateCharacterData();
      });

      $(document).on('click', '#type-toggle', function(e) {
        e.stopPropagation();
        isTypeDisabled = !isTypeDisabled;
        localStorage.setItem('disableTypeDisplay', isTypeDisabled);
        populateCharacterData();
      });

      $(document).on('click', '#privacy-toggle', function(e) {
        e.stopPropagation();
        isPrivacyDisabled = !isPrivacyDisabled;
        localStorage.setItem('disablePrivacyDisplay', isPrivacyDisabled);
        populateCharacterData();
      });

      $('.collapsible-header').on('click', function(e) {
        e.stopPropagation();
        const content = $(this).next('.collapsible-content');
        const isActive = $(this).hasClass('active');
        $('.collapsible-header').removeClass('active');
        $('.collapsible-header').find('.toggle-icon').removeClass('rotated');
        $('.collapsible-content').not(content).slideUp(200);
        if(!isActive) {
          $(this).addClass('active');
          $(this).find('.toggle-icon').addClass('rotated');
          content.slideDown(200);
        } else {
          content.slideUp(200);
        }
      });

      $('#list-objects').on('click', '.clickable', function(e){
        e.stopPropagation();
        const name = $(this).attr('data-name');
        if(name) { manualSelectedName = name; populateCharacterData(); }
      });

      $('#list-actions').on('click', '.action-clickable', function(e){
        e.stopPropagation();
        const encodedContent = $(this).attr('data-content');
        $(this).addClass('active-selected').siblings().removeClass('active-selected');
        if(encodedContent) {
            const content = decodeURIComponent(escape(atob(encodedContent)));
            if (typeof triggerSlash === 'function') {
                triggerSlash(`/setinput ${content}`);
            }
        }
      });

      $(document).on('click', '.set-active-text', function(e) {
          e.stopPropagation();
          $(this).find('.active-checkbox').text('☑');

          if (manualSelectedName && typeof eventEmit === 'function') {
              let msgId = 'latest';
              try { msgId = getCurrentMessageId(); } catch(e) {}
              eventEmit('XQ_UI_UPDATE_VAR', {
                  type: 'setActive',
                  name: manualSelectedName,
                  messageId: msgId
              });
          }
      });

      $(document).on('click', '.edit-icon', function(e) {
          e.stopPropagation();
          const wrapper = $(this).closest('.editable-wrapper');
          const textSpan = wrapper.find('.editable-text');
          const isEditing = textSpan.attr('contenteditable') === 'true';

          if (!isEditing) {
              textSpan.attr('contenteditable', 'true').focus();

              const el = textSpan[0];
              const range = document.createRange();
              const sel = window.getSelection();
              range.selectNodeContents(el);
              range.collapse(false);
              sel.removeAllRanges();
              sel.addRange(range);

              $(this).addClass('editing').text('✔');
          } else {
              textSpan.removeAttr('contenteditable');
              $(this).removeClass('editing').text('✎');
          }
      });

      $(document).on('blur', '.editable-text[contenteditable="true"]', function() {
          $(this).removeAttr('contenteditable');
          $(this).siblings('.edit-icon').removeClass('editing').text('✎');

          const id = $(this).attr('id');
          const text = $(this).text().trim();
          const arrayData = text ? text.split(/[，,。.；;\s]+/).filter(Boolean) : [];

          let targetType = '';
          let targetName = '';
          let field = '';

          if (id === 'obj-hidden-text' || id === 'obj-xp') {
              targetType = 'object';
              targetName = $('#obj-name').text();
              if (targetName === '无对象') return;
              field = id === 'obj-hidden-text' ? '隐瞒事项' : '特殊性癖';
          } else if (id === 'player-hidden-text' || id === 'player-xp') {
              targetType = 'player';
              field = id === 'player-hidden-text' ? '隐瞒事项' : '特殊性癖';
          }

          if (targetType && typeof eventEmit === 'function') {
              let msgId = 'latest';
              try { msgId = getCurrentMessageId(); } catch(e) {}
              eventEmit('XQ_UI_UPDATE_VAR', {
                  type: 'updateArray',
                  targetType: targetType,
                  targetName: targetName,
                  field: field,
                  data: arrayData,
                  messageId: msgId
              });
          }
      });
    }

    $(errorCatched(init));
  </script>
</head>
<body>

<div class="dating-container collapsed">
  <div class="weather-overlay" id="weatherOverlay"></div>
  <div class="heart-bg" id="heartContainer"></div>
  <div class="collapsed-heart">❤</div>

  <div class="expanded-content">

    <div class="header-section">
      <span class="main-title" id="main-title">加载中...</span>
      <div class="info-line">
        <span class="info-item"><span class="icon-label interactive-toggle" id="type-toggle" title="点击切换类型显示">⏰</span> <span style="line-height: 1.4;" id="val-time">--:--</span></span>
      </div>
      <div class="info-line between">
        <span class="info-item"><span class="icon-label interactive-toggle" id="privacy-toggle" title="点击切换隐私显示">📍</span><span style="line-height: 1.4;" id="val-location">未知</span></span>
        <span class="info-item"><span class="icon-label interactive-toggle" id="weather-toggle" title="点击切换天气特效">☁️</span><span style="line-height: 1.4;" id="val-weather">未知</span></span>
      </div>
      <div class="event-desc-text" id="event-desc"></div>
    </div>

    <div class="char-header">
      <div class="name-wrapper">
        <span class="eaten-checkbox">⚤</span>
        <span class="char-name" id="obj-name">无对象</span>
        <span class="age-text" id="obj-age-val">0岁</span>
      </div>

      <div id="obj-preview-tag" style="display:none; text-align:center; margin-top:2px;">
        <span class="set-active-text" style="font-size: 11px; color: #FFD54F; cursor:pointer; user-select:none;">设为活跃对象 <span class="active-checkbox" style="color: #00FFCA; text-shadow: 0 0 5px #00FFCA; font-size:12px;">☐</span></span>
      </div>

      <div class="tag-container" id="obj-tags"></div>
    </div>

    <div id="obj-empty" style="text-align:center;opacity:0.5;font-size:12px;margin-bottom:10px;">(静待缘分)</div>

    <div id="obj-content" style="display:none; margin-bottom:5px;">
      <div class="progress-group">
        <div class="progress-item">
          <span class="progress-name">好感度</span>
          <div class="progress-container"><div id="bar-aff" class="progress-bar"></div></div>
          <span id="val-aff" class="progress-val">0%</span>
        </div>
        <div class="progress-item">
          <span class="progress-name">情欲值</span>
          <div class="progress-container"><div id="bar-lust" class="progress-bar"></div></div>
          <span id="val-lust" class="progress-val">0%</span>
        </div>
      </div>
      <div class="quick-stats-row">
         <span class="quick-stat-item">📅 <span id="val-quick-duration"></span></span>
         <span class="quick-stat-item">💸 <span id="val-quick-invest"></span></span>
      </div>
      <div class="detail-list">
        <div class="info-row-full" id="obj-thoughts-row">
          <span class="info-label">想法:</span> <span class="info-val-thoughts" id="obj-thoughts"></span>
        </div>
        <div class="info-row-full">
          <span class="info-label">着装:</span> <span class="info-val" id="obj-clothing"></span>
        </div>
        <div class="info-row-full" id="obj-hidden-row">
          <span class="info-label">隐瞒:</span>
          <div class="editable-wrapper">
            <span class="info-val editable-text" id="obj-hidden-text"></span>
            <span class="edit-icon">✎</span>
          </div>
        </div>
        <div class="info-row-full" id="obj-xp-row">
          <span class="info-label">性癖:</span>
          <div class="editable-wrapper">
            <span class="info-val editable-text" id="obj-xp"></span>
            <span class="edit-icon">✎</span>
          </div>
        </div>

      </div>
    </div>

    <div class="player-section">
      <div class="char-header">
        <div class="name-wrapper">
          <span class="player-gender">♂</span>
          <span class="char-name" id="player-name">玩家</span>
          <span class="age-text" id="player-age-val">0岁</span>
        </div>
        <div class="tag-container" id="player-tags"></div>
      </div>
      <div class="player-stats-grid">
         <div class="player-stat-cell">
            <span class="player-stat-label">相亲:</span> <span class="player-stat-val" id="player-duration"></span>
         </div>
         <div class="player-stat-cell">
            <span class="player-stat-label">阅人:</span> <span class="player-stat-val" id="player-count"></span>
         </div>
         <div class="player-stat-cell">
            <span class="player-stat-label">花费:</span> <span class="player-stat-val" id="player-money"></span>
         </div>
         <div class="player-stat-cell">
            <span class="player-stat-label">战绩:</span> <span class="player-stat-val" id="player-win"></span>
         </div>
      </div>
      <div class="detail-list">
         <div class="info-row-full">
            <span class="info-label">隐瞒:</span>
            <div class="editable-wrapper">
              <span class="info-val editable-text" id="player-hidden-text"></span>
              <span class="edit-icon">✎</span>
            </div>
         </div>
         <div class="info-row-full">
            <span class="info-label">性癖:</span>
            <div class="editable-wrapper">
              <span class="info-val editable-text" id="player-xp"></span>
              <span class="edit-icon">✎</span>
            </div>
         </div>
      </div>
    </div>

    <div class="collapsible-header" id="objects-header">
      <span class="collapsible-title">对象列表 <span id="count-objects" style="opacity:0.6;font-size:10px"></span></span>
      <span class="toggle-icon">◀</span>
    </div>
    <div class="collapsible-content" id="list-objects"></div>
    <div class="collapsible-header" id="history-header">
