                <div class="dynamic-island"></div>
                <div class="subpage-title" id="chat-title-icon" onclick="openChatState()" style="cursor: pointer; display: flex; align-items: center; justify-content: flex-end; width: 40px; height: 100%; right: 24px; position: absolute;">
                    <svg id="status-svg-icon" viewBox="0 0 24 24" style="width: 24px; height: 24px; fill: var(--text-main);"></svg>
                </div>
            </div>

            <div class="chat-content" id="chat-content-area">
                <!-- 聊天记录动态渲染区域 -->
            </div>

            <div class="chat-input-area">
                <textarea class="chat-input-box" id="chat-input" placeholder="说点什么吧..." rows="1" onkeydown="handleInputKeyDown(event)" oninput="autoResizeInput(this)"></textarea>
                <button class="btn-send" onclick="sendMessage()">发送</button>
            </div>
        </div>

        <!-- 三级页面：状态页特有样式 -->
        <div id="subpage-chat-state" class="subpage">
            <div class="subpage-header">
                <div class="btn-back" onclick="closeChatState()">
                    <svg viewBox="0 0 24 24"><path d="M15.41 7.41L14 6l-6 6 6 6 1.41-1.41L10.83 12z"/></svg>
                </div>
                <div class="dynamic-island"></div>
                <div class="subpage-title" id="chat-state-title">状态</div>
            </div>
            <div class="subpage-content">
                <div class="settings-list">
                    <div class="settings-item">
                        <span class="settings-label">加入黑名单</span>
                        <label class="ios-switch">
                            <input type="checkbox" id="setting-block-user" onchange="toggleBlockUser(this.checked)">
                            <span class="ios-switch-slider"></span>
                        </label>
                    </div>
                </div>
                <button class="settings-btn-action" onclick="deleteChat()">删除</button>
            </div>
        </div>

    </div>

    <script>
        // ====== 全屏缩放逻辑 ======
        function toggleFullscreen() {
            if (!document.fullscreenElement) {
                if (document.body.requestFullscreen) {
                    document.body.requestFullscreen();
                } else if (document.body.webkitRequestFullscreen) {
                    document.body.webkitRequestFullscreen();
                }
            } else {
                if (document.exitFullscreen) {
                    document.exitFullscreen();
                }
            }
        }

        function handleFullscreenChange() {
            const isFullscreen = !!document.fullscreenElement;
            const btns = document.querySelectorAll('.btn-fullscreen');
            const dynamicStyle = document.getElementById('dynamic-fullscreen-style');

            const iconEnter = `<svg viewBox="0 0 24 24"><path d="M7 14H5v5h5v-2H7v-3zm-2-4h2V7h3V5H5v5zm12 7h-3v2h5v-5h-2v3zM14 5v2h3v3h2V5h-5z"/></svg>`;
            const iconExit = `<svg viewBox="0 0 24 24"><path d="M5 16h3v3h2v-5H5v2zm3-8H5v2h5V5H8v3zm6 11h2v-3h3v-2h-5v5zm2-11V5h-2v5h5V8h-3z"/></svg>`;

            btns.forEach(btn => {
                btn.innerHTML = isFullscreen ? iconExit : iconEnter;
            });

            if (dynamicStyle) {
                if (isFullscreen) {
                    dynamicStyle.textContent = `
                        body:fullscreen .mes:not([mesid="0"]) { display: none !important; }
                        body:fullscreen #chat { padding-bottom: 0 !important; }
                        body:fullscreen #bottom-bar { display: none !important; }
                    `;
                } else {
                    dynamicStyle.textContent = '';
                }
            }
        }

        function injectFullscreenButtons() {
            const islands = document.querySelectorAll('.dynamic-island');
            const iconEnter = `<svg viewBox="0 0 24 24"><path d="M7 14H5v5h5v-2H7v-3zm-2-4h2V7h3V5H5v5zm12 7h-3v2h5v-5h-2v3zM14 5v2h3v3h2V5h-5z"/></svg>`;

            islands.forEach(island => {
                if (window.getComputedStyle(island).position === 'static') {
                    island.style.position = 'relative';
                }
                const btn = document.createElement('div');
                btn.className = 'btn-fullscreen';
                btn.title = '全屏切换';
                btn.innerHTML = iconEnter;
                btn.addEventListener('click', (e) => {
                    e.stopPropagation();
                    toggleFullscreen();
                });
                island.appendChild(btn);
            });

            document.addEventListener('fullscreenchange', handleFullscreenChange);
            document.addEventListener('webkitfullscreenchange', handleFullscreenChange);
        }

        // === 基础安全辅助函数 ===
        // 安全获取顶级 window 对象，防止跨域或嵌套层级导致的崩溃
        function getTopWindow() {
            try {
                return window.top || window.parent || window;
            } catch (e) {
                return window;
            }
        }

        // 统一的安全跨层通信函数
        function sendTavernEvent(eventName, data = {}) {
            try {
                const topW = getTopWindow();
                // 使用最安全的 postMessage 向顶层窗口发送消息
                if (topW !== window) {
                    topW.postMessage({
                        type: eventName,
                        detail: data
                    }, '*');
                } else {
                    // 如果碰巧在同层，用 CustomEvent 兜底
                    const evt = new CustomEvent(eventName, { detail: data });
                    window.dispatchEvent(evt);
                }
            } catch (e) {
                console.error(`[心遇前端] 事件 ${eventName} 派发异常:`, e);
            }
        }

        // 时间解析和格式化辅助函数
        function parseGameTime(timeStr) {
            if (!timeStr) return null;
            const regex = /(?:(\d{4})年)?(\d{1,2})月(\d{1,2})日\s+(\d{1,2}):(\d{1,2})/;
            const match = timeStr.match(regex);
            if (match) {
                const year = match[1] ? parseInt(match[1]) : new Date().getFullYear();
                const month = parseInt(match[2]) - 1;
                const day = parseInt(match[3]);
                const hour = parseInt(match[4]);
                const minute = parseInt(match[5]);
                return new Date(year, month, day, hour, minute).getTime();
            }
            const parsed = Date.parse(timeStr);
            if (!isNaN(parsed)) return parsed;
            return null;
        }

        function formatRelativeTime(msgTimestamp, latestTimestamp) {
            if (!msgTimestamp || !latestTimestamp) return "未知时间";
            const diff = latestTimestamp - msgTimestamp;
            const diffMinutes = Math.floor(diff / (60 * 1000));
            const msgDate = new Date(msgTimestamp);
            const latestDate = new Date(latestTimestamp);
            const formatHHmm = (d) => `${d.getHours().toString().padStart(2, '0')}:${d.getMinutes().toString().padStart(2, '0')}`;
            const formatMMdd = (d) => `${(d.getMonth() + 1)}月${d.getDate()}日`;

            if (diffMinutes < 1) return "刚刚";

            const isSameDay = msgDate.getDate() === latestDate.getDate() && msgDate.getMonth() === latestDate.getMonth() && msgDate.getFullYear() === latestDate.getFullYear();
            const yesterday = new Date(latestDate);
            yesterday.setDate(latestDate.getDate() - 1);
            const isYesterday = msgDate.getDate() === yesterday.getDate() && msgDate.getMonth() === yesterday.getMonth() && msgDate.getFullYear() === yesterday.getFullYear();

            if (isSameDay) return formatHHmm(msgDate);
            if (isYesterday) return `昨天 ${formatHHmm(msgDate)}`;
            if (diff < 7 * 24 * 60 * 60 * 1000) {
                const weekDays = ['日', '一', '二', '三', '四', '五', '六'];
                return `星期${weekDays[msgDate.getDay()]} ${formatHHmm(msgDate)}`;
            }
            if (msgDate.getFullYear() === latestDate.getFullYear()) return `${formatMMdd(msgDate)} ${formatHHmm(msgDate)}`;
            return `${msgDate.getFullYear()}年${formatMMdd(msgDate)} ${formatHHmm(msgDate)}`;
        }

        // 获取当前聊天ID
        function getStChatId() {
            try {
                const topW = getTopWindow();
                if (typeof topW.SillyTavern?.getCurrentChatId === 'function') {
                    return topW.SillyTavern.getCurrentChatId();
                }
            } catch (e) {
                console.warn("[心遇前端] 未能获取聊天ID:", e);
            }
            return "default";
        }

        // 获取当前楼层ID
        function getStMessageId() {
            try {
                if (typeof getCurrentMessageId === 'function') {
                    return getCurrentMessageId();
                }
                const topW = getTopWindow();
                if (topW && topW.TavernHelper && typeof topW.TavernHelper.getMessageId === 'function') {
                    return topW.TavernHelper.getMessageId(window.name);
                }
            } catch (e) {
                console.warn("[心遇前端] 未能获取楼层ID:", e);
            }
            return null;
        }

        // 独立的前端显示层数读取
        function getDisplayLayers() {
            const defaultLayers = 64;
            const configKey = 'BlindDate_Display_Layers';

            const localVal = localStorage.getItem(configKey);
            if (localVal !== null) {
                const parsed = parseInt(localVal);
                if (!isNaN(parsed) && parsed > 0) return parsed;
            }

            return defaultLayers;
        }

        // 获取底层最近动态层数的纯净文本
        function getRecentLayersText() {
            let recentMsgs = [];
            try {
                const topW = getTopWindow();
                if (topW.TavernHelper && topW.TavernHelper.getChatMessages) {
                    let currentFloorId = getStMessageId();
                    const targetId = (currentFloorId !== null && currentFloorId !== undefined)
                                     ? currentFloorId
                                     : topW.TavernHelper.getLastMessageId();

                    const displayLayers = getDisplayLayers();
                    const startId = Math.max(0, targetId - (displayLayers - 1));
                    recentMsgs = topW.TavernHelper.getChatMessages(startId + '-' + targetId);

                    return recentMsgs.map((m, index) => {
                        let rawText = m.message;
                        if (typeof topW.TavernHelper.formatAsTavernRegexedString === 'function') {
                            let source = m.role === 'user' ? 'user_input' : 'ai_output';
                            rawText = topW.TavernHelper.formatAsTavernRegexedString(
                                rawText,
                                source,
                                'prompt',
                                { depth: recentMsgs.length - 1 - index }
                            );
                        }
                        return rawText;
                    }).join("\n\n");
                }
            } catch (e) {
                console.error("[心遇前端] 获取聊天记录失败:", e);
            }
            return "";
        }

        // 获取底层最近动态层数的消息对象 (包含 message_id)
        function getRecentMessages() {
            let recentMsgs = [];
            try {
                const topW = getTopWindow();
                if (topW.TavernHelper && topW.TavernHelper.getChatMessages) {
                    let currentFloorId = getStMessageId();
                    const targetId = (currentFloorId !== null && currentFloorId !== undefined)
                                     ? currentFloorId
                                     : topW.TavernHelper.getLastMessageId();

                    const displayLayers = getDisplayLayers();
                    const startId = Math.max(0, targetId - (displayLayers - 1));
                    let rawMsgs = topW.TavernHelper.getChatMessages(startId + '-' + targetId);

                    recentMsgs = rawMsgs.map((m, index) => {
                        let rawText = m.message;
                        if (typeof topW.TavernHelper.formatAsTavernRegexedString === 'function') {
                            let source = m.role === 'user' ? 'user_input' : 'ai_output';
                            rawText = topW.TavernHelper.formatAsTavernRegexedString(
                                rawText,
                                source,
                                'prompt',
                                { depth: rawMsgs.length - 1 - index }
                            );
                        }
                        return { ...m, message: rawText, mes: rawText };
                    });
                }
            } catch (e) {
                console.error("[心遇前端] 获取聊天记录对象失败:", e);
            }
            return recentMsgs;
        }

        // 无感追加文本到当前楼层末尾
        async function appendToFloorMessage(msgId, appendText) {
            if (msgId === null) return;
            let currentText = "";
            try {
                const topW = getTopWindow();
                const getChatMsgs = topW.TavernHelper?.getChatMessages;
                if (getChatMsgs) {
                    const messages = getChatMsgs(msgId);
                    if (messages && messages.length > 0) {
                        currentText = messages[0].message || "";
                    }
                }
            } catch (e) {
                console.warn("[心遇前端] 读取当前楼层文本失败:", e);
            }

            const newText = currentText + appendText;
            try {
                const topW = getTopWindow();
                const setMsgs = topW.TavernHelper?.setChatMessages;
                if (setMsgs) {
                    await setMsgs([{ message_id: msgId, message: newText }], { refresh: 'none' });
                }
            } catch(e) {
                console.error("[心遇前端] 写入楼层文本失败:", e);
            }
        }

        // 获取玩家的当前名称
        function getPlayerNameFromVars() {
            try {
                let msgId = getStMessageId();
                const topW = getTopWindow();
                if(msgId !== null && topW.Mvu && topW.Mvu.getMvuData) {
                     const mvuData = topW.Mvu.getMvuData({ type: 'message', message_id: msgId });
                     if(mvuData && mvuData.stat_data && mvuData.stat_data['玩家数据'] && mvuData.stat_data['玩家数据']['姓名']) {
                         return mvuData.stat_data['玩家数据']['姓名'];
                     }
                }
            } catch(e) {
                console.warn("[心遇前端] 获取玩家姓名失败:", e);
            }
            return "玩家";
        }

        // ====== 真实头像链接生成器及解析函数 ======
        function parseImagePrompt(promptStr, defaultSize) {
            let desc = promptStr || "暂无";
            let width = defaultSize;
            let height = defaultSize;

            // 从末尾匹配: 任意文本 + 逗号 + 宽度(数字) + 逗号 + 高度(数字)
            const match = promptStr.match(/(.*?)\s*,\s*(\d+)\s*,\s*(\d+)\s*$/);

            if (match) {
                desc = match[1].trim();
                width = parseInt(match[2]);
                height = parseInt(match[3]);
            }

            return { desc, width, height };
        }

        function getRealAvatarUrl(prompt) {
            if (!prompt || prompt === "暂无" || prompt.trim() === "") return "";
            const { desc, width, height } = parseImagePrompt(prompt.trim(), 1024);
            const safePrompt = encodeURIComponent(desc);
            return `https://picsum.photos/seed/${safePrompt}/${width}/${height}`;
        }

        // ====== 锁屏事件派发与销毁逻辑 ======
        async function lockScreen() {
            sendTavernEvent('XQ_LockScreen');

            const msgId = getStMessageId();
            if (msgId === null) return;

            let currentText = "";
            try {
                const topW = getTopWindow();
                const getChatMsgs = topW.TavernHelper?.getChatMessages;
                if (getChatMsgs) {
                    const messages = getChatMsgs(msgId);
                    if (messages && messages.length > 0) {
                        currentText = messages[0].message || "";
                    }
                }
            } catch (e) {
                console.warn("[心遇前端] 读取当前楼层文本失败:", e);
            }

            const cleanedText = currentText.replace(/💬\n?/g, '').trim();

            try {
                const topW = getTopWindow();
                if (cleanedText === "") {
                    const delMsgs = topW.TavernHelper?.deleteChatMessages;
                    if (delMsgs) {
                        await delMsgs([msgId]);
                    }
                } else {
                    const setMsgs = topW.TavernHelper?.setChatMessages;
                    if (setMsgs) {
                        await setMsgs([{ message_id: msgId, message: cleanedText }], { refresh: 'affected' });
                    }
                }
            } catch (e) {
                console.warn("[心遇前端] 刷新或删楼失败:", e);
            }
        }

        // ====== VIP与资产系统逻辑 ======
        let realVipLevel = 0;
        let isHackMode = false;
        const vipPrices = [0, 1000, 10000, 100000];

        function getEffectiveVipLevel() {
            if (isHackMode) return 3;
            return realVipLevel;
        }

        function getAvailableMoneyInfo() {
            let money = 0;
            let isFromCache = false;
            let msgId = getStMessageId();

            try {
                const topW = getTopWindow();
                if (topW.TavernHelper) {
                    let targetMsgId = msgId !== null ? msgId : 'latest';
                    const vars = topW.TavernHelper.getVariables({type: 'message', message_id: targetMsgId});
                    if (topW._ && topW._.get) {
                        money = topW._.get(vars, 'stat_data.玩家数据.现金余额', 0);
                    } else if (vars && vars.stat_data && vars.stat_data['玩家数据']) {
                        money = vars.stat_data['玩家数据']['现金余额'] || 0;
                    }
                }
            } catch (e) {
                console.warn("[心遇前端] 变量系统读取资金异常，将启动缓存兜底", e);
            }

            if (money === 0 && msgId === 0) {
                try {
                    const cacheStr = localStorage.getItem('SillyTavern_BlindDate_Cache');
                    if (cacheStr) {
                        const cacheData = JSON.parse(cacheStr);
                        money = Number(cacheData['v_money']) || 0;
                        if (money > 0) {
                            isFromCache = true;
                        }
                    }
                } catch (e) {}
            }
            return { money: money, isFromCache: isFromCache, currentMsgId: msgId };
        }

        function loadVipState() {
            try {
                let msgId = getStMessageId();
                const topW = getTopWindow();
                if (topW.TavernHelper) {
                    let targetMsgId = msgId !== null ? msgId : 'latest';
                    const vars = topW.TavernHelper.getVariables({type: 'message', message_id: targetMsgId});
                    if (topW._ && topW._.get) {
                        realVipLevel = topW._.get(vars, 'stat_data.玩家数据.$会员等级', 0);
                    } else if (vars && vars.stat_data && vars.stat_data['玩家数据']) {
                        realVipLevel = vars.stat_data['玩家数据']['$会员等级'] || 0;
                    }
                }

                const storedHack = localStorage.getItem('BlindDate_Hack_Mode');
                if (storedHack !== null) {
                    isHackMode = storedHack === 'true';
                    const hackCheckbox = document.getElementById('setting-hack-mode');
                    if(hackCheckbox) hackCheckbox.checked = isHackMode;
                }
                updateProfileVipBadge();
            } catch (e) {
                console.warn("[心遇前端] 加载VIP状态失败:", e);
            }
        }

        function updateProfileVipBadge() {
            const badge = document.getElementById('profile-vip-badge');
            const banner = document.getElementById('profile-vip-banner');
            if(!badge || !banner) return;

            const effectiveVip = getEffectiveVipLevel();

            if (effectiveVip >= 3) {
                banner.style.display = 'none';
            } else {
                banner.style.display = 'flex';
            }

            badge.className = 'profile-vip-badge';
            badge.style = '';

            if(effectiveVip === 0) {
                badge.textContent = 'VIP 0';
                badge.classList.add('vip-0');
            } else {
                if (isHackMode && effectiveVip === 3) {
                    badge.textContent = 'GM';
                } else {
                    badge.textContent = 'VIP ' + effectiveVip;
                }
                if(effectiveVip === 1) {
                    badge.style.background = 'linear-gradient(135deg, #ffd700, #ff8c00)';
                    badge.style.color = '#ffffff';
                    badge.style.boxShadow = '0 2px 4px rgba(255,140,0,0.2)';
                } else if(effectiveVip === 2) {
                    badge.style.background = 'linear-gradient(135deg, #e5e4e2, #b0c4de)';
                    badge.style.color = '#ffffff';
                    badge.style.boxShadow = '0 2px 4px rgba(176,196,222,0.4)';
                } else if(effectiveVip === 3) {
                    badge.style.background = 'linear-gradient(135deg, #2c2c2c, #1a1a1a)';
                    badge.style.color = '#ffd700';
                    badge.style.boxShadow = '0 2px 4px rgba(0,0,0,0.3)';
                }
            }
        }

        function renderVipMenu() {
            const vipCards = document.querySelectorAll('.vip-card');
            const effectiveVip = getEffectiveVipLevel();

            vipCards.forEach((card, index) => {
                const targetLevel = index + 1;
                const btn = card.querySelector('.btn-buy');
                const priceSpan = card.querySelector('.vip-price');

                if (btn.innerText === "余额不足" || btn.innerText === "处理中..." || btn.innerText === "失败") {
                    btn.disabled = false;
                    btn.innerText = (effectiveVip > 0) ? "升级" : "开通";
                }

                if (effectiveVip >= targetLevel) {
                    card.classList.add('disabled');
                    btn.style.display = 'none';
                    priceSpan.style.color = 'var(--text-hint)';
                } else {
                    card.classList.remove('disabled');
                    btn.style.display = 'block';
                    priceSpan.style.color = '#ff3b30';

                    const diffPrice = vipPrices[targetLevel] - vipPrices[realVipLevel];
                    priceSpan.textContent = '￥' + diffPrice;

                    if (effectiveVip > 0) {
                        btn.textContent = '升级';
                    } else {
                        btn.textContent = '开通';
                    }
                }
            });
        }

        async function buyVip(level, btnElement) {
            const requiredMoney = vipPrices[level] - vipPrices[realVipLevel];
            const moneyInfo = getAvailableMoneyInfo();

            if (moneyInfo.money >= requiredMoney) {
                btnElement.innerText = "处理中...";
                btnElement.disabled = true;

                try {
                    sendTavernEvent('XQ_UI_UPDATE_VAR', {
                        type: 'buyVip',
                        messageId: moneyInfo.currentMsgId,
                        amount: requiredMoney,
                        targetLevel: level,
                        isFromCache: moneyInfo.isFromCache,
                        initialMoney: moneyInfo.isFromCache ? moneyInfo.money : 0
                    });

                    // 延迟 200 毫秒后直接主动刷新，不再死等广播
                    setTimeout(() => {
                        loadVipState();
                        renderVipMenu();
                        renderMessageList();
                    }, 200);

                } catch(e) {
                    console.error("[心遇前端] VIP扣费发送事件失败:", e);
                    btnElement.innerText = "失败";
                    btnElement.disabled = false;
                }
            } else {
                const oldText = btnElement.innerText;
                btnElement.innerText = "余额不足";
                setTimeout(() => {
                    if(btnElement.innerText === "余额不足") {
                        btnElement.innerText = oldText;
                    }
                }, 2000);
            }
        }

        function openVipMenu() {
            renderVipMenu();
            const subVip = document.getElementById('subpage-vip');
            if(subVip) subVip.style.display = 'flex';
        }

        function closeVipMenu() {
            const subVip = document.getElementById('subpage-vip');
            if(subVip) subVip.style.display = 'none';
        }

        // --- 设置页面逻辑 ---
        function toggleDarkMode(isChecked) {
            if (isChecked) {
                document.documentElement.setAttribute('data-theme', 'dark');
            } else {
                document.documentElement.removeAttribute('data-theme');
            }
            try {
                localStorage.setItem('BlindDate_Dark_Mode', isChecked);
            } catch(e) {}
        }

        function openSettings() {
            const subSettings = document.getElementById('subpage-settings');
            if(subSettings) subSettings.style.display = 'flex';
        }

        function closeSettings() {
            const subSettings = document.getElementById('subpage-settings');
            if(subSettings) subSettings.style.display = 'none';
        }

        function toggleHackMode(isChecked) {
            isHackMode = isChecked;
            try {
                localStorage.setItem('BlindDate_Hack_Mode', isHackMode);
            } catch(e) {}
            updateProfileVipBadge();
            renderCurrentCard();
        }

        function toggleAutoClear(isChecked) {
            try {
                localStorage.setItem('BlindDate_Auto_Clear', isChecked);
            } catch(e) {}
        }

        function saveConfig() {
            updateMatchConfig();
            const btn = document.querySelector('.settings-btn-action[onclick="saveConfig()"]');
            if (btn) {
                const oldText = btn.innerText;
                btn.innerText = "已保存";
                setTimeout(() => {
                    if (btn.innerText === "已保存") {
                        btn.innerText = oldText;
                    }
                }, 2000);
            }
        }

        function updateMatchConfig() {
            const batchInput = document.getElementById('setting-match-batch');
            const thresholdInput = document.getElementById('setting-match-threshold');
            if(!batchInput || !thresholdInput) return;

            let batchSize = parseInt(batchInput.value);
            if (isNaN(batchSize) || batchSize < 1) batchSize = 10;

            let threshold = parseInt(thresholdInput.value);
            if (isNaN(threshold) || threshold < 1) threshold = 3;

            const offsetInput = document.getElementById('setting-log-offset');
            let displayLayers = 64;
            if (offsetInput) {
                displayLayers = parseInt(offsetInput.value);
                if (isNaN(displayLayers) || displayLayers < 1) displayLayers = 64;
            }

            try {
                localStorage.setItem('BlindDate_Match_BatchSize', batchSize);
                localStorage.setItem('BlindDate_Match_Threshold', threshold);
                localStorage.setItem('BlindDate_Display_Layers', displayLayers);
            } catch(e) {}

            sendTavernEvent('XY_ConfigUpdated');
        }

        function clearData() {
            const btn = document.getElementById('btn-clear-data');
            if(!btn) return;

            try {
                // 只清理当前前端应用产生的临时队列和游标缓存
                localStorage.removeItem('SillyTavern_BlindDate_Queue'); // 推荐列表
                localStorage.removeItem('SillyTavern_BlindDate_Liked'); // 喜欢列表
                localStorage.removeItem('SillyTavern_BlindDate_Liked_Read'); // 喜欢列表已读记录
                localStorage.removeItem('SillyTavern_BlindDate_Msg_Cursor'); // 消息游标

                // 通知后端清空内存中的队列
                sendTavernEvent('XQ_ClearQueue');
            } catch(e) {
                console.error("[心遇前端] 清理本地缓存失败:", e);
            }

            renderCurrentCard();
            renderLikedGrid();
            renderMessageList();

            const oldText = btn.innerText;
            btn.innerText = "已清理";
            setTimeout(() => {
                if(btn.innerText === "已清理") {
                    btn.innerText = oldText;
                }
            }, 2000);
        }

        // ====== 辅助工具函数：获取对象微信数组 ======
        function extractFlashMsgsForUser(targetName, recentText) {
            const safeName = targetName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const regex = new RegExp(`<微信\\s+(?:user|from)="${safeName}">([\\s\\S]*?)<\\/微信>`, 'gi');
            let msgs = [];
            let match;
            while ((match = regex.exec(recentText)) !== null) {
                msgs.push(match[1].trim().substring(0, 8));
            }
            return msgs;
        }

        // ====== 喜欢页已读记录 ======
        function getLikedReadList() {
            return JSON.parse(localStorage.getItem('SillyTavern_BlindDate_Liked_Read') || '[]');
        }

        function markLikedAsRead(targetName) {
            let readList = getLikedReadList();
            if (!readList.includes(targetName)) {
                readList.push(targetName);
                localStorage.setItem('SillyTavern_BlindDate_Liked_Read', JSON.stringify(readList));
            }
        }

        function removeLikedFromRead(targetName) {
            let readList = getLikedReadList();
            const index = readList.indexOf(targetName);
            if (index !== -1) {
                readList.splice(index, 1);
                localStorage.setItem('SillyTavern_BlindDate_Liked_Read', JSON.stringify(readList));
            }
        }

        // ====== 消息游标管理 ======
        function getUnreadMsgCount(targetName, recentText) {
            const cursorDict = JSON.parse(localStorage.getItem('SillyTavern_BlindDate_Msg_Cursor') || '{}');
            const lastCursor = cursorDict[targetName];

            const msgs = extractFlashMsgsForUser(targetName, recentText);
            if (msgs.length === 0) return 0;

            if (!lastCursor) {
                return msgs.length;
            }

            for (let i = msgs.length - 1; i >= 0; i--) {
                if (msgs[i] === lastCursor) {
                    return msgs.length - 1 - i;
                }
            }

            return msgs.length;
        }

        function markMsgAsRead(targetName) {
            const recentText = getRecentLayersText();
            const msgs = extractFlashMsgsForUser(targetName, recentText);
            if (msgs.length > 0) {
                const cursorDict = JSON.parse(localStorage.getItem('SillyTavern_BlindDate_Msg_Cursor') || '{}');
                cursorDict[targetName] = msgs[msgs.length - 1];
                localStorage.setItem('SillyTavern_BlindDate_Msg_Cursor', JSON.stringify(cursorDict));
            }
        }

        // ====== 拉黑系统逻辑 ======
        function isBlocked(targetName) {
            try {
                let msgId = getStMessageId();
                const topW = getTopWindow();
                if (topW.TavernHelper) {
                    let targetMsgId = msgId !== null ? msgId : 'latest';
                    const vars = topW.TavernHelper.getVariables({type: 'message', message_id: targetMsgId});
                    let blacklist = [];
                    if (topW._ && topW._.get) {
                        blacklist = topW._.get(vars, 'stat_data.玩家数据.$拉黑列表', []);
                    } else if (vars && vars.stat_data && vars.stat_data['玩家数据']) {
                        blacklist = vars.stat_data['玩家数据']['$拉黑列表'] || [];
                    }
                    return blacklist.includes(targetName);
                }
            } catch(e) {
                console.warn("[心遇前端] 检查拉黑状态失败:", e);
            }
            return false;
        }

        async function toggleBlockUser(isBlockedState) {
            if (!currentChatName) return;
            try {
                const topW = getTopWindow();
                const msgId = getStMessageId();
                let playerName = getPlayerNameFromVars();
                const safeName = currentChatName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

                sendTavernEvent('XQ_UI_UPDATE_VAR', {
                    type: 'toggleBlock',
                    messageId: msgId,
                    targetName: currentChatName,
                    isBlockedState: isBlockedState
                });

                if (isBlockedState) {
                    let appendStr = `\n[拉黑对象] ${playerName}在「微信」上将${currentChatName}加入黑名单`;
                    await appendToFloorMessage(msgId, appendStr);
                } else {
                    let currentText = "";
                    try {
                        const getChatMsgs = topW.TavernHelper?.getChatMessages;
                        if (getChatMsgs) {
                            const messages = getChatMsgs(msgId);
                            if (messages && messages.length > 0) {
                                currentText = messages[0].message || "";
                            }
                        }
                    } catch (e) {
                        console.warn("[心遇前端] 读取当前楼层文本失败:", e);
                    }

                    let blockRegex = new RegExp(`\\n?\\[拉黑对象\\] ${playerName}在「微信」上将${safeName}加入黑名单`, 'g');
                    if (blockRegex.test(currentText)) {
                        let newText = currentText.replace(blockRegex, '');
                        try {
                            const setMsgs = topW.TavernHelper?.setChatMessages;
                            if (setMsgs) {
                                await setMsgs([{ message_id: msgId, message: newText }], { refresh: 'none' });
                            }
                        } catch(e) {
                            console.error("[心遇前端] 写入楼层文本失败:", e);
                        }
                    } else {
                        let appendStr = `\n[解除拉黑] ${playerName}在「微信」上将${currentChatName}移出黑名单`;
                        await appendToFloorMessage(msgId, appendStr);
                    }
                }

                // 像 deleteChat 那样延迟刷新
                setTimeout(() => {
                    openChat(currentChatName);
                }, 200);
            } catch (e) {
                console.error("[心遇前端] 更新拉黑状态失败:", e);
            }
        }

        // ====== 详情页逻辑 ======
        let currentDetailIndex = -1;
        let currentChatName = "";

        function openDetail(index) {
            currentDetailIndex = index;
            const nameEl = document.getElementById('detail-name');
            const ageEl = document.getElementById('detail-age');
            const tagsContainer = document.getElementById('detail-tags');
            const descEl = document.getElementById('detail-desc');
            const subDetailContent = document.querySelector('#subpage-detail .subpage-content');
            const imgContainer = document.querySelector('#subpage-detail .dating-card-image-container');

            if(!nameEl || !ageEl || !tagsContainer || !descEl) return;

            try {
                const cached = localStorage.getItem('SillyTavern_BlindDate_Liked');
                if (cached) {
                    const likedQueue = JSON.parse(cached);
                    if (Array.isArray(likedQueue) && likedQueue[index]) {
                        const target = likedQueue[index];
                        const targetName = target["姓名"] || "神秘人";

                        const isGoddess = Array.isArray(target["对象类型"]) && target["对象类型"].includes("女神");
                        if(subDetailContent) {
                            if(isGoddess) subDetailContent.classList.add('goddess-theme');
                            else subDetailContent.classList.remove('goddess-theme');
                        }

                        markLikedAsRead(targetName);
                        renderLikedGrid();

                        nameEl.innerText = targetName;
                        ageEl.innerText = target["年龄"] ? `${target["年龄"]}岁` : "";

                        const { desc, width, height } = parseImagePrompt(target["图片描述"], 1024);
                        if (imgContainer) {
                            imgContainer.style.aspectRatio = `${width} / ${height}`;
                        }

                        const realUrl = getRealAvatarUrl(target["图片描述"]);
                        const mainImg = document.getElementById('detail-real-avatar');
                        const miniImg = document.getElementById('detail-mini-avatar');
                        if (mainImg) { mainImg.style.opacity = 1; if (realUrl) { mainImg.src = realUrl; } }
                        if (miniImg) { miniImg.style.opacity = 1; if (realUrl) { miniImg.src = realUrl; } }

                        let cup = target["罩杯"];
                        if(cup) cup = cup.replace(/罩杯/g, '') + "罩杯";

                        const tags = [target["籍贯"], target["身高"], target["体重"], cup, target["学历"], target["职业"]];
                        tagsContainer.innerHTML = '';
                        tags.forEach(t => {
                            if (t) {
                                const span = document.createElement('span');
                                span.className = 'tag';
                                span.innerText = t;
                                tagsContainer.appendChild(span);
                            }
                        });

                        let descHTML = '';
                        if (target["自我介绍"]) descHTML += `<div class="desc-section-title">关于我</div>${target["自我介绍"]}<br>`;
                        if (target["性格特点"]) descHTML += `<div class="desc-section-title">性格特点</div>${target["性格特点"]}<br>`;
                        if (target["兴趣爱好"]) descHTML += `<div class="desc-section-title">兴趣爱好</div>${target["兴趣爱好"]}<br>`;
                        if (target["家庭背景"]) descHTML += `<div class="desc-section-title">家庭背景</div>${target["家庭背景"]}<br>`;
                        if (target["个人资产"]) descHTML += `<div class="desc-section-title">个人资产</div>${target["个人资产"]}<br>`;
                        if (target["个人收入"]) descHTML += `<div class="desc-section-title">个人收入</div>${target["个人收入"]}<br>`;

                        if (isHackMode) {
                            const rawJsonStr = JSON.stringify(target, null, 2);
                            descHTML += `<div class="desc-section-title">调试数据</div><pre style="font-size:12px; color:var(--text-sub); background:var(--bg-section); padding:10px; border-radius:8px; white-space:pre-wrap; word-wrap:break-word;">${rawJsonStr}</pre>`;
                        }

                        descEl.innerHTML = descHTML;

                        const subDetail = document.getElementById('subpage-detail');
                        if(subDetail) subDetail.style.display = 'flex';
                    }
                }
            } catch (e) {
                console.error("[心遇前端] 加载详情页失败:", e);
            }
        }

        function closeDetail() {
            const subDetail = document.getElementById('subpage-detail');
            if(subDetail) subDetail.style.display = 'none';
            const subDetailContent = document.querySelector('#subpage-detail .subpage-content');
            if(subDetailContent) subDetailContent.classList.remove('goddess-theme');
            currentDetailIndex = -1;
        }

        function deleteLikedFromDetail() {
            if (currentDetailIndex === -1) return;
            try {
                const cached = localStorage.getItem('SillyTavern_BlindDate_Liked');
                if (cached) {
                    let likedQueue = JSON.parse(cached);
                    if (Array.isArray(likedQueue) && likedQueue[currentDetailIndex]) {
                        const targetName = likedQueue[currentDetailIndex]["姓名"] || "未知";
                        removeLikedFromRead(targetName);

                        likedQueue.splice(currentDetailIndex, 1);
                        localStorage.setItem('SillyTavern_BlindDate_Liked', JSON.stringify(likedQueue));
                        renderLikedGrid();
                    }
                }
            } catch (e) {
                console.error("[心遇前端] 删除喜欢对象失败:", e);
            }
            closeDetail();
        }

        async function startChatFromDetail() {
            if (currentDetailIndex === -1) return;
            try {
                const likedCached = localStorage.getItem('SillyTavern_BlindDate_Liked');
                if (likedCached) {
                    let likedQueue = JSON.parse(likedCached);
                    if (Array.isArray(likedQueue) && likedQueue[currentDetailIndex]) {
                        const targetObj = likedQueue[currentDetailIndex];
                        const name = targetObj["姓名"] || "神秘人";

                        removeLikedFromRead(name);

                        const msgId = getStMessageId();

                        sendTavernEvent('XQ_StartDetailChat', {
                            msgId: msgId,
                            targetName: name,
                            targetObj: targetObj
                        });

                        likedQueue.splice(currentDetailIndex, 1);
                        localStorage.setItem('SillyTavern_BlindDate_Liked', JSON.stringify(likedQueue));
                        renderLikedGrid();

                        closeDetail();
                    }
                }
            } catch (e) {
                console.error("[心遇前端] 开启聊天发送事件失败:", e);
            }
        }

        // ====== 消息列表动态渲染逻辑 ======
        function renderMessageList() {
            const container = document.getElementById('message-list-container');
            if (!container) return;

            try {
                const msgId = getStMessageId();
                if (msgId === null) {
                    container.innerHTML = `<div style="text-align: center; color: var(--text-hint); padding-top: 50px;">环境未就绪，暂无记录</div>`;
                    return;
                }

                let activeKeys = [];
                let targetList = {};
                const topW = getTopWindow();
                if (topW.Mvu && topW.Mvu.getMvuData) {
                    const mvuData = topW.Mvu.getMvuData({ type: 'message', message_id: msgId });
                    if (mvuData && mvuData.stat_data && mvuData.stat_data['交往对象列表']) {
                        targetList = mvuData.stat_data['交往对象列表'];
                        activeKeys = Object.keys(targetList);
                    }
                }

                let totalUnread = 0;

                // 获取最新基准时间
                let latestTimestamp = null;
                try {
                    if (topW.TavernHelper && topW.TavernHelper.getVariables) {
                        let targetMsgId = msgId !== null ? msgId : 'latest';
                        const vars = topW.TavernHelper.getVariables({type: 'message', message_id: targetMsgId});
                        if (topW._ && topW._.get) {
                            let latestTimeStr = topW._.get(vars, 'stat_data.世界状态.时间', '');
                            latestTimestamp = parseGameTime(latestTimeStr);
                        } else if (vars && vars.stat_data && vars.stat_data['世界状态']) {
                            latestTimestamp = parseGameTime(vars.stat_data['世界状态']['时间']);
                        }
                    }
                } catch(e) {}

                if (activeKeys.length > 0) {
                    const bgColors = ['%23ffccd5', '%23c8e7ff', '%23e0d4ff', '%23d4f0d4'];
                    const recentText = getRecentLayersText();
                    const recentMessages = getRecentMessages();
                    let htmlString = "";

                    activeKeys.forEach((name, index) => {
                        const color = bgColors[index % bgColors.length];
                        const picDesc = targetList[name] ? targetList[name]["图片描述"] : "暂无";
                        const realUrl = getRealAvatarUrl(picDesc);
                        const realImgHtml = realUrl ? `<img class="msg-avatar" src="${realUrl}" style="position: absolute; top: 0; left: 0; opacity: 1;" onerror="this.style.opacity=0" loading="lazy">` : '';

                        if (isBlocked(name)) {
                            htmlString += `
                                <li class="message-item" onclick="openChat('${name}')">
                                    <div class="msg-avatar-container">
                                        <img class="msg-avatar" src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Crect width='100' height='100' fill='${color}'/%3E%3C/svg%3E" alt="头像">
                                        ${realImgHtml}
                                    </div>
                                    <div class="msg-content">
                                        <div class="msg-header">
                                            <span class="msg-name">${name}</span>
                                            <span class="msg-time">屏蔽中</span>
                                        </div>
                                        <div class="msg-preview">已加入黑名单</div>
                                    </div>
                                </li>
                            `;
                            return;
                        }

                        let previewText = "点击开始聊天吧";
                        const safeName = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

                        try {
                            const regex = new RegExp(`<微信\\s+(?:user|from)="${safeName}">([\\s\\S]*?)<\/微信>`, 'gi');
                            let match;
                            let lastMatch = null;
                            while ((match = regex.exec(recentText)) !== null) {
                                lastMatch = match;
                            }
                            if (lastMatch && lastMatch[1]) {
                                let rawText = lastMatch[1].trim();
                                rawText = rawText.replace(/<img:[^>]+>/gi, '[图片]');
                                previewText = rawText;
                            }
                        } catch(re) {
                            console.warn("[心遇前端] 正则解析预览文本失败:", re);
                        }

                        const unreadCount = getUnreadMsgCount(name, recentText);
                        totalUnread += unreadCount;
                        const badgeHtml = unreadCount > 0 ? `<div class="msg-badge">${unreadCount}</div>` : '';

                        let displayTime = "刚刚";
                        let lastMsgTimeStr = null;
                        try {
                            for (let i = recentMessages.length - 1; i >= 0; i--) {
                                if (recentMessages[i].mes.includes(`<微信 user="${name}">`) || recentMessages[i].mes.includes(`<微信 from="${name}">`)) {
                                    if (topW.TavernHelper && topW.TavernHelper.getVariables) {
                                        let vars = topW.TavernHelper.getVariables({type: 'message', message_id: recentMessages[i].message_id});
                                        if (topW._ && topW._.get) {
                                            lastMsgTimeStr = topW._.get(vars, 'stat_data.世界状态.时间', '');
                                        } else if (vars && vars.stat_data && vars.stat_data['世界状态']) {
                                            lastMsgTimeStr = vars.stat_data['世界状态']['时间'];
                                        }
                                    }
                                    break;
                                }
                            }
                        } catch(e) {}

                        if (lastMsgTimeStr && latestTimestamp) {
                            let msgTimestamp = parseGameTime(lastMsgTimeStr);
                            if (msgTimestamp) {
                                displayTime = formatRelativeTime(msgTimestamp, latestTimestamp);
                            }
                        }

                        htmlString += `
                            <li class="message-item" onclick="openChat('${name}')">
                                <div class="msg-avatar-container">
                                    <img class="msg-avatar" src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Crect width='100' height='100' fill='${color}'/%3E%3C/svg%3E" alt="头像">
                                    ${realImgHtml}
                                    ${badgeHtml}
                                </div>
                                <div class="msg-content">
                                    <div class="msg-header">
                                        <span class="msg-name">${name}</span>
                                        <span class="msg-time">${displayTime}</span>
                                    </div>
                                    <div class="msg-preview">${previewText}</div>
                                </div>
                            </li>
                        `;
                    });
                    container.innerHTML = htmlString;
                } else {
                    container.innerHTML = `<div style="text-align: center; color: var(--text-hint); padding-top: 50px;">暂无消息记录<br>去喜欢页发起聊天吧~</div>`;
                }

                const msgTabBadge = document.getElementById('msg-tab-badge');
                if (msgTabBadge) {
                    if (totalUnread > 0) {
                        msgTabBadge.innerText = totalUnread;
                        msgTabBadge.style.display = 'flex';
                    } else {
                        msgTabBadge.style.display = 'none';
                    }
                }

            } catch (e) {
                console.error("[心遇前端] 渲染消息列表失败:", e);
                container.innerHTML = `<div style="text-align: center; color: var(--text-hint); padding-top: 50px;">读取失败</div>`;
            }
        }

