        // ====== 卡片数据渲染逻辑 ======
        function renderCurrentCard() {
            try {
                const cardElement = document.getElementById('dating-card');
                const cardScrollArea = document.getElementById('card-scroll-area');
                const nameEl = document.querySelector('.user-name');
                const ageEl = document.querySelector('.user-age');
                const tagsContainer = document.querySelector('.user-tags');
                const descEl = document.querySelector('.user-desc');
                const imgContainer = document.querySelector('.dating-card-image-container');

                if(!nameEl || !ageEl || !tagsContainer || !descEl) return;

                const cached = localStorage.getItem('SillyTavern_BlindDate_Queue');
                if (cached) {
                    const queue = JSON.parse(cached);
