                        if (target["性格特点"]) descHTML += `<div class="desc-section-title">性格特点</div>${target["性格特点"]}<br>`;
                        if (target["兴趣爱好"]) descHTML += `<div class="desc-section-title">兴趣爱好</div>${target["兴趣爱好"]}<br>`;
                        if (target["家庭背景"]) descHTML += `<div class="desc-section-title">家庭背景</div>${target["家庭背景"]}<br>`;
                        if (target["个人资产"]) descHTML += `<div class="desc-section-title">个人资产</div>${target["个人资产"]}<br>`;
                        if (target["个人收入"]) descHTML += `<div class="desc-section-title">个人收入</div>${target["个人收入"]}<br>`;

                        if (isHackMode) {
