                descEl.innerHTML = "<br><br><div style='text-align:center;'>完成信息登记后滑动卡片<br>立即为您在茫茫人海中寻找合适的缘分...</div>";

                const mainImg = document.getElementById('recommend-real-avatar');
                const miniImg = document.getElementById('recommend-mini-avatar');
                if (mainImg) mainImg.style.opacity = 0;
                if (miniImg) miniImg.style.opacity = 0;

            } catch (e) {
