        // --- 卡片拖拽与滑动逻辑 ---
        const card = document.getElementById('dating-card');
        const statusLike = document.getElementById('status-like');
        const statusNope = document.getElementById('status-nope');
        const scrollArea = document.getElementById('card-scroll-area');

        let isDragging = false;
        let startX = 0, startY = 0;
        let currentX = 0, currentY = 0;
        let isHorizontalSwipe = false;
        let isSwipeDetermined = false;

        const threshold = window.innerWidth * 0.25;

        function initDrag(e) {
            if(!card) return;
            if(card.style.transition) card.style.transition = 'none';
            isDragging = true;
            isSwipeDetermined = false;
            isHorizontalSwipe = false;

            const clientX = e.type.includes('mouse') ? e.clientX : e.touches[0].clientX;
            const clientY = e.type.includes('mouse') ? e.clientY : e.touches[0].clientY;

            startX = clientX;
            startY = clientY;

            document.addEventListener('mousemove', onDrag);
            document.addEventListener('mouseup', endDrag);
            document.addEventListener('touchmove', onDrag, {passive: false});
            document.addEventListener('touchend', endDrag);
        }

        function onDrag(e) {
            if (!isDragging || !card) return;

            const clientX = e.type.includes('mouse') ? e.clientX : e.touches[0].clientX;
            const clientY = e.type.includes('mouse') ? e.clientY : e.touches[0].clientY;

            const deltaX = clientX - startX;
            const deltaY = clientY - startY;

            if (!isSwipeDetermined) {
                if (Math.abs(deltaX) > Math.abs(deltaY) && Math.abs(deltaX) > 10) {
                    isHorizontalSwipe = true;
                    isSwipeDetermined = true;
                } else if (Math.abs(deltaY) > Math.abs(deltaX) && Math.abs(deltaY) > 10) {
                    isHorizontalSwipe = false;
                    isSwipeDetermined = true;
                }
            }

            if (isSwipeDetermined && !isHorizontalSwipe) {
                isDragging = false;
                resetCard();
                return;
            }

            if (isSwipeDetermined && isHorizontalSwipe) {
                if(e.cancelable) e.preventDefault();
                currentX = deltaX;
                currentY = deltaY;

                const rotate = currentX * 0.05;
                card.style.transform = `translate(${currentX}px, ${currentY}px) rotate(${rotate}deg)`;

                if (currentX > 0) {
                    if(statusLike) statusLike.style.opacity = Math.min(currentX / threshold, 1);
                    if(statusNope) statusNope.style.opacity = 0;
                } else {
                    if(statusNope) statusNope.style.opacity = Math.min(Math.abs(currentX) / threshold, 1);
                    if(statusLike) statusLike.style.opacity = 0;
                }
            }
        }

        function endDrag(e) {
            if (!isDragging) return;
            isDragging = false;

            document.removeEventListener('mousemove', onDrag);
            document.removeEventListener('mouseup', endDrag);
            document.removeEventListener('touchmove', onDrag);
            document.removeEventListener('touchend', endDrag);

            if (!isHorizontalSwipe) {
                resetCard();
                return;
            }

            if (currentX > threshold) {
                swipeOut('right');
            } else if (currentX < -threshold) {
                swipeOut('left');
            } else {
                resetCard();
            }
        }

        function resetCard() {
            if(!card) return;
            card.style.transition = 'transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275)';
            card.style.transform = 'translate(0px, 0px) rotate(0deg)';
            if(statusLike) statusLike.style.opacity = 0;
            if(statusNope) statusNope.style.opacity = 0;
            currentX = 0;
            currentY = 0;

            setTimeout(() => {
                if (!isDragging && card) card.style.transition = '';
            }, 300);
        }

        function swipeOut(direction) {
            if(!card) return;
            const msgId = getStMessageId();
            const flyX = direction === 'right' ? window.innerWidth * 1.5 : -window.innerWidth * 1.5;
            const flyRotate = direction === 'right' ? 30 : -30;

            if (direction === 'right') {
                if(statusLike) statusLike.style.opacity = 1;
                if(statusNope) statusNope.style.opacity = 0;
            } else {
                if(statusNope) statusNope.style.opacity = 1;
                if(statusLike) statusLike.style.opacity = 0;
            }

            card.style.transition = 'transform 0.4s ease-out';
            card.style.transform = `translate(${flyX}px, ${currentY || -50}px) rotate(${flyRotate}deg)`;

            sendTavernEvent('XQ_SwipeCard', { direction: direction, vipLevel: realVipLevel, msgId: msgId });

            setTimeout(() => {
                if(!card) return;
                card.style.transition = 'none';
                card.style.transform = 'translate(0px, 0px) rotate(0deg) scale(0.95)';
                card.style.opacity = '0';
                if(statusLike) statusLike.style.opacity = 0;
                if(statusNope) statusNope.style.opacity = 0;
                if(scrollArea) scrollArea.scrollTop = 0;

                renderCurrentCard();

                setTimeout(() => {
                    if(!card) return;
                    card.style.transition = 'all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275)';
                    card.style.transform = 'translate(0px, 0px) rotate(0deg) scale(1)';
                    card.style.opacity = '1';
                }, 50);
            }, 400);
        }

        function swipeCard(direction) {
            if(isDragging) return;
            swipeOut(direction);
        }

        if(card) {
            card.addEventListener('mousedown', initDrag);
            card.addEventListener('touchstart', initDrag, {passive: true});
        }

        // --- 页面切换逻辑 ---
        function switchTab(tabId, titleText, event) {
            const headerTitle = document.getElementById('header-title');
            if(headerTitle) headerTitle.innerText = titleText;

            const pages = document.querySelectorAll('.tab-page');
            pages.forEach(page => page.classList.remove('active'));

            const tabItems = document.querySelectorAll('.tab-item');
            tabItems.forEach(item => item.classList.remove('active'));

            const targetPage = document.getElementById('page-' + tabId);
            if(targetPage) targetPage.classList.add('active');

            if(event && event.currentTarget) event.currentTarget.classList.add('active');

            const settingsIcon = document.getElementById('main-settings-icon');
            const powerIcon = document.getElementById('main-power-icon');
            if (tabId === 'profile') {
                if (settingsIcon) settingsIcon.style.display = 'flex';
                if (powerIcon) powerIcon.style.display = 'none';
            } else {
                if (settingsIcon) settingsIcon.style.display = 'none';
                if (powerIcon) powerIcon.style.display = 'flex';
            }

            if (tabId === 'like') {
                renderLikedGrid();
            } else if (tabId === 'message') {
                renderMessageList();
            }
        }

        // ====== 聊天室渲染逻辑 ======
        function renderChatHistory(targetName) {
            const chatContentArea = document.getElementById('chat-content-area');
            if (!chatContentArea) return;

            chatContentArea.innerHTML = '';

            if (isBlocked(targetName)) {
                return;
            }

            const recentMessages = getRecentMessages();
            const msgId = getStMessageId();

            let targetPicDesc = "暂无";
            try {
                const topW = getTopWindow();
                if (topW.Mvu && topW.Mvu.getMvuData && msgId !== null) {
                    const mvuData = topW.Mvu.getMvuData({ type: 'message', message_id: msgId });
                    if (mvuData && mvuData.stat_data && mvuData.stat_data['交往对象列表'] && mvuData.stat_data['交往对象列表'][targetName]) {
                        targetPicDesc = mvuData.stat_data['交往对象列表'][targetName]['图片描述'] || "暂无";
                    }
                }
            } catch (e) {
                console.warn("[心遇前端] 获取聊天室对象图片描述失败:", e);
            }

            const realUrl = getRealAvatarUrl(targetPicDesc);
            const realImgHtml = realUrl ? `<img src="${realUrl}" style="position: absolute; width: 100%; height: 100%; object-fit: cover; top: 0; left: 0; opacity: 1;" onerror="this.style.opacity=0" loading="lazy">` : '';

            try {
                const topW = getTopWindow();

                // 获取最新基准时间
                let latestTimestamp = null;
                try {
                    if (topW.TavernHelper && topW.TavernHelper.getVariables) {
                        let targetMsgId = msgId !== null ? msgId : 'latest';
                        const vars = topW.TavernHelper.getVariables({type: 'message', message_id: targetMsgId});
                        if (topW._ && topW._.get) {
                            let latestTimeStr = topW._.get(vars, 'stat_data.世界状态.时间', '');
                            latestTimestamp = parseGameTime(latestTimeStr);
                        } else if (vars && vars.stat_data && vars.stat_data['世界状态']) {
                            latestTimestamp = parseGameTime(vars.stat_data['世界状态']['时间']);
                        }
                    }
                } catch(e) {}

                let lastMsgTimestamp = 0;
                let lastDisplayedDateStr = "";

                for (let msgObj of recentMessages) {
                    const rawMes = msgObj.mes;
                    const regex = /<微信\s+(user|from)="([^"]+)">([\s\S]*?)<\/微信>/gi;
                    let match;

                    while ((match = regex.exec(rawMes)) !== null) {
                        const type = match[1];
                        const bindName = match[2].trim();
                        let msgText = match[3].trim();

                        if (bindName === targetName) {
                            const isSelf = (type === 'user');
                            const rowClass = isSelf ? 'chat-row self' : 'chat-row other';

                            let timeHtml = "";
                            try {
                                if (topW.TavernHelper && topW.TavernHelper.getVariables) {
                                    const vars = topW.TavernHelper.getVariables({type: 'message', message_id: msgObj.message_id});
                                    let timeStr = "";
                                    if (topW._ && topW._.get) {
                                        timeStr = topW._.get(vars, 'stat_data.世界状态.时间', '');
                                    } else if (vars && vars.stat_data && vars.stat_data['世界状态']) {
                                        timeStr = vars.stat_data['世界状态']['时间'];
                                    }

                                    let currentTimestamp = parseGameTime(timeStr);
                                    if (currentTimestamp) {
                                        if (lastMsgTimestamp === 0 || (currentTimestamp - lastMsgTimestamp) >= 300000) {
                                            let formattedTime = formatRelativeTime(currentTimestamp, latestTimestamp);
                                            timeHtml = `<div class="chat-time">${formattedTime}</div>`;
                                            lastMsgTimestamp = currentTimestamp;
                                        }
                                    } else if (timeStr) {
                                        // 降级兜底逻辑
                                        const datePartMatch = timeStr.match(/^(\d{4}年\d{1,2}月\d{1,2}日)/);
                                        const datePart = datePartMatch ? datePartMatch[1] : timeStr;
                                        if (datePart !== lastDisplayedDateStr) {
                                            timeHtml = `<div class="chat-time">${timeStr}</div>`;
                                            lastDisplayedDateStr = datePart;
                                        }
                                    }
                                }
                            } catch(te) {
                                console.warn("[心遇前端] 获取时间变量失败:", te);
                            }

                            const textWithoutImg = msgText.replace(/<img:[^>]+>/gi, '').trim();
                            const isPureImage = (textWithoutImg.length === 0);

                            const imgRegex = /<img:\s*([^>]+?)>/gi;
                            msgText = msgText.replace(imgRegex, (imgMatch, prompt) => {
                                const { desc, width, height } = parseImagePrompt(prompt, 512);
                                const safePrompt = encodeURIComponent(desc);
                                const genUrl = `https://loremflickr.com/${width}/${height}/${safePrompt}`;

                                const baseAvatarHtml = isSelf
                                    ? `<div class="user_avatar" style="width: 100%; height: 100%;"></div>`
                                    : `<div class="char_avatar" style="width: 100%; height: 100%;"></div>`;

                                return `
                                    <div style="width: 100%; aspect-ratio: ${width} / ${height}; border-radius: 8px; overflow: hidden; position: relative; margin-top: 5px; box-sizing: border-box;">
                                        ${baseAvatarHtml}
                                        <img src="${genUrl}" style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; opacity: 1;" onerror="this.style.opacity=0">
                                    </div>
                                `;
                            });

                            const avatarHtml = isSelf
                                ? `<div class="chat-avatar" style="overflow: hidden;"><div class="user_avatar"></div></div>`
                                : `<div class="chat-avatar" style="position: relative; overflow: hidden;">${realImgHtml}</div>`;

                            let bubbleContentHtml = "";
                            if (isPureImage) {
                                bubbleContentHtml = `<div class="chat-bubble" style="width: 65%; background-color: transparent; padding: 0; box-shadow: none;">${msgText}</div>`;
                            } else {
                                bubbleContentHtml = `<div class="chat-bubble">${msgText}</div>`;
                            }

                            const chatHTML = `
                                ${timeHtml}
                                <div class="${rowClass}">
                                    ${!isSelf ? avatarHtml : ''}
                                    ${bubbleContentHtml}
                                    ${isSelf ? avatarHtml : ''}
                                </div>
                            `;
                            chatContentArea.insertAdjacentHTML('beforeend', chatHTML);
                        }
                    }
                }

                setTimeout(() => {
                    chatContentArea.scrollTop = chatContentArea.scrollHeight;
                }, 50);

            } catch (e) {
                console.error("[心遇前端] 渲染聊天记录失败:", e);
            }
        }

        // ====== 发送消息与重试机制 ======
        function handleInputKeyDown(event) {
            if (event.key === 'Enter' || event.keyCode === 13) {
                if (event.ctrlKey) {
                    event.preventDefault();
                    sendMessage();
                }
            }
        }

        function autoResizeInput(element) {
            element.style.height = '36px';
            element.style.height = element.scrollHeight + 'px';
        }

        async function sendMessage() {
            if (!currentChatName) return;

            // 拉黑状态下拦截发送
            if (isBlocked(currentChatName)) {
                return;
            }

            const inputEl = document.getElementById('chat-input');
            if(!inputEl) return;

            const text = inputEl.value.trim();
            const playerName = getPlayerNameFromVars();
            const msgId = getStMessageId();

            if (text) {
                // 使用微信格式包裹发送的文本，user 为当前目标对象
                const newChatBlock = `\n&lt;微信 user="${currentChatName}"&gt;\n${text}\n&lt;/微信&gt;`;
                await appendToFloorMessage(msgId, newChatBlock);

                inputEl.value = '';
                inputEl.style.height = '36px';
                markMsgAsRead(currentChatName);
                renderChatHistory(currentChatName);
                renderMessageList();
            }

            sendTavernEvent('XQ_TriggerChat', { targetName: currentChatName, playerName: playerName, msgId: msgId });
        }

        function openChat(nameText) {
            currentChatName = nameText;
            const svgIcon = document.getElementById('status-svg-icon');

            if (svgIcon && nameText) {
                if (isBlocked(nameText)) {
                    // 禁止图标 🚫
                    svgIcon.innerHTML = `<path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18c-4.42 0-8-3.58-8-8 0-1.85.63-3.55 1.69-4.9L16.9 18.31C15.55 19.37 13.85 20 12 20zm6.31-3.1L7.1 5.69C8.45 4.63 10.15 4 12 4c4.42 0 8 3.58 8 8 0 1.85-.63 3.55-1.69 4.9z"/>`;
                    svgIcon.style.fill = "#ff3b30";
                } else {
                    // 标准半身人像图标
                    svgIcon.innerHTML = `<path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z"/>`;
