        // --- 三级页面：状态页相关逻辑 ---
        function openChatState() {
            const subChatState = document.getElementById('subpage-chat-state');
            const stateTitle = document.getElementById('chat-state-title');

            if (stateTitle && currentChatName) {
                stateTitle.innerText = currentChatName;
