        async function deleteChat() {
            if (!currentChatName) return;

            try {
                const topW = getTopWindow();
                const msgId = getStMessageId();

                // 获取当前的活跃对象，用于判断是否需要清空
                let activeObjName = "";
                try {
                    if (topW.TavernHelper) {
                        let targetMsgId = msgId !== null ? msgId : 'latest';
                        const vars = topW.TavernHelper.getVariables({type: 'message', message_id: targetMsgId});
                        if (topW._ && topW._.get) {
                            activeObjName = topW._.get(vars, 'stat_data.当前活跃对象', '');
                        } else if (vars && vars.stat_data) {
                            activeObjName = vars.stat_data['当前活跃对象'] || "";
                        }
                    }
                } catch (e) {
                    console.warn("[心遇前端] 读取当前活跃对象异常", e);
                }

                // 提前追加删除文本
                let playerName = getPlayerNameFromVars();
                let appendStr = `\n[删除对象] ${playerName}在「微信」上将${currentChatName}删除好友`;
                await appendToFloorMessage(msgId, appendStr);

                // 1. 发送删除对象的指令
                sendTavernEvent('XQ_UI_UPDATE_VAR', {
                    type: 'deleteObject',
                    messageId: msgId,
                    targetName: currentChatName
                });

                // 2. 如果删除的是当前活跃对象，同步发送清空活跃的指令
                if (activeObjName === currentChatName) {
                    sendTavernEvent('XQ_UI_UPDATE_VAR', {
                        type: 'setActive',
                        messageId: msgId,
                        name: ""
                    });
                }

                // 3. 清理前端的游标缓存
                const cursorDict = JSON.parse(localStorage.getItem('SillyTavern_BlindDate_Msg_Cursor') || '{}');
                if (cursorDict[currentChatName]) {
                    delete cursorDict[currentChatName];
                    localStorage.setItem('SillyTavern_BlindDate_Msg_Cursor', JSON.stringify(cursorDict));
                }

                // 4. 最后关闭面板并清空全局变量
                closeChatState();
                closeChat();

                // 5. 延迟 200 毫秒刷新列表，确保后端的异步变量更新已完成
                setTimeout(() => {
                    renderMessageList();
                }, 200);

            } catch(e) {
                console.error("[心遇前端] 删除对象事件发送失败:", e);
                closeChatState();
                closeChat();
            }
        }

        const CACHE_KEY = 'SillyTavern_BlindDate_Cache';
        const pFields = ['p_name', 'p_age', 'p_height', 'p_weight', 'p_face', 'p_shape', 'p_native', 'p_income', 'p_address', 'p_money', 'p_bg', 'p_job', 'p_edu', 'p_trait', 'p_hobby', 'p_note'];
        const tFields = ['t_age', 't_native', 't_height', 't_weight', 't_face', 't_shape', 't_edu', 't_income', 't_bg', 't_money', 't_job', 't_trait', 't_best', 't_worst', 't_hobby', 't_note'];

        function loadProfileData() {
            try {
                const cacheStr = localStorage.getItem(CACHE_KEY);
                if (!cacheStr) return;

                const cacheData = JSON.parse(cacheStr);

                let playerName = cacheData['p_name'] ? cacheData['p_name'].trim() : '';
                if (playerName === '') playerName = '玩家';

                const dispName = document.getElementById('display_header_name');
                if(dispName) dispName.innerText = playerName;

                pFields.forEach(id => {
                    const el = document.getElementById('val_' + id);
                    if (el) {
                        let val = cacheData[id] ? cacheData[id].trim() : '';
                        el.innerText = val !== '' ? val : '未填写';
                    }
                });

                tFields.forEach(id => {
                    const el = document.getElementById('val_' + id);
                    if (el) {
                        let val = cacheData[id] ? cacheData[id].trim() : '';
                        el.innerText = val !== '' ? val : '不限';
                    }
                });
            } catch (e) {
                console.error('[心遇前端] 读取缓存失败:', e);
            }
        }

        // ====== 接收后端或系统广播事件 ======
        window.addEventListener('message', async (event) => {
            if (event.data) {
                // 接收应用状态改变（VIP购买、删好友等）
                if (event.data.type === 'XQ_AppStateChanged' || event.data.type === 'XQ_ConfigUpdated') {
                    loadVipState();
                    renderVipMenu();
                    renderMessageList();
                }
                else if (event.data.type === 'XQ_QueueUpdated') {
                    const nameEl = document.querySelector('.user-name');
                    if (nameEl && nameEl.innerText === "队列为空...") {
                        renderCurrentCard();
                    }
                }
                else if (event.data.type === 'XQ_LikedUpdated') {
                    renderLikedGrid();
                }
                else if (event.data.type === 'XQ_DetailChatReady') {
                    const tabs = document.querySelectorAll('.tab-item');
                    if(tabs.length >= 3) {
                        switchTab('message', '消息', { currentTarget: tabs[2] });
                    }
                    openChat(event.data.targetName);
                }
                else if (event.data.type === 'XQ_ChatReplySuccess') {
                    const { targetName, replyContent } = event.data;
                    const msgId = getStMessageId();

                    const formattedBlock = `\n${replyContent}`;
                    await appendToFloorMessage(msgId, formattedBlock);

                    if (currentChatName === targetName) {
                        markMsgAsRead(targetName);
                        renderChatHistory(targetName);
                    }
                    renderMessageList();
                }
            }
        });

        window.addEventListener('DOMContentLoaded', () => {
            try {
                const isDark = localStorage.getItem('BlindDate_Dark_Mode') === 'true';
                const darkCheckbox = document.getElementById('setting-dark-mode');
                if (darkCheckbox) darkCheckbox.checked = isDark;
                toggleDarkMode(isDark);

                const isAutoClear = localStorage.getItem('BlindDate_Auto_Clear') === 'true';
                const autoClearCheckbox = document.getElementById('setting-auto-clear');
                if (autoClearCheckbox) autoClearCheckbox.checked = isAutoClear;

                // 读取匹配配置缓存并初始化输入框
                try {
                    const savedBatch = localStorage.getItem('BlindDate_Match_BatchSize');
                    if (savedBatch) {
                        const batchInput = document.getElementById('setting-match-batch');
                        if (batchInput) batchInput.value = savedBatch;
                    }
                    const savedThreshold = localStorage.getItem('BlindDate_Match_Threshold');
                    if (savedThreshold) {
                        const thresholdInput = document.getElementById('setting-match-threshold');
                        if (thresholdInput) thresholdInput.value = savedThreshold;
                    }
                    const savedLayers = localStorage.getItem('BlindDate_Display_Layers');
                    if (savedLayers) {
                        const offsetInput = document.getElementById('setting-log-offset');
                        if (offsetInput) offsetInput.value = savedLayers;
                    }
                } catch(e) {
                    console.warn("[心遇前端] 读取匹配配置缓存失败:", e);
                }

                loadProfileData();
                loadVipState();
                renderCurrentCard();
                renderLikedGrid();
                renderMessageList();

                // 注入全屏按钮
                injectFullscreenButtons();
            } catch (e) {
                console.error("[心遇前端] 初始化过程中发生严重错误:", e);
                const nameElFallback = document.querySelector('.user-name');
                if(nameElFallback) nameElFallback.innerText = "脚本执行崩溃";
            }
        });
    </script>
</body>
</html>
