                        <label class="xq-switch"><input type="checkbox" id="xq-cfg-api-enable"><span class="xq-slider"></span></label>
                    </div>
                    <div class="xq-grid-2">
                        <div class="xq-input-item xq-grid-full"><label>接口地址</label><input type="text" id="xq-cfg-api-url" placeholder="如：https://gcli.ggchan.dev" value=""></div>
                        <div class="xq-input-item xq-grid-full"><label>访问密钥</label><input type="text" id="xq-cfg-api-key" placeholder="如：sk-xxxxxxxx" value=""></div>
                        <div class="xq-input-item xq-grid-full"><label>模型名称</label><input type="text" id="xq-cfg-api-model" placeholder="点击获取可用模型，或手动输入" value=""></div>
                        <div class="xq-input-item"><label>最大回复</label><input type="number" id="xq-cfg-api-tokens" value="16384"></div>
                        <div class="xq-input-item"><label>生成温度</label><input type="number" id="xq-cfg-api-temp" value="0.8" step="0.1"></div>
                    </div>
                </div>

            </div>

            <!-- [底部] 操作栏 -->
            <div class="xq-footer">
                <button class="xq-btn-restore" id="xq-btn-restore-cfg" title="清除所有自定义参数并重载">恢复默认</button>
                <button class="xq-btn-save" id="xq-btn-save-cfg">保存配置</button>
            </div>
        </div>
    </div>
    `;

    // ==========================================
    // 3. 逻辑控制 (JS)
    // ==========================================
    const Terminal = {
        configMap: {
            'xq-cfg-breaklimit': { type: 'bool', key: 'XQ_UseBuiltinBreakLimit', default: true },
            'xq-cfg-force-update': { type: 'bool', key: 'XQ_ForceUpdate_Enable', default: true },
            'xq-cfg-preset': { type: 'text', key: 'XQ_CustomPresetName', default: '' },
            'xq-cfg-energy': { type: 'bool', key: 'XQ_EnergyMode', default: false },
            'xq-cfg-persona': { type: 'bool', key: 'XQ_AutoPersona', default: true },
            'xq-cfg-append-log': { type: 'bool', key: 'XQ_Append_Log', default: true },
            'xq-cfg-auto-clean': { type: 'bool', key: 'XQ_Auto_Clean', default: false },

            'xq-cfg-update-floor': { type: 'num', key: 'XQ_ForceUpdate_Floor', default: 128 },
            'xq-cfg-protect-floor': { type: 'num', key: 'XQ_Protect_Floor', default: 32 },
            'xq-cfg-offset': { type: 'num', key: 'XQ_Log_Offset', default: 16 },

            'xq-cfg-log-keep': { type: 'num', key: 'XQ_Log_Keep_Limit', default: 8192 },
            'xq-cfg-log-cut': { type: 'num', key: 'XQ_Log_Cut_Amount', default: 4096 },

            'xq-cfg-limit-fav': { type: 'bool', key: 'XQ_Fav_Limit_Enable', default: true },
            'xq-cfg-limit-desire': { type: 'bool', key: 'XQ_Desire_Limit_Enable', default: true },
            'xq-cfg-fav-inc': { type: 'num', key: 'XQ_Fav_Max_Inc', default: 3 },
            'xq-cfg-desire-inc': { type: 'num', key: 'XQ_Desire_Max_Inc', default: 6 },
            'xq-cfg-fav-dec': { type: 'num', key: 'XQ_Fav_Max_Dec', default: 100 },
            'xq-cfg-desire-dec': { type: 'num', key: 'XQ_Desire_Max_Dec', default: 100 },

            'xq-cfg-music-ambient': { type: 'bool', key: 'XQ_Music_Ambient', default: true },
            'xq-cfg-music-story': { type: 'bool', key: 'XQ_Music_Story', default: true },
            'xq-cfg-music-noloop': { type: 'bool', key: 'XQ_Music_NoLoop', default: true },
            'xq-cfg-music-fade': { type: 'bool', key: 'XQ_Music_Fade', default: true },

            'xq-cfg-hide-enable': { type: 'bool', key: 'XQ_Hide_Enable', default: true },
            'xq-cfg-hide-inc': { type: 'bool', key: 'XQ_Hide_Incremental', default: true },
            'xq-cfg-hide-keep': { type: 'num', key: 'XQ_Hide_Keep', default: 16 },
            'xq-cfg-hide-buf': { type: 'num', key: 'XQ_Hide_Buffer', default: 4 },

            'xq-cfg-api-enable': { type: 'bool', key: 'XQ_Api_Enable', default: false },
            'xq-cfg-api-url': { type: 'text', key: 'XQ_Api_Url', default: '' },
            'xq-cfg-api-key': { type: 'text', key: 'XQ_Api_Key', default: '' },
            'xq-cfg-api-model': { type: 'text', key: 'XQ_Api_Model', default: '' },
            'xq-cfg-api-tokens': { type: 'num', key: 'XQ_Api_Tokens', default: 16384 },
            'xq-cfg-api-temp': { type: 'num', key: 'XQ_Api_Temp', default: 0.8 },
        },

        syncToGlobalConfig: function(broadcast = false) {
            const configObj = {};
            for (const [id, cfg] of Object.entries(this.configMap)) {
                let val = localStorage.getItem(cfg.key);
                if (cfg.type === 'bool') {
                    configObj[cfg.key] = val !== null ? (val === 'true') : cfg.default;
                } else if (cfg.type === 'num') {
                    configObj[cfg.key] = val !== null ? parseFloat(val) : cfg.default;
                } else {
                    configObj[cfg.key] = val !== null ? val : cfg.default;
                }
            }
            // 写入全局变量池
            const targetWindow = (typeof parent !== 'undefined' && parent.window) ? parent.window : window;
            targetWindow.XQ_Config = configObj;

            if (broadcast) {
                this.emitXqEvent('XQ_ConfigUpdated');
                console.log('[终端控制台] 全局配置已同步。');
            }
        },

        emitXqEvent: function(eventName, data = {}) {
            if (typeof eventEmit === 'function') {
                eventEmit(eventName, data);
            } else {
                console.warn('[终端控制台] 未找到原生 eventEmit');
            }
        },

        init: function() {
            // 1. 挂载DOM
            if ($('#xq-terminal-overlay').length === 0) {
                $('head').append(STYLE);
                $('body').append(UI_HTML);
            }

            // 2. 加载配置到UI
            this.loadConfig();

            // 3. 绑定内部事件
            this.bindEvents();

            // 4. 初始化完毕，派发 XQ_ConfigUpdated 事件作为系统启动信号
            this.syncToGlobalConfig(true);

            // 5. 提示用户
            if (typeof toastr !== 'undefined') {
                const breakLimit = $('#xq-cfg-breaklimit').is(':checked');
                const apiEnable = $('#xq-cfg-api-enable').is(':checked');
                toastr.success(`当前配置：内置破限: ${breakLimit}，独立API: ${apiEnable}`, '系统就绪');
            }
        },

        loadConfig: function() {
            for (const [id, cfg] of Object.entries(this.configMap)) {
                const val = localStorage.getItem(cfg.key);
                const el = $(`#${id}`);

                if (cfg.type === 'bool') {
                    const isChecked = val !== null ? (val === 'true') : cfg.default;
                    el.prop('checked', isChecked);
                } else {
                    if (val !== null) {
                        el.val(val);
                    } else if (cfg.default !== '') {
                        el.val(cfg.default);
                    } else {
                        el.val('');
                    }
                }
            }
            // 触发组件状态联动
            $('#xq-cfg-breaklimit').trigger('change');
            $('#xq-cfg-force-update').trigger('change');
            $('#xq-cfg-api-enable').trigger('change');
            $('#xq-cfg-limit-fav').trigger('change');
            $('#xq-cfg-limit-desire').trigger('change');
            $('#xq-cfg-music-ambient').trigger('change');
            $('#xq-cfg-music-story').trigger('change');
            $('#xq-cfg-hide-enable').trigger('change');
            $('#xq-cfg-hide-inc').trigger('change');
            $('#xq-cfg-append-log').trigger('change');
        },

        saveConfig: function() {
            for (const [id, cfg] of Object.entries(this.configMap)) {
                const el = $(`#${id}`);
                let val = '';

                if (cfg.type === 'bool') {
                    val = el.is(':checked');
                } else {
                    val = el.val().trim();
                }

                if (val === '' && cfg.type !== 'bool') {
                    localStorage.removeItem(cfg.key);
                } else {
                    localStorage.setItem(cfg.key, val);
                }
            }

            // 保存完毕后重新广播
            this.syncToGlobalConfig(true);
        },

        restoreDefault: function() {
            for (const [id, cfg] of Object.entries(this.configMap)) {
                localStorage.removeItem(cfg.key);
            }
            this.loadConfig();
            this.syncToGlobalConfig(true);
        },

        // 尝试注入菜单
        injectMenu: function() {
            const TARGET_ID = 'xq-terminal-trigger';

            // 如果已经注入过了，只需更新状态并返回
            if ($(`#${TARGET_ID}`).length) {
                $(`#${TARGET_ID}`).off('click.xq_terminal').on('click.xq_terminal', () => this.open());
                return true;
            }

            // 查找可以挂载的目标容器
            const targets = ['#extensionsMenu .list-group', '#extensions_menu .list-group', '#extensionsMenu', '#extensions_menu'];
            let container = null;
            for (let sel of targets) {
                const el = $(sel);
                if (el.length) {
                    container = el.first();
                    if (!container.hasClass('list-group') && container.find('.list-group').length) {
                        container = container.find('.list-group').first();
                    }
                    break;
                }
            }

            // 如果找到容器，执行注入
            if (container) {
                const menuItem = $(`
                    <div id="${TARGET_ID}" class="list-group-item xq-menu-item" title="剧情终端控制台">
                        <i class="fa-solid fa-heart-pulse"></i>
                        <span>终端控制台</span>
                    </div>
                `);
                container.append(menuItem);
                menuItem.off('click.xq_terminal').on('click.xq_terminal', () => this.open());
                return true;
            }

            return false;
        },

        bindMenuTrigger: function() {
            // 监听扩展菜单按钮的点击动作，按需尝试注入
            $(document).off('click.xq_terminal_trigger', '#extensionsMenuButton')
                       .on('click.xq_terminal_trigger', '#extensionsMenuButton', () => {
                setTimeout(() => {
                    this.injectMenu();
                }, 0);
            });
        },

        showDropdown: function(inputEl, items) {
            $('.xq-dropdown').remove();

            $(document).off('click.xq_dropdown');
            $('.xq-panel').off('click.xq_dropdown');

            const $input = $(inputEl);
            const $container = $('<div class="xq-dropdown"></div>');

            items.forEach(item => {
                const $div = $('<div class="xq-dropdown-item"></div>').text(item);
                $div.on('click', function(e) {
                    $input.val(item).trigger('change');
                    $('.xq-dropdown').remove();
                    $(document).off('click.xq_dropdown');
                    $('.xq-panel').off('click.xq_dropdown');
                });
                $container.append($div);
            });

            $input.parent().append($container);

            setTimeout(() => {
                const closeDropdown = function(e) {
                    if (!$(e.target).closest('.xq-dropdown').length && !$(e.target).is($input)) {
                        $('.xq-dropdown').remove();
                        $(document).off('click.xq_dropdown');
                        $('.xq-panel').off('click.xq_dropdown');
                    }
                };

                $(document).on('click.xq_dropdown', closeDropdown);
                $('.xq-panel').on('click.xq_dropdown', closeDropdown);
            }, 0);
        },

        bindEvents: function() {
            const overlay = $('#xq-terminal-overlay');
            const closeBtn = overlay.find('.xq-close-btn');

            const close = () => { overlay.removeClass('show'); setTimeout(() => overlay.hide(), 200); };
            closeBtn.on('click', close);
            overlay.on('click', (e) => { if ($(e.target).is(overlay)) close(); });
            $(document).off('keydown.xq_terminal').on('keydown.xq_terminal', (e) => { if (e.key === 'Escape' && overlay.hasClass('show')) close(); });

            $('#xq-cfg-breaklimit').on('change', function() {
                const isChecked = $(this).is(':checked');
                const presetInput = $('#xq-cfg-preset');
                presetInput.prop('disabled', isChecked);

                $('.xq-dropdown').remove();
                $(document).off('click.xq_dropdown');
                $('.xq-panel').off('click.xq_dropdown');

                if (!isChecked && typeof getLoadedPresetName === 'function') {
                    const currentPreset = getLoadedPresetName();
                    if (currentPreset && currentPreset !== 'in_use' && !presetInput.val().trim()) {
                        presetInput.val(currentPreset);
                    }
                }
            });

            $('#xq-cfg-force-update').on('change', function() {
                const isChecked = $(this).is(':checked');
                $('#xq-cfg-update-floor').prop('disabled', !isChecked);
            });

            $('#xq-cfg-append-log').on('change', function() {
                const isChecked = $(this).is(':checked');
                $('#xq-cfg-offset').prop('disabled', !isChecked);
                $('#xq-cfg-log-keep').prop('disabled', !isChecked);
                $('#xq-cfg-log-cut').prop('disabled', !isChecked);
            });

            $('#xq-cfg-limit-fav').on('change', function() {
                const isChecked = $(this).is(':checked');
                $('#xq-cfg-fav-inc').prop('disabled', !isChecked);
                $('#xq-cfg-fav-dec').prop('disabled', !isChecked);
            });

            $('#xq-cfg-limit-desire').on('change', function() {
                const isChecked = $(this).is(':checked');
                $('#xq-cfg-desire-inc').prop('disabled', !isChecked);
                $('#xq-cfg-desire-dec').prop('disabled', !isChecked);
            });

            $('#xq-cfg-music-ambient').on('change', function() {
                const isChecked = $(this).is(':checked');
                const $btn = $('#xq-btn-toggle-amb');
                $btn.prop('disabled', !isChecked);
                if (!isChecked) {
                    $btn.html('⏸️ 暂停环境音');
                }
            });

            $('#xq-cfg-music-story').on('change', function() {
                const isChecked = $(this).is(':checked');
                const $btn = $('#xq-btn-toggle-sto');
                $btn.prop('disabled', !isChecked);
                if (!isChecked) {
                    $btn.html('⏸️ 暂停剧情音');
                }
            });

            $('#xq-cfg-hide-enable').on('change', function() {
                const isChecked = $(this).is(':checked');
                $('#xq-cfg-hide-inc').prop('disabled', !isChecked);
                $('#xq-cfg-hide-keep').prop('disabled', !isChecked);
                $('#xq-cfg-hide-buf').prop('disabled', !isChecked || !$('#xq-cfg-hide-inc').is(':checked'));
                $('#xq-btn-hide-fl').prop('disabled', !isChecked);
                $('#xq-btn-show-fl').prop('disabled', !isChecked);
            });

            $('#xq-cfg-hide-inc').on('change', function() {
                const isChecked = $(this).is(':checked');
                const isEnableChecked = $('#xq-cfg-hide-enable').is(':checked');
                $('#xq-cfg-hide-buf').prop('disabled', !isEnableChecked || !isChecked);
            });

            $('#xq-cfg-api-enable').on('change', function() {
                const isChecked = $(this).is(':checked');
                $('#xq-cfg-api-url').prop('disabled', !isChecked);
                $('#xq-cfg-api-key').prop('disabled', !isChecked);
                $('#xq-cfg-api-model').prop('disabled', !isChecked);
                $('#xq-cfg-api-tokens').prop('disabled', !isChecked);
                $('#xq-cfg-api-temp').prop('disabled', !isChecked);
            });

            $('#xq-cfg-preset').on('click', (e) => {
                if ($('#xq-cfg-preset').prop('disabled')) return;

                if (typeof getPresetNames === 'function') {
                    try {
                        const presets = getPresetNames();
                        if (presets && presets.length > 0) {
                            const availablePresets = presets.filter(p => p !== 'in_use');
                            this.showDropdown(e.target, availablePresets);
                        } else {
                            toastr.warning('未能获取到预设列表', '提示');
                        }
                    } catch (err) {
                        console.error('[终端控制台] 获取预设列表失败', err);
                    }
                } else {
                    toastr.warning('当前环境不支持自动获取预设列表', '提示');
                }
            });

            $('#xq-cfg-api-model').on('click', async (e) => {
                let baseUrl = $('#xq-cfg-api-url').val().trim();
                let apiKey = $('#xq-cfg-api-key').val().trim();
                const $input = $(e.target);

                if (!baseUrl) {
                    toastr.warning('请先在上方输入接口地址', '缺少参数');
                    return;
                }

                baseUrl = baseUrl.replace(/(\/v1)?\/?$/, '');

                try {
                    $input.prop('placeholder', '正在获取模型列表中...');
                    let headers = { 'Content-Type': 'application/json' };
                    if (apiKey) headers['Authorization'] = `Bearer ${apiKey}`;

                    let res = await fetch(`${baseUrl}/v1/models`, { headers: headers });
                    if (!res.ok) throw new Error(`HTTP ${res.status}`);

                    let json = await res.json();
                    let models = (json.data || []).map(m => m.id);

                    if (models.length === 0) {
                        toastr.warning('接口返回的模型列表为空', '提示');
                        return;
                    }
                    this.showDropdown(e.target, models);
                } catch (err) {
                    toastr.error('获取模型列表失败: ' + err.message, '请求错误');
                } finally {
                    $input.prop('placeholder', '点击获取可用模型，或手动输入');
                }
            });

            $('#xq-btn-restore-cfg').on('click', () => {
                this.restoreDefault();
                const breakLimit = $('#xq-cfg-breaklimit').is(':checked');
                const apiEnable = $('#xq-cfg-api-enable').is(':checked');
                toastr.success(`默认配置：内置破限: ${breakLimit}，独立API: ${apiEnable}`, '重置成功');
            });

            $('#xq-btn-save-cfg').on('click', () => {
                this.saveConfig();
                const btn = $('#xq-btn-save-cfg');
                const originalHtml = btn.html();
                btn.html('保存成功');
                btn.css({'background': '#FF80AB', 'color': '#222'});

                const breakLimit = $('#xq-cfg-breaklimit').is(':checked');
                const apiEnable = $('#xq-cfg-api-enable').is(':checked');
                toastr.success(`更新配置：内置破限: ${breakLimit}，独立API: ${apiEnable}`, '保存成功');

                setTimeout(() => {
                    btn.html(originalHtml);
                    btn.css({'background': '', 'color': ''});
                }, 1000);
            });

            const bindBtn = (id, eventName) => {
                $(`#${id}`).on('click', () => {
                    this.emitXqEvent(eventName);
                });
            };

            // 绑定事件到全局总线
            bindBtn('xq-btn-gen-p', 'XQ_ForceGeneratePlayer');
            bindBtn('xq-btn-gen-o', 'XQ_ForceGenerateObject');
            bindBtn('xq-btn-upd-p', 'XQ_ForceUpdatePlayer');
            bindBtn('xq-btn-upd-o', 'XQ_ForceUpdateObject');

            // XQ_ForceCutLog 现在的语义是：重试压缩往事
            bindBtn('xq-btn-cut-log', 'XQ_ForceCutLog');

            bindBtn('xq-btn-restart', 'XQ_ForceCleanRedundant');
            bindBtn('xq-btn-del-old', 'XQ_ForceDeleteOld');
            bindBtn('xq-btn-clr-all', 'XQ_ForceClearAll');

            $('#xq-btn-toggle-amb').on('click', () => {
                const $btn = $('#xq-btn-toggle-amb');
                if ($btn.text().includes('暂停')) {
                    this.emitXqEvent('XQ_ForcePauseAmbient');
                    $btn.html('▶️ 恢复环境音');
                } else {
                    this.emitXqEvent('XQ_ForceResumeAmbient');
                    $btn.html('⏸️ 暂停环境音');
                }
            });

            $('#xq-btn-toggle-sto').on('click', () => {
                const $btn = $('#xq-btn-toggle-sto');
                if ($btn.text().includes('暂停')) {
                    this.emitXqEvent('XQ_ForcePauseStory');
                    $btn.html('▶️ 恢复剧情音');
                } else {
                    this.emitXqEvent('XQ_ForceResumeStory');
                    $btn.html('⏸️ 暂停剧情音');
                }
            });

            bindBtn('xq-btn-hide-fl', 'XQ_ForceHideFloor');
            bindBtn('xq-btn-show-fl', 'XQ_ForceShowFloor');
        },

        open: function() {
            const overlay = $('#xq-terminal-overlay');
            overlay.css('display', 'flex');
            this.loadConfig(); // 打开面板时读取配置
            requestAnimationFrame(() => overlay.addClass('show'));
        }
    };

    // ==========================================
    // 4. 启动与事件挂载
    // ==========================================

    const startup = () => {
        Terminal.init();

        // 尝试首次注入
        Terminal.injectMenu();
        // 绑定按钮点击事件，实现按需注入，彻底抛弃 MutationObserver
        Terminal.bindMenuTrigger();
    };

    // 原生判断 DOM 状态
    if (document.readyState === 'complete' || document.readyState === 'interactive') {
        startup();
    } else {
        document.addEventListener('DOMContentLoaded', startup);
    }

    // 绑定生命周期钩子，确保退出角色卡时清理残留 DOM 和事件
    $(window).on('pagehide unload', () => {
        $('#xq-terminal-trigger').remove();
        $(document).off('click.xq_terminal_trigger');
        $('#xq-terminal-overlay').remove();
        $('#xq-terminal-style').remove();
    });

})();

/**
==========================================
 变量控制器_v3.1
 作者：Berger
==========================================
*/

(async () => {
    // 等待 MVU 框架就绪
    try {
        await waitGlobalInitialized('Mvu');
    } catch (e) {
        console.error('[VarLimit] Mvu 初始化失败:', e);
        return;
    }

    // 默认保底配置
    const CONFIG = {
        enableFavLimit: true,
        enableDesireLimit: true,
        favMaxInc: 3,
        favMaxDec: 50,
        desireMaxInc: 6,
        desireMaxDec: 100
    };

    // 动态加载配置
    function loadConfig() {
        const targetWindow = (typeof parent !== 'undefined' && parent.window) ? parent.window : window;
        const globalConfig = targetWindow.XQ_Config || {};

        const loadBool = (key, defaultVal) => {
            let val = globalConfig[key];
            if (val === undefined) val = localStorage.getItem(key);
            if (val !== null) return val === true || val === 'true';
            return defaultVal;
        };

        const loadNum = (key, defaultVal) => {
            let val = globalConfig[key];
            if (val === undefined) val = localStorage.getItem(key);
            if (val !== null) {
                const parsed = parseFloat(val);
                if (!isNaN(parsed)) return parsed;
            }
            return defaultVal;
        };

        CONFIG.enableFavLimit = loadBool('XQ_Fav_Limit_Enable', true);
        CONFIG.enableDesireLimit = loadBool('XQ_Desire_Limit_Enable', true);
        CONFIG.favMaxInc = loadNum('XQ_Fav_Max_Inc', 3);
        CONFIG.favMaxDec = loadNum('XQ_Fav_Max_Dec', 50);
        CONFIG.desireMaxInc = loadNum('XQ_Desire_Max_Inc', 6);
        CONFIG.desireMaxDec = loadNum('XQ_Desire_Max_Dec', 100);

        console.log(`[VarLimit] 配置同步: 好感限制=${CONFIG.enableFavLimit}, 情欲限制=${CONFIG.enableDesireLimit}`);
    }

    // 计算差值限制
    function clampValueChange(newValue, oldValue, maxInc, maxDec) {
        if (oldValue === undefined || oldValue === null) return newValue;

        const difference = newValue - oldValue;

        if (difference > 0 && difference > maxInc) {
            return oldValue + maxInc;
        }
        if (difference < 0 && Math.abs(difference) > maxDec) {
            return oldValue - maxDec;
        }

        return newValue;
    }

    // 计算基于对象类型的最高上限
    function getTypeBasedMaxFav(types) {
        let limits = [100]; // 默认上限

        if (Array.isArray(types)) {
            if (types.includes('婚托')) limits.push(50);
            if (types.includes('捞女')) limits.push(70);
            if (types.includes('渣女')) limits.push(90);
            if (types.includes('人妻')) limits.push(99);
        }

        return Math.min(...limits);
    }

    // 计算基于对象类型的最低下限
    function getTypeBasedMinFav(types) {
        let limits = [-100]; // 默认下限

        if (Array.isArray(types)) {
            if (types.includes('正妻型')) limits.push(-50);
            if (types.includes('女神')) limits.push(0);
        }

        return Math.max(...limits);
    }

    // 解析中文时间的辅助函数
    function parseChineseTime(timeStr) {
        if (!timeStr) return null;
        const match = timeStr.match(/(\d{4})年(\d{1,2})月(\d{1,2})日/);
        if (!match) return null;

        const year = parseInt(match[1], 10);
        const month = parseInt(match[2], 10) - 1;
        const day = parseInt(match[3], 10);

        return new Date(year, month, day);
    }

    // 解析并修复时间格式的辅助函数
    function normalizeTimeStr(timeStr) {
        if (!timeStr || typeof timeStr !== 'string') return timeStr;

        const match = timeStr.match(/^(\d{4})年(\d{1,2})月(\d{1,2})日 (\d{1,2}):(\d{1,2})/);
        if (!match) {
            return timeStr;
        }

        const year = parseInt(match[1], 10);
        const month = parseInt(match[2], 10) - 1;
        const day = parseInt(match[3], 10);

        const dateObj = new Date(year, month, day);
        const weekDays = ['日', '一', '二', '三', '四', '五', '六'];
        const correctWeekDay = weekDays[dateObj.getDay()];

        return `${match[1]}年${match[2]}月${match[3]}日 ${match[4]}:${match[5]} 星期${correctWeekDay}`;
    }

    // ================= 模块A: 根目录白名单清洗 =================
    function cleanIllegalRoots(variables) {
        const allowedRoots = [
            '世界状态', '当前事件', '玩家数据',
            '当前活跃对象', '交往对象列表', '历史对象列表', 'schema', '$internal'
        ];

        if (variables && variables.stat_data) {
            // 遍历当前生成的所有根目录
            for (const key of Object.keys(variables.stat_data)) {
                if (!allowedRoots.includes(key)) {
                    // 发现未定义目录直接清理掉
                    _.unset(variables.stat_data, key);
                    console.log(`[VarLimit] 拦截脏数据：已清除擅自创建的非法根目录 [${key}]`);
                }
            }
        }
    }

    // ================= 时间格式化拦截 =================
    function processTimeFormatCheck(variables) {
        const rawTime = _.get(variables, 'stat_data.世界状态.时间');
        if (rawTime) {
            const fixedTime = normalizeTimeStr(rawTime);
            if (rawTime !== fixedTime) {
                _.set(variables, 'stat_data.世界状态.时间', fixedTime);
                console.log(`[VarLimit] 时间格式化修正: ${rawTime} >> ${fixedTime}`);
            }
        }
    }

    // ================= 模块B: 时间流逝与基础数值 =================
    function processTimeAndBasicStats(variables, variablesBeforeUpdate) {
        const currentGlobalTime = _.get(variables, 'stat_data.世界状态.时间', '');
        const oldGlobalTime = _.get(variablesBeforeUpdate, 'stat_data.世界状态.时间', '');

        let dayDiff = 0;

        if (currentGlobalTime && oldGlobalTime && currentGlobalTime !== oldGlobalTime) {
            const currentDate = parseChineseTime(currentGlobalTime);
            const oldDate = parseChineseTime(oldGlobalTime);

            if (currentDate && oldDate) {
                const msPerDay = 1000 * 60 * 60 * 24;
                dayDiff = Math.floor((currentDate.getTime() - oldDate.getTime()) / msPerDay);
                if (dayDiff < 0) dayDiff = 0; // 防止时间倒流导致减去天数
            }
        }

        if (dayDiff > 0) {
            console.log(`[VarLimit] 检测到时间跨越了 ${dayDiff} 天。`);
        }

        // --- 1. 玩家数据强制接管 ---
        let playerOldTime = _.get(variablesBeforeUpdate, 'stat_data.玩家数据.总相亲时长', 0);
        if (typeof playerOldTime !== 'number') playerOldTime = 0;
        let playerNewTime = playerOldTime + dayDiff;
        _.set(variables, 'stat_data.玩家数据.总相亲时长', playerNewTime);

        let playerName = _.get(variables, 'stat_data.玩家数据.姓名', '玩家');
        let playerOldAge = _.get(variablesBeforeUpdate, 'stat_data.玩家数据.年龄', 0);
        if (typeof playerOldAge !== 'number') playerOldAge = 0;
        let playerOldYears = Math.floor(playerOldTime / 365);
        let playerNewYears = Math.floor(playerNewTime / 365);
        let playerAgeIncrease = playerNewYears - playerOldYears;

        if (playerAgeIncrease > 0) {
            let playerNewAge = playerOldAge + playerAgeIncrease;
            _.set(variables, 'stat_data.玩家数据.年龄', playerNewAge);
            console.log(`[VarLimit] 岁月流逝，${playerName} 年龄增长: ${playerOldAge}岁 >> ${playerNewAge}岁`);
        }

        // --- 相亲人数与得吃人数强制接管 ---
        const allObjectsBefore = _.get(variablesBeforeUpdate, 'stat_data.交往对象列表', {});
        const allObjectsCurrent = _.get(variables, 'stat_data.交往对象列表', {});
        const historyList = _.get(variablesBeforeUpdate, 'stat_data.历史对象列表', []);

        let oldTotalDatingCount = _.get(variablesBeforeUpdate, 'stat_data.玩家数据.总相亲人数', 0);
        let oldTotalEatenCount = _.get(variablesBeforeUpdate, 'stat_data.玩家数据.总得吃人数', 0);

        let newDatingIncrease = 0;
        let newEatenIncrease = 0;

        for (let targetName in allObjectsCurrent) {
            let currentData = allObjectsCurrent[targetName];
            let beforeData = allObjectsBefore[targetName];

            if (!beforeData) {
                const isReunion = historyList.some(historyObj => historyObj.对象姓名 === targetName);
                if (!isReunion) {
                    newDatingIncrease += 1;
                    console.log(`[VarLimit] 检测到全新相亲对象: ${targetName}`);
                } else {
                    console.log(`[VarLimit] 检测到对象复合: ${targetName}，不增加总相亲人数`);
                }
            }

            let oldEatenStatus = beforeData ? !!beforeData.是否得吃 : false;
            let newEatenStatus = !!currentData.是否得吃;

            if (!oldEatenStatus && newEatenStatus) {
                newEatenIncrease += 1;
                console.log(`[VarLimit] 恭喜！${targetName} 被拿下了，总得吃人数将增加`);
            }
            else if (oldEatenStatus && !newEatenStatus) {
                currentData.是否得吃 = true;
                _.set(variables, `stat_data.交往对象列表["${targetName}"].是否得吃`, true);
                console.log(`[VarLimit] 拦截异常数据：强行将 ${targetName} 的得吃状态锁定为 true`);
            }
        }

        let finalDatingCount = oldTotalDatingCount + newDatingIncrease;
        let finalEatenCount = oldTotalEatenCount + newEatenIncrease;

        _.set(variables, 'stat_data.玩家数据.总相亲人数', finalDatingCount);
        _.set(variables, 'stat_data.玩家数据.总得吃人数', finalEatenCount);

        if (newDatingIncrease > 0 || newEatenIncrease > 0) {
            console.log(`[VarLimit] 统计更新：总相亲人数 = ${finalDatingCount}，总得吃人数 = ${finalEatenCount}`);
        }

        // --- 2. 所有对象数据强制接管 ---
        const allObjectsListBefore = _.get(variablesBeforeUpdate, 'stat_data.交往对象列表', {});
        const allObjectsListCurrent = _.get(variables, 'stat_data.交往对象列表', {});

        for (let targetName in allObjectsListBefore) {
            let targetDataCurrent = allObjectsListCurrent[targetName];
            let targetDataBefore = allObjectsListBefore[targetName];

            if (!targetDataCurrent || !targetDataBefore) continue;

            let targetOldTime = targetDataBefore.交往时长;
            if (typeof targetOldTime !== 'number') targetOldTime = 0;
            let targetNewTime = targetOldTime + dayDiff;

            targetDataCurrent.交往时长 = targetNewTime;
            _.set(variables, `stat_data.交往对象列表["${targetName}"].交往时长`, targetNewTime);

            let targetOldAge = targetDataBefore.年龄;
            if (typeof targetOldAge !== 'number') targetOldAge = 0;
            let targetOldYears = Math.floor(targetOldTime / 365);
            let targetNewYears = Math.floor(targetNewTime / 365);
            let targetAgeIncrease = targetNewYears - targetOldYears;

            if (targetAgeIncrease > 0) {
                let targetNewAge = targetOldAge + targetAgeIncrease;
                targetDataCurrent.年龄 = targetNewAge;
                _.set(variables, `stat_data.交往对象列表["${targetName}"].年龄`, targetNewAge);
                console.log(`[VarLimit] 岁月流逝，${targetName} 年龄增长: ${targetOldAge}岁 >> ${targetNewAge}岁`);
            }
        }

        return dayDiff;
    }

    // ================= 模块C: 资金结算与限制逻辑 =================
    function processFinanceSettle(variables, variablesBeforeUpdate) {
        const oldCash = _.get(variablesBeforeUpdate, 'stat_data.玩家数据.现金余额', 0);
        const oldTotalSpend = _.get(variablesBeforeUpdate, 'stat_data.玩家数据.总花费金额', 0);

        // 获取AI结算后的当前回合数据
        let currentCash = _.get(variables, 'stat_data.玩家数据.现金余额', oldCash);
        let currentTotalSpend = _.get(variables, 'stat_data.玩家数据.总花费金额', oldTotalSpend);

        // 获取当前活跃对象
        const activeObjectName = _.get(variables, 'stat_data.当前活跃对象', '');

        // 1. 计算 AI 企图造成的开销
        let totalSpendAttemptAI = Math.max(0, currentTotalSpend - oldTotalSpend);

        // 2. 收集所有对象的预期投入增加值
        const allObjectsCurrentSpend = _.get(variables, 'stat_data.交往对象列表', {});
        const allObjectsBeforeSpend = _.get(variablesBeforeUpdate, 'stat_data.交往对象列表', {});

        let objectSpendAttemptTotal = 0;
        const spendRecords = []; // 记录谁要花钱，花多少

        for (let objName in allObjectsBeforeSpend) {
            let oldInvest = allObjectsBeforeSpend[objName].投入金额 || 0;
            let newInvest = allObjectsCurrentSpend[objName]?.投入金额 || oldInvest;
            let attemptAdd = newInvest - oldInvest;

            if (attemptAdd > 0) {
                objectSpendAttemptTotal += attemptAdd;
                spendRecords.push({
                    name: objName,
                    oldInvest: oldInvest,
                    attemptAdd: attemptAdd
                });
            } else if (attemptAdd < 0 && allObjectsCurrentSpend[objName]) {
                // 防止 AI 莫名其妙减少投入金额
                allObjectsCurrentSpend[objName].投入金额 = oldInvest;
                _.set(variables, `stat_data.交往对象列表["${objName}"].投入金额`, oldInvest);
            }
        }

        // 3. 确定最终试图消费总额 (防AI漏加总花费的核心)
        let finalAttemptSpend = Math.max(totalSpendAttemptAI, objectSpendAttemptTotal);

        // 4. 计算不含乱扣费的理论底线
        let theoryMinCash = oldCash - finalAttemptSpend;

        // 5. 结账与防拦截判定
        if (theoryMinCash >= 0) {
            // 【情况A：余额充足，正常结算】
            if (currentCash >= theoryMinCash) {
                // 资金大于等于底线，信任 AI 计算 (包含发工资和正常扣费)，只需强制修正总花费
                _.set(variables, 'stat_data.玩家数据.总花费金额', oldTotalSpend + finalAttemptSpend);
                // 只有产生实际花费时才打印日志
                if (finalAttemptSpend > 0) {
                    console.log(`[VarLimit] 结算正常：当前余额 ${currentCash}，花费 ${finalAttemptSpend}`);
                }
            } else {
                // AI乱扣费，触发防拦截，拉回至底线
                let newCash = theoryMinCash;
                _.set(variables, 'stat_data.玩家数据.现金余额', newCash);
                _.set(variables, 'stat_data.玩家数据.总花费金额', oldTotalSpend + finalAttemptSpend);
                console.log(`[VarLimit] 拦截乱扣费：强制恢复余额至 ${newCash}`);
            }
        } else {
            // 【情况B：余额不足，触发破产】
            console.log(`[VarLimit] 资金结算：余额不足！试图消费 ${finalAttemptSpend}，但只有 ${oldCash}`);

            // 现金强归0，总花费只能加上原有的底子
            _.set(variables, 'stat_data.玩家数据.现金余额', 0);
            _.set(variables, 'stat_data.玩家数据.总花费金额', oldTotalSpend + oldCash);

            // 破产分配优先级：当前活跃对象 > 其他对象
            let availableQuota = oldCash;
            let activeRecord = spendRecords.find(r => r.name === activeObjectName);
            let otherRecords = spendRecords.filter(r => r.name !== activeObjectName);

            const assignQuota = (record) => {
                if (availableQuota <= 0) {
                    // 额度用光，强制还原投入
                    _.set(variables, `stat_data.交往对象列表["${record.name}"].投入金额`, record.oldInvest);
                    if (allObjectsCurrentSpend[record.name]) allObjectsCurrentSpend[record.name].投入金额 = record.oldInvest;
                    return;
                }

                let actualAdd = Math.min(record.attemptAdd, availableQuota);
                let finalInvest = record.oldInvest + actualAdd;
                availableQuota -= actualAdd;

                _.set(variables, `stat_data.交往对象列表["${record.name}"].投入金额`, finalInvest);
                if (allObjectsCurrentSpend[record.name]) allObjectsCurrentSpend[record.name].投入金额 = finalInvest;
                console.log(`[VarLimit] 资金分配：${record.name} 获得 ${actualAdd} 额度`);
            };

            // 分发额度
            if (activeRecord) assignQuota(activeRecord);
            otherRecords.forEach(assignQuota);
        }
    }

    // ================= 模块D: 好感度与情欲值 =================
    function processAffectionAndDesire(variables, variablesBeforeUpdate) {
        const currentTargetList = _.get(variables, 'stat_data.交往对象列表', {});
        const oldTargetList = _.get(variablesBeforeUpdate, 'stat_data.交往对象列表', {});

        // 提取当前事件的新旧编号，用于第0层过滤
        const oldEventStr = _.get(variablesBeforeUpdate, 'stat_data.当前事件.事件编号', '');
        const newEventStr = _.get(variables, 'stat_data.当前事件.事件编号', '');
        const isEventRefreshed = !!(newEventStr && oldEventStr !== newEventStr);
        const eventType = isEventRefreshed ? newEventStr.charAt(0).toUpperCase() : 'NONE';
        const activeObjectName = _.get(variables, 'stat_data.当前活跃对象', '');

        Object.keys(currentTargetList).forEach(targetName => {
            const currentData = currentTargetList[targetName];
            const oldData = oldTargetList[targetName];

            if (!oldData) return;

            const oldDesire = oldData.情欲值 !== undefined ? oldData.情欲值 : 0;
            const oldFav = oldData.好感度 !== undefined ? oldData.好感度 : 0;

            if (currentData.好感度 !== undefined) {

                const typeMaxLimit = getTypeBasedMaxFav(currentData.对象类型);
                const typeMinLimit = getTypeBasedMinFav(currentData.对象类型);

                // 记录AI尝试给出的理论初始值
                let theoryFav = currentData.好感度;

                if (CONFIG.enableFavLimit) {
                    // 1. 好感度事件防篡改预处理 (事件过滤，受总开关控制)
                    if (eventType === 'E') {
                        // E类事件全局解禁
                    } else {
                        // 非E类事件
                        if (targetName === activeObjectName) {
                            if (eventType === 'N') {
                                theoryFav = Math.min(theoryFav, oldFav - 5);
                            } else if (eventType === 'X') {
                                theoryFav = Math.min(theoryFav, oldFav - 50);
                            } else {
                                theoryFav = Math.min(theoryFav, oldFav);
                            }
                        } else {
                            theoryFav = Math.min(theoryFav, oldFav);
                        }
                    }

                    if (theoryFav !== currentData.好感度) {
                        console.log(`[VarLimit] 事件拦截(${targetName}): 新事件类型[${eventType}]，理论好感度修正: ${currentData.好感度} >> ${theoryFav}`);
                    }

                    // 2. 幅度限制
                    // 情欲值小于20时，好感度每次最多增加1 (基于旧情欲值判断)
                    const dynamicMaxInc = oldDesire < 20 ? 1 : CONFIG.favMaxInc;

                    theoryFav = clampValueChange(
                        theoryFav,
                        oldData.好感度,
                        dynamicMaxInc,
                        CONFIG.favMaxDec
                    );
                }

                // 3. 终极审判（核心核对区）：在所有变化之后，统一强行应用上下限边界
                let finalFav = theoryFav;

                if (finalFav > typeMaxLimit) {
                    finalFav = typeMaxLimit;
                    console.log(`[VarLimit] 最终结算触发上限: ${targetName} 锁定至 ${typeMaxLimit}`);
                }

                if (finalFav < typeMinLimit) {
                    finalFav = typeMinLimit;
                    console.log(`[VarLimit] 最终结算触发下限: ${targetName} 锁定至 ${typeMinLimit}`);
                }

                // 最终赋值
                if (finalFav !== currentData.好感度) {
                    if (CONFIG.enableFavLimit && oldDesire < 20 && currentData.好感度 > oldData.好感度 && finalFav < currentData.好感度) {
                        console.log(`[VarLimit] 拦截 ${targetName} 的好感增加: 旧情欲值(${oldDesire}) < 20`);
                    }
                    console.log(`[VarLimit] 最终修正 ${targetName} 的好感度: ${currentData.好感度} >> ${finalFav}`);
                    _.set(variables, `stat_data.交往对象列表["${targetName}"].好感度`, finalFav);
                    currentData.好感度 = finalFav;
                }
            }

            // 情欲值限制
            if (CONFIG.enableDesireLimit && currentData.情欲值 !== undefined) {
                let limitedDesire = clampValueChange(
                    currentData.情欲值,
                    oldData.情欲值,
                    CONFIG.desireMaxInc,
                    CONFIG.desireMaxDec
                );

                if (oldFav < 20 && limitedDesire > 50) {
                    limitedDesire = 50;
                    console.log(`[VarLimit] ${targetName} 触发情欲值限制: 旧好感(${oldFav})<20, 截断至50`);
                }

                const isEaten = !!currentData.是否得吃;
                if (!isEaten && limitedDesire > 50) {
                    limitedDesire = 50;
                    console.log(`[VarLimit] ${targetName} 触发情欲值限制: 未得吃状态, 截断至50`);
                }

                if (limitedDesire !== currentData.情欲值) {
                    console.log(`[VarLimit] 修正 ${targetName} 的情欲值: ${currentData.情欲值} >> ${limitedDesire}`);
                    _.set(variables, `stat_data.交往对象列表["${targetName}"].情欲值`, limitedDesire);
                    currentData.情欲值 = limitedDesire;
                }
            }
        });
    }

    // ================= 模块E: 边缘状态检测与称号系统触发 =================
    function processAchievementsAndTitles(variables, variablesBeforeUpdate) {
        const oldPlayerState = _.get(variablesBeforeUpdate, 'stat_data.玩家数据', {});
        const newPlayerState = _.get(variables, 'stat_data.玩家数据', {});
        const oldTargetStateList = _.get(variablesBeforeUpdate, 'stat_data.交往对象列表', {});
        const newTargetStateList = _.get(variables, 'stat_data.交往对象列表', {});
        const oldHistoryStateList = _.get(variablesBeforeUpdate, 'stat_data.历史对象列表', []);
        const newHistoryStateList = _.get(variables, 'stat_data.历史对象列表', []);

        const awardTitle = (titleName) => {
            _.set(variables, `stat_data.玩家数据.称号列表.${titleName}`, true);
            console.log(`[VarLimit] 达成条件！为玩家添加称号：${titleName}`);
        };

        // 1. 渣男
        const isZhaNan = (player, targetList) => {
            if (player.恋爱阶段 && (player.恋爱阶段.includes('已婚') || player.恋爱阶段.includes('结婚'))) return false;
            return Object.values(targetList).some(obj => obj.交往时长 >= 180 && obj.是否得吃 === true);
        };
        if (!isZhaNan(oldPlayerState, oldTargetStateList) && isZhaNan(newPlayerState, newTargetStateList)) {
            awardTitle('渣男');
        }

        // 2. 海王
        const isHaiWang = (targetList) => {
            return Object.values(targetList).filter(obj => obj.好感度 >= 50).length >= 3;
        };
        if (!isHaiWang(oldTargetStateList) && isHaiWang(newTargetStateList)) {
            awardTitle('海王');
        }

        // 3. 炮王
        const isPaoWang = (player) => (player.总得吃人数 || 0) >= 3;
        if (!isPaoWang(oldPlayerState) && isPaoWang(newPlayerState)) {
            awardTitle('炮王');
        }

        // 4. 曹贼
        const isCaoZei = (targetList) => {
            return Object.values(targetList).some(obj => obj.对象类型 && obj.对象类型.includes('人妻') && obj.是否得吃 === true);
        };
        if (!isCaoZei(oldTargetStateList) && isCaoZei(newTargetStateList)) {
            awardTitle('曹贼');
        }

        // 5. 铁公鸡
        const isTieGongJi = (player) => (player.总相亲时长 || 0) >= 7 && (player.总花费金额 || 0) <= 0;
        if (!isTieGongJi(oldPlayerState) && isTieGongJi(newPlayerState)) {
            awardTitle('铁公鸡');
        }

        // 6. 老实人
        const isHaoRen = (player, targetList) => {
            return (player.总相亲时长 || 0) >= 60 && !Object.values(targetList).some(obj => obj.好感度 >= 50);
        };
        if (!isHaoRen(oldPlayerState, oldTargetStateList) && isHaoRen(newPlayerState, newTargetStateList)) {
            awardTitle('老实人');
        }

        // 7. 大冤种
        const isDaYuanZhong = (historyList) => {
            return historyList.some(obj => obj.交往时长 <= 30 && obj.投入金额 >= 5000);
        };
        if (!isDaYuanZhong(oldHistoryStateList) && isDaYuanZhong(newHistoryStateList)) {
            awardTitle('大冤种');
        }

        // 8. 负心汉
        let fuxinhanTriggered = false;
        for (const [targetName, oldData] of Object.entries(oldTargetStateList)) {
            if (oldData.好感度 >= 70) {
                const newData = newTargetStateList[targetName];
                if (!newData || newData.好感度 <= 50) {
                    fuxinhanTriggered = true;
                    break; // 只要发生一次有效跌落就触发
                }
            }
        }
        if (fuxinhanTriggered) {
            awardTitle('负心汉');
        }
    }

    // ================= 初始化主监听器 =================
    function initializeLimiter() {
        eventMakeFirst(Mvu.events.VARIABLE_UPDATE_ENDED, (variables, variablesBeforeUpdate) => {

            cleanIllegalRoots(variables);

            processTimeFormatCheck(variables);

            processTimeAndBasicStats(variables, variablesBeforeUpdate);

            processFinanceSettle(variables, variablesBeforeUpdate);

            processAffectionAndDesire(variables, variablesBeforeUpdate);

            processAchievementsAndTitles(variables, variablesBeforeUpdate);

        });
    }

    // 监听配置更新
    function setupCommunication() {
        if (typeof eventOn === 'function') {
            eventOn('XQ_ConfigUpdated', loadConfig);
        }
    }

    // 监听来自状态栏、前端等UI层的变量修改广播
    function setupUICommunication() {
        if (typeof eventOn === 'function') {
            eventOn('XQ_UI_UPDATE_VAR', async (data) => {
                if (!data || !data.type) return;

                try {
                    const msgId = (data.messageId !== undefined && data.messageId !== null) ? data.messageId : 'latest';
                    const targetOption = { type: 'message', message_id: msgId };

                    const mvu_data = Mvu.getMvuData(targetOption);
                    if (!mvu_data) {
                        console.warn(`[变量控制] 找不到目标楼层的数据:`, targetOption);
                        return;
                    }

                    // --- VIP 扣费 ---
                    if (data.type === 'buyVip') {
                        let currentMoney = _.get(mvu_data, 'stat_data.玩家数据.现金余额', 0);
                        let currentSpend = _.get(mvu_data, 'stat_data.玩家数据.总花费金额', 0);

                        // 如果在0层且前端使用了缓存兜底，优先用缓存金额作为初始资金
                        if (msgId === 0 && data.isFromCache) {
                            currentMoney = data.initialMoney;
                        }

                        _.set(mvu_data, 'stat_data.玩家数据.现金余额', currentMoney - data.amount);
                        _.set(mvu_data, 'stat_data.玩家数据.总花费金额', currentSpend + data.amount);
                        // 新增写入会员等级
                        _.set(mvu_data, 'stat_data.玩家数据.$会员等级', data.targetLevel);

                        await Mvu.replaceMvuData(mvu_data, targetOption);
                        console.log(`[变量控制] VIP扣费成功: 扣除 ${data.amount}`);

                        if (typeof eventEmit === 'function') eventEmit('XQ_AppStateChanged');
                    }
                    // --- 拉黑/解除拉黑操作 ---
                    else if (data.type === 'toggleBlock') {
                        let blacklist = _.get(mvu_data, 'stat_data.玩家数据.$拉黑列表', []);

                        if (data.isBlockedState) {
                            // 拉黑
                            if (!blacklist.includes(data.targetName)) {
                                blacklist.push(data.targetName);
                                if (blacklist.length > 10) blacklist.shift(); // 限制数组长度
                            }

                            // 清除活跃状态
                            if (_.get(mvu_data, 'stat_data.当前活跃对象') === data.targetName) {
                                _.set(mvu_data, 'stat_data.当前活跃对象', "");
                            }
                        } else {
                            // 解除拉黑
                            blacklist = blacklist.filter(name => name !== data.targetName);

                            // 恢复活跃状态
                            if (_.get(mvu_data, 'stat_data.当前活跃对象') === "") {
                                _.set(mvu_data, 'stat_data.当前活跃对象', data.targetName);
                            }
                        }

                        _.set(mvu_data, 'stat_data.玩家数据.$拉黑列表', blacklist);
                        await Mvu.replaceMvuData(mvu_data, targetOption);
                        console.log(`[变量控制] 切换拉黑状态成功: ${data.targetName} -> ${data.isBlockedState}`);

                        if (typeof eventEmit === 'function') eventEmit('XQ_AppStateChanged');
                    }
                    // --- 详情页发起聊天，新增对象 ---
                    else if (data.type === 'addNewObject') {
                        _.set(mvu_data, `stat_data.交往对象列表["${data.targetName}"]`, data.targetData);
                        _.set(mvu_data, 'stat_data.当前活跃对象', data.targetName);

                        // 手动处理总相亲人数的增加
                        let currentDatingCount = _.get(mvu_data, 'stat_data.玩家数据.总相亲人数', 0);
                        _.set(mvu_data, 'stat_data.玩家数据.总相亲人数', currentDatingCount + 1);

                        // 0层特殊处理：写入地点与玩家额外数据
                        if (msgId === 0) {
                            if (!_.has(mvu_data, 'stat_data.世界状态')) {
                                _.set(mvu_data, 'stat_data.世界状态', {});
                            }
                            let pName = data.playerName && data.playerName.trim() !== '' ? data.playerName : "玩家";
                            _.set(mvu_data, 'stat_data.世界状态.地点', pName + "卧室");

                            // 合并写入额外的玩家变量
                            if (data.playerData) {
                                if (!_.has(mvu_data, 'stat_data.玩家数据')) {
                                    _.set(mvu_data, 'stat_data.玩家数据', {});
                                }
                                let currentPlayerVars = _.get(mvu_data, 'stat_data.玩家数据', {});

                                // ==========================================
                                // --- 余额覆盖前的安全拦截与重算逻辑 ---
                                if (data.playerData["现金余额"] !== undefined) {
                                    // 读取 Mvu 中最真实的当前会员等级
                                    let realVipLevel = _.get(mvu_data, 'stat_data.玩家数据.$会员等级', 0);
                                    const vipPrices = [0, 1000, 10000, 100000];

                                    let originalMoney = Number(data.playerData["现金余额"]);

                                    // 如果已经是会员，自动扣除对应的初始会费
                                    if (realVipLevel > 0 && realVipLevel < vipPrices.length) {
                                        originalMoney -= vipPrices[realVipLevel];
                                    }

                                    data.playerData["现金余额"] = originalMoney;
                                }

                                Object.assign(currentPlayerVars, data.playerData);
                                _.set(mvu_data, 'stat_data.玩家数据', currentPlayerVars);
                            }
                        }

                        await Mvu.replaceMvuData(mvu_data, targetOption);
                        console.log(`[变量控制] 新增对象成功: ${data.targetName}`);

                        if (typeof eventEmit === 'function') {
                            eventEmit('XQ_ActiveObjectChanged', data.targetName);
                            eventEmit('XQ_AppStateChanged');
                        }
                    }
                    // --- 删除对象，转入历史列表 ---
                    else if (data.type === 'deleteObject') {
                        let targetData = _.get(mvu_data, `stat_data.交往对象列表["${data.targetName}"]`);

                        if (targetData) {
                            let historyList = _.get(mvu_data, 'stat_data.历史对象列表', []);
                            let historyItem = {
                                "对象姓名": data.targetName,
                                "对象类型": (Array.isArray(targetData["对象类型"]) && targetData["对象类型"].length > 0) ? targetData["对象类型"][0] : "现实考量型",
                                "交往时长": Number(targetData["交往时长"]) || 0,
                                "投入金额": Number(targetData["投入金额"]) || 0,
                                "是否得吃": Boolean(targetData["是否得吃"]),
                                "失败原因": "被玩家主动拉黑或删除"
                            };

                            historyList.push(historyItem);
                            if (historyList.length > 10) historyList.shift();

                            _.set(mvu_data, 'stat_data.历史对象列表', historyList);
                            _.unset(mvu_data, `stat_data.交往对象列表["${data.targetName}"]`);

                            // 若是活跃对象则清空活跃状态
                            if (_.get(mvu_data, 'stat_data.当前活跃对象') === data.targetName) {
                                _.set(mvu_data, 'stat_data.当前活跃对象', "");
                            }

                            await Mvu.replaceMvuData(mvu_data, targetOption);
                            console.log(`[变量控制] 删除对象成功: ${data.targetName}`);

                            if (typeof eventEmit === 'function') eventEmit('XQ_AppStateChanged');
                        }
                    }
                    // --- 状态栏切换活跃对象 ---
                    else if (data.type === 'setActive') {
                        _.set(mvu_data, 'stat_data.当前活跃对象', data.name);
                        await Mvu.replaceMvuData(mvu_data, targetOption);
                        console.log(`[变量控制] UI设为活跃对象: ${data.name}`);

                        if (typeof eventEmit === 'function') {
                            eventEmit('XQ_ActiveObjectChanged', data.name);
                        }
                    }
                    // --- 状态栏直接更新数组/字段 ---
                    else if (data.type === 'updateArray') {
                        let pathStr = '';
                        if (data.targetType === 'object') {
                            pathStr = `stat_data.交往对象列表["${data.targetName}"].${data.field}`;
                        } else if (data.targetType === 'player') {
                            pathStr = `stat_data.玩家数据.${data.field}`;
                        }

                        if (pathStr) {
                            _.set(mvu_data, pathStr, data.data);
                            await Mvu.replaceMvuData(mvu_data, targetOption);
                            console.log(`[变量控制] UI变量修改成功: ${pathStr} >>`, data.data);
                        }
                    }

                } catch (e) {
                    console.error(`[变量控制] UI变量修改处理失败: 发生错误`, e, data);
                }
            });
        }
    }

    // ================= 启动流程 =================
    loadConfig();
    setupCommunication();
    setupUICommunication();
    initializeLimiter();

})();

