        }
    };

    let isRunningAPI = false;
    let lastExecutedFloorId = null;

    // === 动态配置加载 ===
    function loadConfig() {
        const targetWindow = (typeof parent !== 'undefined' && parent.window) ? parent.window : window;
        const globalConfig = targetWindow.XQ_Config || {};

        const getBool = (key, defaultVal) => {
            if (globalConfig[key] !== undefined) return globalConfig[key];
