            return val !== null ? val === 'true' : defaultVal;
        };
        const getNum = (key, defaultVal) => {
            if (globalConfig[key] !== undefined) return globalConfig[key];
            const val = localStorage.getItem(key);
            if (val !== null) {
                const parsed = parseFloat(val);
                if (!isNaN(parsed)) return parsed;
            }
            return defaultVal;
        };
        const getStr = (key, defaultVal) => {
            if (globalConfig[key] !== undefined) return globalConfig[key];
            const val = localStorage.getItem(key);
            return val !== null ? val : defaultVal;
        };

        CONFIG.useBuiltinBreakLimit = getBool('XQ_UseBuiltinBreakLimit', CONFIG.useBuiltinBreakLimit);
        CONFIG.analysisPreset = getStr('XQ_CustomPresetName', CONFIG.analysisPreset) || "Default";
        CONFIG.strictActiveObjectOnly = getBool('XQ_EnergyMode', CONFIG.strictActiveObjectOnly);
        CONFIG.autoTogglePersona = getBool('XQ_AutoPersona', CONFIG.autoTogglePersona);
        CONFIG.autoClean = getBool('XQ_Auto_Clean', CONFIG.autoClean);

