        CONFIG.logKeepLimit = getNum('XQ_Log_Keep_Limit', CONFIG.logKeepLimit);
        CONFIG.logCutAmount = getNum('XQ_Log_Cut_Amount', CONFIG.logCutAmount);
        CONFIG.appendLogEnabled = getBool('XQ_Append_Log', CONFIG.appendLogEnabled);

        // 留出未来可能在配置面板修改名字的接口
        CONFIG.logEntryName = getStr('XQ_Log_Entry_Name', "相亲日志");
        CONFIG.bakEntryName = getStr('XQ_Bak_Entry_Name', "相亲往事");

        CONFIG.externalApi.enabled = getBool('XQ_Api_Enable', CONFIG.externalApi.enabled);
        CONFIG.externalApi.url = getStr('XQ_Api_Url', CONFIG.externalApi.url);
        CONFIG.externalApi.apiKey = getStr('XQ_Api_Key', CONFIG.externalApi.apiKey);
        CONFIG.externalApi.model = getStr('XQ_Api_Model', CONFIG.externalApi.model);
        CONFIG.externalApi.max_tokens = getNum('XQ_Api_Tokens', CONFIG.externalApi.max_tokens);
        CONFIG.externalApi.temperature = getNum('XQ_Api_Temp', CONFIG.externalApi.temperature);
    }

    loadConfig();

    // ==========================================
    // 一、基础辅助工具
    // ==========================================
    function getCurrentChatId() { return typeof SillyTavern.getCurrentChatId === 'function' ? SillyTavern.getCurrentChatId() : null; }
    function getScopedEntryName(baseName, chatId = null) { const id = chatId || getCurrentChatId(); return id ? `${baseName}_XQ_${id}` : baseName; }
    function isValidName(name) { if (!name) return false; const str = String(name).trim(); return !(["N/A", "未知", "待初始化", "未知玩家", "none", "null", ""].includes(str)) && str.length > 0; }

    function getStatData(messageId = null) {
        try {
            const targetId = messageId !== null ? messageId : getLastMessageIdSafe();
            if (targetId >= 0 && typeof Mvu !== 'undefined' && Mvu.getMvuData) {
                const mvuData = Mvu.getMvuData({ type: 'message', message_id: targetId });
                if (mvuData && mvuData.stat_data) return mvuData.stat_data;
            }
            if (targetId >= 0) {
                const msgVars = getVariables({type: 'message', message_id: targetId});
                if (msgVars && msgVars.stat_data) return msgVars.stat_data;
            }
            return getVariables({type: 'chat'})?.stat_data || null;
        } catch (e) { return null; }
    }

    function getActivePersonaEntries(statData) {
        if (!statData?.当前活跃对象 || !statData.交往对象列表?.[statData.当前活跃对象]?.对象类型) return [];
        const types = statData.交往对象列表[statData.当前活跃对象].对象类型;
        return Array.isArray(types) ? types.map(t => `${t}_人设`) : [];
    }

    function getActiveWorldbookName() { const names = getCharWorldbookNames('current'); return names ? (names.primary || (names.additional?.length > 0 ? names.additional[0] : null)) : null; }
    function getLastMessageIdSafe() { return typeof getLastMessageId === 'function' ? getLastMessageId() : 0; }
    function getWatermark(content, tag) { if (!content) return -1; const regex = new RegExp(`<!--\\s*${tag}:\\s*(\\d+)\\s*-->`); const match = content.match(regex); return match ? parseInt(match[1], 10) : -1; }

    // 提取最后一条日志的 MarkLine 和 时间
    function extractLastLogWatermark(text) {
        if (!text) return { markLine: -1, timeStr: "未知时间" };
        const lines = text.split('\n');

        let lastMark = -1;
        let lastTime = "";

        for (let i = 0; i < lines.length; i++) {
            const line = lines[i];

            const markMatch = line.match(/<!--\s*MarkLine:\s*(\d+)\s*-->/);
            if (markMatch) {
                lastMark = parseInt(markMatch[1], 10);
                continue;
            }

            if (lastMark !== -1) {
                const timeMatch = line.match(/^\[(.*?)\]/);
                if (timeMatch) {
                    lastTime = timeMatch[1];
                }
            }
        }
        return { markLine: lastMark !== -1 ? lastMark : 0, timeStr: lastTime || "未知时间" };
    }

    // 从末尾往前查找最后一个 MarkLine，避免正则全文扫描
    function getLastMarkLineFromEnd(content) {
        if (!content) return -1;
        const searchStr = "<!-- MarkLine: ";
        const lastIndex = content.lastIndexOf(searchStr);
        if (lastIndex === -1) return -1;

        const startIndex = lastIndex + searchStr.length;
        const endIndex = content.indexOf(" -->", startIndex);
        if (endIndex !== -1) {
            return parseInt(content.substring(startIndex, endIndex), 10);
        }
        return -1;
    }

    // 提取相亲日志末尾的纯事件内容
    function extractLastLogEventContent(logText) {
        if (!logText) return "";
        const searchStr = "<!-- MarkLine: ";
        const lastIndex = logText.lastIndexOf(searchStr);
        if (lastIndex === -1) return "";

        const lastLogBlock = logText.substring(lastIndex);
        const lines = lastLogBlock.split('\n');
        const contentLines = [];

        for (let i = 0; i < lines.length; i++) {
            const line = lines[i].trim();
            if (!line) continue;
            if (line.startsWith("<!-- MarkLine:")) continue;
            if (line.startsWith("[")) continue;
            contentLines.push(line);
        }
        return contentLines.join('\n');
    }

    // 清理所有系统水印，确保发给AI的是纯净数据
    function cleanWatermarks(content) {
        if (!content) return content;
        let clean = content.replace(/<!--[\s\S]*?-->\n?/g, "").trim();
        return clean.replace(/档案更新时间:\s*\[.*?\]\n?/g, "").trim();
    }

    function getLoadedPresetNameSafe() { if (typeof getLoadedPresetName === 'function') return getLoadedPresetName(); return 'Default'; }

    const LOG_TITLE = "【相亲日志】\n";
    const BAK_TITLE = "【相亲往事】\n";
    const PENDING_COMPRESS = "<!-- PendingCompress -->\n";
    const PENDING_UPDATE = "<!-- PendingUpdate -->\n";
    const getTimeMark = (time) => `档案更新时间: [${time}]\n`;
    const getUpdateMark = (tag, id) => `<!-- ${tag}: ${id} -->\n`;

    function stripTitle(content, titleString) {
        if (!content) return "";
        if (content.startsWith(titleString)) {
            return content.substring(titleString.length);
        }
        return content;
    }

    function ensureTitle(content, titleString) {
        if (!content) return "";
        if (!content.startsWith(titleString)) {
            return titleString + content;
        }
        return content;
    }

    // 档案过期与强制更新
    async function checkProfileExpiration(message_id) {
        const wbName = getActiveWorldbookName();
        if (!wbName) return;

        try {
            const wb = await getWorldbook(wbName);
            const targetEntries = wb.filter(e =>
                (e.name.startsWith('玩家_') || e.name.startsWith('对象_')) &&
                e.name.includes(`_XQ_${getCurrentChatId()}`) &&
                !e.name.endsWith('_bak')
            );

            for (const entry of targetEntries) {
                // 如果已经打了待更新水印，直接跳过，防止重复触发
                if (entry.content.includes('<!-- PendingUpdate -->')) continue;

                const isPlr = entry.name.startsWith('玩家_');
                const tag = isPlr ? 'LastUpdatePlayer' : 'LastUpdateObj';
                const watermark = getWatermark(entry.content, tag);

                if (watermark >= 0) {
                    const diff = message_id - watermark;
                    const cleanName = entry.name.replace(`_XQ_${getCurrentChatId()}`, '');

                    if (CONFIG.forceUpdateEnable) {
                        // 只要大于等于阈值，立刻打水印
                        if (diff >= CONFIG.forceUpdateFloor) {
                            if (typeof toastr !== 'undefined') {
                                toastr.info(`【${cleanName}】档案距上次更新已达 ${diff} 层，已自动加入更新队列。`, '触发自动更新');
                            }
                            const newContent = entry.content + PENDING_UPDATE;
                            await upsertStandardEntry(wbName, entry.name, newContent, entry.position ? entry.position.order : 10, true);
                        }
                    } else {
                        // 仅在刚好等于阈值时弹窗一次，防止每层都弹窗
                        if (diff === CONFIG.forceUpdateFloor) {
                            if (typeof toastr !== 'undefined') {
                                toastr.warning(`【${cleanName}】档案距上次更新已经达到 ${CONFIG.forceUpdateFloor} 层，如果需要请手动更新。`, '档案滞后提示', {timeOut: 10000});
                            }
                        }
                    }
                }
            }
        } catch (e) {
            console.error('[档案过期检查异常]', e);
        }
    }


    // ==========================================
    // 二、数据流转与版本控制
    // ==========================================
    async function enforceLogAlignment() {
        const wbName = getActiveWorldbookName();
        if (!wbName) return { success: false, msg: "" };

        const logName = getScopedEntryName(CONFIG.logEntryName);
        const bakName = getScopedEntryName(CONFIG.bakEntryName);

        try {
            const wb = await getWorldbook(wbName);
            const logEntry = wb.find(e => e.name === logName);
            const bakEntry = wb.find(e => e.name === bakName);

            let logContent = stripTitle(logEntry ? logEntry.content : "", LOG_TITLE);
            let bakContent = stripTitle(bakEntry ? bakEntry.content : "", BAK_TITLE);
            let changed = false;

            // 只进行多余部分的裁切
            if (logContent.length > CONFIG.logKeepLimit + CONFIG.logCutAmount) {
                const targetIndex = logContent.length - CONFIG.logKeepLimit;
                const markRegex = /<!--\s*MarkLine:\s*(\d+)\s*-->/g;
                let match;
                let bestCutIndex = -1;

                while ((match = markRegex.exec(logContent)) !== null) {
                    if (match.index >= targetIndex) {
                        bestCutIndex = match.index;
                        break;
                    }
                }

                if (bestCutIndex !== -1) {
                    const cutOutText = logContent.substring(0, bestCutIndex);
                    logContent = logContent.substring(bestCutIndex);

                    if (cutOutText) {
                        bakContent = bakContent + cutOutText + PENDING_COMPRESS;
                    }
                    changed = true;
                }
            }

            if (changed) {
                await upsertStandardEntry(wbName, logName, ensureTitle(logContent, LOG_TITLE), 100, true);
                await upsertStandardEntry(wbName, bakName, ensureTitle(bakContent, BAK_TITLE), 99, true);

                // 返回标记以供立即触发压缩
                return { success: true, triggerCompress: true };
            }

            return { success: false };

        } catch (e) {
            console.error('[日志对齐异常]', e);
            return { success: false };
        }
    }

    async function processLogAndRecover(message_id) {
        const wbName = getActiveWorldbookName();
        if (!wbName) return;

        const anchorId = Math.max(0, message_id - CONFIG.anchorOffset);
        const logName = getScopedEntryName(CONFIG.logEntryName);
        const bakName = getScopedEntryName(CONFIG.bakEntryName);

        try {
            const wb = await getWorldbook(wbName);
            const entry = wb.find(e => e.name === logName);
            const bakEntry = wb.find(e => e.name === bakName);

            if (!entry) return;

            let currentContent = stripTitle(entry.content, LOG_TITLE);
            let contentChanged = false;
            let toastConfig = null;

            // 1. 相亲日志的直接截断
            const markRegex = /<!--\s*MarkLine:\s*(\d+)\s*-->/g;
            let match;
            let cutIndex = -1;

            while ((match = markRegex.exec(currentContent)) !== null) {
                if (parseInt(match[1], 10) > anchorId) {
                    cutIndex = match.index;
                    break;
                }
            }

            if (cutIndex !== -1) {
                currentContent = currentContent.substring(0, cutIndex);
                contentChanged = true;
                toastConfig = { type: 'info', msg: `剧情回退，已截断冗余日志 (锚点:${anchorId})。`, title: '数据安全' };
            }

            let bakContent = stripTitle(bakEntry ? bakEntry.content : "", BAK_TITLE);
            let bakChanged = false;

            // 2. 往事的比对与恢复
            if (bakContent) {
                const bakSummaryVal = getWatermark(bakContent, 'LastSummary');
                // 如果当前往事的压缩水印越界了
                if (bakSummaryVal > anchorId) {
                    const realBakEntryName = `${bakName}_bak`;
                    const realBakEntry = wb.find(e => e.name === realBakEntryName);

                    if (realBakEntry && realBakEntry.content && realBakEntry.content.trim() !== "") {
                        const realBakWatermark = getWatermark(realBakEntry.content, 'LastSummary');
                        // 检查 bak 是否也越界
                        if (realBakWatermark > anchorId) {
                            bakContent = "";
                            bakChanged = true;
                            if (!contentChanged && cutIndex === -1 && currentContent === "") {
                                toastConfig = { type: 'warning', msg: `剧情回退过深，备份已经失效，往事已重置 (锚点:${anchorId})。`, title: '数据熔断' };
                            }
                        } else {
                            // 恢复 bak 并清洗 PendingCompress 水印
                            bakContent = realBakEntry.content.replace(/<!--\s*PendingCompress\s*-->\n?/g, "");
                            bakContent = stripTitle(bakContent, BAK_TITLE); // 确保去头，方便后续统一处理
                            bakChanged = true;
                            if (!contentChanged && cutIndex === -1 && currentContent === "") {
                                toastConfig = { type: 'info', msg: `剧情回退，往事已成功回滚至安全快照 (锚点:${anchorId})。`, title: '数据安全' };
                            }
                        }
                    } else {
                        // 没有备份可用
                        bakContent = "";
                        bakChanged = true;
                        if (!contentChanged && cutIndex === -1 && currentContent === "") {
                            toastConfig = { type: 'warning', msg: `剧情回退过深，历史记忆流失，且无可用备份，往事已重置 (锚点:${anchorId})。`, title: '数据熔断' };
                        }
                    }
                }

                // 3. 执行二次删楼/残留日志的全局截断扫描
                if (bakContent) {
                    const recoverMarkRegex = /<!--\s*MarkLine:\s*(\d+)\s*-->/g;
                    let rMatch;
                    let rCutIndex = -1;

                    while ((rMatch = recoverMarkRegex.exec(bakContent)) !== null) {
                        if (parseInt(rMatch[1], 10) > anchorId) {
                            rCutIndex = rMatch.index;
                            break;
                        }
                    }

                    if (rCutIndex !== -1) {
                        bakContent = bakContent.substring(0, rCutIndex);
                        bakChanged = true; // 如果发生了截断，也要标记以便触发保存
                    }
                }
            }

            if (contentChanged || bakChanged) {
                if (contentChanged) await upsertStandardEntry(wbName, logName, ensureTitle(currentContent, LOG_TITLE), 100, true);
                if (bakChanged) {
                    if (bakContent) await upsertStandardEntry(wbName, bakName, ensureTitle(bakContent, BAK_TITLE), 99, true);
                    else await upsertStandardEntry(wbName, bakName, "", 99, true);
                }

                if (toastConfig && typeof toastr !== 'undefined' && toastr[toastConfig.type]) {
                    toastr[toastConfig.type](toastConfig.msg, toastConfig.title);
                }
            }
        } catch (e) { console.error('[日志回滚异常]', e); }
    }


    async function appendLogSnapshot(message_id) {
        if (!CONFIG.appendLogEnabled) return;

        const wbName = getActiveWorldbookName();
        if (!wbName) return;

        if (message_id <= CONFIG.anchorOffset) return;
        const targetId = message_id - CONFIG.anchorOffset;

        let targetStatData = null;
        try {
            const mvuData = Mvu.getMvuData({ type: 'message', message_id: targetId });
            targetStatData = mvuData?.stat_data || mvuData;
        } catch (e) { return; }

        if (!targetStatData?.当前事件?.事件内容) return;

        const event = targetStatData.当前事件;
        const world = targetStatData.世界状态;
        const logName = getScopedEntryName(CONFIG.logEntryName);
        const entry = (await getWorldbook(wbName)).find(e => e.name === logName);

        let content = stripTitle(entry ? entry.content : "", LOG_TITLE);

        // 获取日志末尾的纯事件内容
        const lastLogEventContent = extractLastLogEventContent(content);
        // 获取当前锚点楼层的事件内容
        const currentEventContent = event.事件内容.trim();

        // 核心逻辑：比对内容
        if (lastLogEventContent !== currentEventContent) {
            // 内容不同，执行追加
            const newLogPart = `<!-- MarkLine: ${targetId} -->\n[${world.时间}] ${world.地点}\n${currentEventContent}\n`;
            const finalContent = content + newLogPart;

            await upsertStandardEntry(wbName, logName, ensureTitle(finalContent, LOG_TITLE), 100, true);
            const alignResult = await enforceLogAlignment();

            // 裁切发生时，立即触发任务检测，保证往事压缩的高优先级
            if (alignResult && alignResult.triggerCompress) {
                const pending = await evaluateTasks(message_id);
                if (pending.length > 0) {
                    lastExecutedFloorId = `${getCurrentChatId()}_${message_id}`;
                    await executeSingleTask(pending[0], message_id, false);
                }
            }
        } else {
            // 内容相同，不追加，也不修改 MarkLine，保持最早期 ID
            return;
        }
    }

    // [档案回滚机制]
    async function processProfileRecover(message_id, isSwiped = false) {
        if (message_id < 0) return;

        const wbName = getActiveWorldbookName();
        if (!wbName) return;

        const currentId = message_id;

        try {
            const wb = await getWorldbook(wbName);
            const targetEntries = wb.filter(e =>
                e?.name &&
                (e.name.startsWith('玩家_') || e.name.startsWith('对象_')) &&
                e.name.includes(`_XQ_${getCurrentChatId()}`) &&
                !e.name.endsWith('_bak')
            );

            for (const entry of targetEntries) {
                const isPlr = entry.name.startsWith('玩家_');
                const tag = isPlr ? 'LastUpdatePlayer' : 'LastUpdateObj';
                const watermark = getWatermark(entry.content, tag);

                // 根据是否为滑屏事件，采用精确等于或安全大于的判定逻辑
                const isDistorted = isSwiped ? (currentId === watermark) : (currentId < watermark);

                if (isDistorted) {
                    let newContent = "";
                    let msg = null;
                    let type = 'info';
                    let title = '档案维护';

                    const bakName = `${entry.name}_bak`;
                    const bakEntry = wb.find(e => e?.name === bakName);

                    if (bakEntry && bakEntry.content && bakEntry.content.trim() !== "") {
                        if (currentId === watermark) {
                            newContent = bakEntry.content;
                            msg = `【${entry.name}】已清除失真数据，回滚至安全备份。`;
                            type = 'info';
                            title = '数据清洗';
                        } else {
                            const bakWatermark = getWatermark(bakEntry.content, tag);
                            if (bakWatermark > currentId) {
                                newContent = "";
                                msg = `【${entry.name}】备份档案也已失真，已清空条目等待重新生成。`;
                                type = 'warning';
                                title = '数据熔断';
                            } else {
                                newContent = bakEntry.content;
                                msg = `【${entry.name}】已成功回滚至安全版本。`;
                                type = 'info';
                                title = '数据安全';
                            }
                        }
                    } else {
                        newContent = "";
                        msg = `【${entry.name}】档案失真且无备份可用，已重置档案等待重新生成。`;
                        type = 'warning';
                        title = '回滚警告';
                    }

                    await upsertStandardEntry(wbName, entry.name, newContent, entry.position ? entry.position.order : 10, true);

                    if (msg && typeof toastr !== 'undefined' && toastr[type]) {
                        toastr[type](msg, title);
                    }
                }
            }

        } catch (e) {
            console.error('[档案回滚异常]', e);
            if (typeof toastr !== 'undefined') toastr.error(`档案回滚模块发生错误: ${e.message}`, '系统异常');
        }
    }

    // ==========================================
    // 三、变量监听与触发标记
    // ==========================================
    function initializeVariableWatcher() {
        if (typeof Mvu === 'undefined' || !Mvu.events) return;

        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, async (variables, variablesBeforeUpdate) => {
            const wbName = getActiveWorldbookName();
            if (!wbName) return;

            const currentStat = _.get(variables, 'stat_data', {});
            const oldStat = _.get(variablesBeforeUpdate, 'stat_data', {});

            let changedEntries = [];

            // 1. 玩家恋爱阶段检测
            const curPhase = _.get(currentStat, '玩家数据.恋爱阶段');
            const oldPhase = _.get(oldStat, '玩家数据.恋爱阶段');
            const pName = _.get(currentStat, '玩家数据.姓名');
            if (curPhase && oldPhase && curPhase !== oldPhase && isValidName(pName)) {
                changedEntries.push(getScopedEntryName(`玩家_${pName}`));
            }

            // 2. 当前对象交往状态检测
            const objName = currentStat.当前活跃对象;
            if (isValidName(objName)) {
                const curState = _.get(currentStat, `交往对象列表["${objName}"].交往状态`);
                const oldState = _.get(oldStat, `交往对象列表["${objName}"].交往状态`);
                if (curState && oldState && curState !== oldState) {
                    changedEntries.push(getScopedEntryName(`对象_${objName}`));
                }
            }

            if (changedEntries.length > 0) {
                const wb = await getWorldbook(wbName);
                for (const eName of changedEntries) {
                    const entry = wb.find(e => e.name === eName);
                    if (entry && entry.content && entry.content.trim() !== "" && !entry.content.includes('<!-- PendingUpdate -->')) {
                        const newContent = entry.content + PENDING_UPDATE;
                        await upsertStandardEntry(wbName, eName, newContent, entry.position ? entry.position.order : 10, true);
                        console.log(`[变量监听] 状态变更，已为 ${eName} 追加待更新标记。`);
                    }
                }
            }
        });
    }

    // ==========================================
    // 四、世界书隔离与自动清理
    // ==========================================
    async function enforceWorldbookIsolation(renderMode = 'debounced') {
        const currentChatId = getCurrentChatId();
        const wbName = getActiveWorldbookName();
        if (!wbName || !currentChatId) return;

        let activeObjectName = null;
        let activePersonaNames = [];
        let activeKeys = [];

        const statData = getStatData(getLastMessageIdSafe());
        if (statData) {
            activeObjectName = statData.当前活跃对象;
            if (statData.交往对象列表) {
                activeKeys = Object.keys(statData.交往对象列表);
            }
            if (CONFIG.autoTogglePersona) {
                activePersonaNames = getActivePersonaEntries(statData);
            }
        }

        try {
            // 加入脏检查预检
            const currentWb = await getWorldbook(wbName);
            let hasChanges = false;
            const targetFlag = `_XQ_${currentChatId}`;

            for (let entry of currentWb) {
                const isObj = entry.name.startsWith("对象_");
                const isSys = isObj || entry.name.startsWith("玩家_") || entry.name.startsWith(CONFIG.logEntryName) || entry.name.startsWith(CONFIG.bakEntryName);
                const isPersona = entry.name.endsWith("_人设");

                let shouldBeEnabled = entry.enabled;

                if (isSys && entry.name.includes("_XQ_")) {
                    const isCurrentChat = entry.name.includes(targetFlag) && !entry.name.endsWith('_bak');
                    shouldBeEnabled = isCurrentChat;

                    if (shouldBeEnabled && isObj) {
                        const match = entry.name.match(/^对象_(.+?)_XQ_/);
                        const entryObjName = match ? match[1] : entry.name.replace('对象_', '').replace(`_XQ_${currentChatId}`, '');

                        if (!activeKeys.includes(entryObjName)) {
                            shouldBeEnabled = false;
                        }

                        if (shouldBeEnabled && CONFIG.strictActiveObjectOnly) {
                            if (isValidName(activeObjectName) && entryObjName !== activeObjectName) {
                                shouldBeEnabled = false;
                            }
                        }
                    }
                }

                // 增加安全限制，只有在授权操控且变量不为空的情况下才进行越权干涉
                if (isPersona && CONFIG.autoTogglePersona) {
                    shouldBeEnabled = activePersonaNames.includes(entry.name);
                }

                if (entry.enabled !== shouldBeEnabled) {
                    hasChanges = true;
                    break;
                }
            }

            // 无变动则阻断后续极重的全量更新
            if (!hasChanges) return;

            await updateWorldbookWith(wbName, wb => {
                const targetFlag = `_XQ_${currentChatId}`;

                wb.forEach(entry => {
                    const isObj = entry.name.startsWith("对象_");
                    const isSys = isObj || entry.name.startsWith("玩家_") || entry.name.startsWith(CONFIG.logEntryName) || entry.name.startsWith(CONFIG.bakEntryName);
                    const isPersona = entry.name.endsWith("_人设");

                    if (isSys && entry.name.includes("_XQ_")) {
                        const isCurrentChat = entry.name.includes(targetFlag) && !entry.name.endsWith('_bak');
                        let shouldBeEnabled = isCurrentChat;

                        if (shouldBeEnabled && isObj) {
                            const match = entry.name.match(/^对象_(.+?)_XQ_/);
                            const entryObjName = match ? match[1] : entry.name.replace('对象_', '').replace(`_XQ_${currentChatId}`, '');

                            if (!activeKeys.includes(entryObjName)) {
                                shouldBeEnabled = false;
                            }

                            if (shouldBeEnabled && CONFIG.strictActiveObjectOnly) {
                                if (isValidName(activeObjectName) && entryObjName !== activeObjectName) {
                                    shouldBeEnabled = false;
                                }
                            }
                        }
                        if (entry.enabled !== shouldBeEnabled) {
                            entry.enabled = shouldBeEnabled;
                        }
                    }

                    // 修改写入部分的控制隔离
                    if (isPersona && CONFIG.autoTogglePersona) {
                        const shouldEnable = activePersonaNames.includes(entry.name);
                        if (entry.enabled !== shouldEnable) {
                            entry.enabled = shouldEnable;
                        }
                    }
                });
                return wb;
            }, { render: renderMode });
        } catch (e) {}
    }

    async function executeSilentAutoClean() {
        if (!CONFIG.autoClean) return;
        const w = getActiveWorldbookName();
        const c = getCurrentChatId();
        if (!w || !c) return;

        try {
            let n = 0;
            await updateWorldbookWith(w, wb => {
                return wb.filter(e => {
                    if ((e.name.startsWith("对象_") || e.name.startsWith("玩家_") || e.name.startsWith(CONFIG.logEntryName) || e.name.startsWith(CONFIG.bakEntryName)) && e.name.includes("_XQ_") && !e.name.includes(`_XQ_${c}`)) {
                        n++;
                        return false;
                    }
                    return true;
                });
            }, { render: 'debounced' });

            if (n > 0) {
                if (typeof toastr !== 'undefined') toastr.success(`自动清理已执行，删除了 ${n} 个非当前时间线的条目。`, '清理完成');
            }
        } catch (e) {
            console.error('[自动清理异常]', e);
        }
    }

    // ==========================================
    // 五、数据组装与调用
    // ==========================================
    async function pureGenerate(prompt, injectContent = "", varsStr = "", tag = "data", requireHistory = false, trimCount = 0, whitelist = [], wbName, maxHistory = 2) {
        let historyText = "";

        if (requireHistory && maxHistory > 0) {
            let chatArr = [];
            if (typeof chat !== 'undefined' && Array.isArray(chat)) chatArr = chat;
            else if (typeof SillyTavern !== 'undefined' && SillyTavern.getContext) chatArr = SillyTavern.getContext().chat || [];

            const validMsgs = chatArr.filter(m => m && !m.is_system && m.mes && m.mes.trim() !== '');
            const validCount = Math.max(1, validMsgs.length - trimCount);
            const sliceStart = Math.max(0, validCount - maxHistory);

            let processedHistoryArr = [];
            const slicedMsgs = validMsgs.slice(sliceStart, validCount);

            for (const m of slicedMsgs) {
                const name = m.is_user ? SillyTavern.name1 : SillyTavern.name2;
                let cleanMsg = m.mes.replace(/<StatusPlaceHolderImpl\/>/g, "");

                const thinkEndTags = ['</think>', '</thinking>', '</think_nya~>', '</konatan_planning~>'];
                let maxEndIndex = -1;
                for (const t of thinkEndTags) {
                    const idx = cleanMsg.lastIndexOf(t);
                    if (idx !== -1 && (idx + t.length) > maxEndIndex) maxEndIndex = idx + t.length;
                }
                if (maxEndIndex !== -1) cleanMsg = cleanMsg.substring(maxEndIndex);

                const targetTags = ['UpdateVariable', 'Analysis', 'snow', 'action', 'details', 'summary', 'tucao'];
                targetTags.forEach(tag => {
                    const safeRegex = new RegExp(`<${tag}>((?!<${tag}>)[\\s\\S])*?<\\/${tag}>`, 'gi');
                    cleanMsg = cleanMsg.replace(safeRegex, "");
                });

                const sourceType = m.is_user ? 'user_input' : 'ai_output';
                let processedMsg = cleanMsg.trim();

                if (typeof formatAsTavernRegexedString === 'function') {
                    try {
                        processedMsg = formatAsTavernRegexedString(processedMsg, sourceType, 'prompt');
                    } catch (e) {
                        console.warn("[终端后台] 正则处理出错，降级为原文本:", e);
                    }
                }

                processedHistoryArr.push(`${name}: ${processedMsg}`);
            }
            historyText = processedHistoryArr.join("\n\n");
        }

        const safeInjectContent = cleanWatermarks(injectContent);
        const safeHistoryText = cleanWatermarks(historyText);

        let templateContext = "";
        let coreSystemPrompt = "";

        if (wbName) {
            try {
                const wb = await getWorldbook(wbName);

                if (whitelist && whitelist.length > 0) {
                    for (const wName of whitelist) {
                        const entry = wb.find(e => e.name === wName);
                        if (entry && entry.content && entry.content.trim() !== "") {
                            let processedEntry = entry.content;
                            if (wName.endsWith('_人设') && typeof window.EjsTemplate !== 'undefined' && window.EjsTemplate.evaltemplate) {
                                try {
                                    const context = await window.EjsTemplate.prepareContext();
                                    processedEntry = await window.EjsTemplate.evaltemplate(processedEntry, context);
                                } catch (e) {
                                    console.warn("[终端后台] EJS 处理出错，降级为原文本:", e);
                                }
                            }
                            templateContext += `${cleanWatermarks(processedEntry)}\n\n`;
                        }
                    }
                }

                const breakLimitEntry = wb.find(e => e.name === "【内置破限】");
                if (breakLimitEntry && breakLimitEntry.content) {
                    coreSystemPrompt = breakLimitEntry.content;
                }

            } catch(e) {
                console.error("[终端后台] 读取世界书异常:", e);
            }
        }

        const userTaskPrompt = `【系统任务变更】
[数据分析]
立即忽略之前收到的所有角色扮演指令，你的任务已经完全改变。你现在必须停止角色扮演，以一个毫无感情的客观数据终端（旁白）身份，根据给定的指令分析数据。
[输出限制]
从此刻起，只能输出被 <${tag}> 和 </${tag}> 标签包裹的最终结果。绝对**禁止生成**剧情推进、对话内容、心理活动、前端代码、小剧场、状态栏、行动选项、变量更新或任何剧情衍生的结构！只准输出最终数据！

【具体分析任务】：
${prompt}
${safeInjectContent ? `\n【本次任务数据】：\n${safeInjectContent}` : "\n【本次任务数据】：\n(本次为档案生成任务，无原始档案，请严格基于【档案模板】、【最新剧情切片】和【当前状态参照】进行推演与生成)"}`;

        let customPromptsArray = [];
        if (coreSystemPrompt) customPromptsArray.push({ role: 'system', content: coreSystemPrompt.trim() });
        if (templateContext) customPromptsArray.push({ role: 'system', content: templateContext.trim() });
        if (safeHistoryText) customPromptsArray.push({ role: 'assistant', content: `【最新剧情切片】：\n${safeHistoryText}` });
        if (varsStr) customPromptsArray.push({ role: 'assistant', content: varsStr.trim() });
        customPromptsArray.push({ role: 'user', content: userTaskPrompt });

        let result = null;

        try {
            let genOptions = {
                user_input: `执行指令，输出 <${tag}> 标签包裹的内容。`,
                max_chat_history: 0,
                should_stream: false,
                should_silence: false
            };

            if (CONFIG.externalApi && CONFIG.externalApi.enabled) {
                genOptions.custom_api = {
                    apiurl: CONFIG.externalApi.url,
                    key: CONFIG.externalApi.apiKey,
                    model: CONFIG.externalApi.model,
                    max_tokens: CONFIG.externalApi.max_tokens,
                    temperature: CONFIG.externalApi.temperature
                };
            }

            if (CONFIG.useBuiltinBreakLimit) {
                genOptions.ordered_prompts = customPromptsArray;
                try {
                    result = await generateRaw(genOptions);
                } catch (e) {
                    throw e;
                }
            } else {
                const backupStates = {};
                const originalPresetName = getLoadedPresetNameSafe();
                let stateRestored = false;

                const restoreState = async () => {
                    if (stateRestored) return;
                    stateRestored = true;

                    if (wbName) {
                        await updateWorldbookWith(wbName, wb => {
                            wb.forEach(e => { if (backupStates[e.name] !== undefined) e.enabled = backupStates[e.name]; });
                            return wb;
                        }, { render: 'debounced' });
                        if (typeof window.EjsTemplate !== 'undefined' && window.EjsTemplate.refreshWorldInfo) await window.EjsTemplate.refreshWorldInfo();
                    }

                    if (getLoadedPresetNameSafe() !== originalPresetName) {
                        loadPreset(originalPresetName);
                    }
                };

                if (wbName) {
                    await updateWorldbookWith(wbName, wb => {
                        wb.forEach(e => {
                            backupStates[e.name] = e.enabled;
                            e.enabled = false; // 核心修改：临时禁用所有条目，阻断原生扫描
                        });
                        return wb;
                    }, { render: 'debounced' });
                }

                if (originalPresetName !== CONFIG.analysisPreset) {
                    loadPreset(CONFIG.analysisPreset);
                }

                const injectors = [];

                if (templateContext && templateContext.trim() !== "") {
                    injectors.push({ position: 'in_chat', depth: 4, should_scan: false, role: 'system', content: templateContext.trim() });
                }

                let factualContext = "";
                if (safeHistoryText) factualContext += `【最新剧情切片】：\n${safeHistoryText}\n\n`;
                if (varsStr) factualContext += varsStr;

                if (factualContext.trim() !== "") {
                    injectors.push({ position: 'in_chat', depth: 2, should_scan: false, role: 'assistant', content: factualContext.trim() });
                }

                injectors.push({ position: 'in_chat', depth: 1, should_scan: false, role: 'user', content: userTaskPrompt });

                genOptions.injects = injectors;

                const onGenStartInterceptor = () => {
                    restoreState();
                    if (typeof eventRemoveListener === 'function') {
                        eventRemoveListener(iframe_events.GENERATION_STARTED, onGenStartInterceptor);
                    }
                };

                eventOn(iframe_events.GENERATION_STARTED, onGenStartInterceptor);

                try {
                    result = await generate(genOptions);
                } finally {
                    if (typeof eventRemoveListener === 'function') {
                        eventRemoveListener(iframe_events.GENERATION_STARTED, onGenStartInterceptor);
                    }
                    await restoreState();
                }
            }

        } catch (e) {
            if (typeof toastr !== 'undefined') toastr.error(`模型请求发生底层错误：${e.message}`, 'API错误');
        }

        if (!result || result.trim() === "") return null;

        let finalContent = result.trim().replace(/<(thinking|think|UpdateVariable|Analysis)>[\s\S]*?<\/\1>/gi, "");
        const endTag = `</${tag}>`;
        const startTag = `<${tag}>`;
        const lastEndIndex = finalContent.lastIndexOf(endTag);
        if (lastEndIndex !== -1) {
            const lastStartIndex = finalContent.lastIndexOf(startTag, lastEndIndex);
            if (lastStartIndex !== -1) return finalContent.substring(lastStartIndex + startTag.length, lastEndIndex).trim();
        }

        return null;
    }

    async function upsertStandardEntry(wbName, entryName, content, orderVal, skipBackup = false) {
        const posObj = { type: 'after_character_definition', order: orderVal };
        const stgObj = { type: 'constant', keys: [], keys_secondary: { logic: 'and_any', keys: [] }, scan_depth: 'same_as_global' };
        try {
            await updateWorldbookWith(wbName, wb => {
                const idx = _.findIndex(wb, e => e.name === entryName);

                if (!skipBackup && idx !== -1) {
                    const originalEntry = wb[idx];
                    if (originalEntry.content && originalEntry.content.trim() !== '') {
                        const bakName = `${entryName}_bak`;
                        const bakIdx = _.findIndex(wb, e => e.name === bakName);
                        const snapshot = _.cloneDeep(originalEntry);

                        if (snapshot.content) {
                            snapshot.content = snapshot.content
                                .replace(/<!--\s*PendingUpdate\s*-->\n?/g, "")
                                .replace(/<!--\s*PendingCompress\s*-->\n?/g, "");
                        }

                        delete snapshot.uid;
                        snapshot.comment = `[系统自动备份] 版本快照`;
                        snapshot.enabled = false;
                        snapshot.name = bakName;

                        if (bakIdx !== -1) {
                            snapshot.uid = wb[bakIdx].uid;
                            wb[bakIdx] = snapshot;
                        }
                        else wb.push(snapshot);
                    }
                }

                const shouldEnable = !entryName.endsWith('_bak');
                if (idx !== -1) {
                    wb[idx].content = content;
                    wb[idx].position = posObj;
                    wb[idx].strategy = stgObj;
                    wb[idx].enabled = shouldEnable;
                } else {
                    wb.push({ name: entryName, content: content, position: posObj, strategy: stgObj, enabled: shouldEnable, probability: 100 });
                }
                return wb;
            }, { render: 'debounced' });
            return true;
        } catch (e) {
            return false;
        }
    }

    // ==========================================
    // 六、任务调度与执行
    // ==========================================
    async function evaluateTasks(message_id) {
        const tasks = [];
        const wbName = getActiveWorldbookName();
        const stat = getStatData(message_id);
        if (!wbName || !stat) return tasks;

        // 1. 对象档案检测
        const oName = stat.当前活跃对象;
        if (isValidName(oName)) {
            const eName = getScopedEntryName(`对象_${oName}`);
            const entry = (await getWorldbook(wbName)).find(e => e.name === eName);

            if (!entry || entry.content.trim() === "") {
                tasks.push({ type: 'GEN_OBJ', priority: 1, entryName: eName });
            } else if (entry.content.includes('<!-- PendingUpdate -->')) {
                const lastMark = getWatermark(entry.content, 'LastUpdateObj');
                if (message_id > 0 && (message_id - Math.max(0, lastMark)) >= CONFIG.protectFloor) {
                    tasks.push({ type: 'UPD_OBJ', priority: 3, entryName: eName, content: entry.content });
                }
            }
        }

        // 2. 玩家档案检测
        const pName = stat.玩家数据?.姓名;
        if (isValidName(pName)) {
            const eName = getScopedEntryName(`玩家_${pName}`);
            const entry = (await getWorldbook(wbName)).find(e => e.name === eName);

            if (!entry || entry.content.trim() === "") {
                tasks.push({ type: 'GEN_PLAYER', priority: 2, entryName: eName });
            } else if (entry.content.includes('<!-- PendingUpdate -->')) {
                const lastMark = getWatermark(entry.content, 'LastUpdatePlayer');
                if (message_id > 0 && (message_id - Math.max(0, lastMark)) >= CONFIG.protectFloor) {
                    tasks.push({ type: 'UPD_PLAYER', priority: 4, entryName: eName, content: entry.content });
                }
            }
        }

        // 3. 日志往事压缩检测
        const bakName = getScopedEntryName(CONFIG.bakEntryName);
        const bakEntry = (await getWorldbook(wbName)).find(e => e.name === bakName);
        if (bakEntry && bakEntry.content.includes('<!-- PendingCompress -->')) {
            // 提取真实的 MarkLine 和时间，传给任务参数
            const { markLine, timeStr } = extractLastLogWatermark(bakEntry.content);
            tasks.push({
                type: 'COMP_LOG',
                priority: 5,
                entryName: bakName,
                content: bakEntry.content,
                extractedMarkLine: markLine,
                extractedTime: timeStr
            });
        }

        return tasks.sort((a, b) => a.priority - b.priority);
    }

    async function executeSingleTask(task, message_id, isManual = false) {
        const wbName = getActiveWorldbookName();
        if (!wbName) return false;

        isRunningAPI = true;
        let success = false;
        const logEntryName = getScopedEntryName(CONFIG.logEntryName);
        const bakEntryName = getScopedEntryName(CONFIG.bakEntryName);
        const statData = getStatData(message_id);

        let objPersonaEntries = [];
        if (statData?.当前活跃对象 && statData.交往对象列表?.[statData.当前活跃对象]?.对象类型) {
            const types = statData.交往对象列表[statData.当前活跃对象].对象类型;
            if (Array.isArray(types)) {
                objPersonaEntries = types.map(t => `${t}_人设`);
            }
        }

        const taskAlias = { 'GEN_PLAYER': '生成玩家档案', 'UPD_PLAYER': '更新玩家档案', 'GEN_OBJ': '生成对象档案', 'UPD_OBJ': '更新对象档案', 'COMP_LOG': '压缩相亲往事' };
        if (!isManual && typeof toastr !== 'undefined') toastr.info(`正在执行：${taskAlias[task.type]}，请勿操作...`, '后台任务启动');

        try {
            const statStr = statData ? `【当前状态参照】：\n${JSON.stringify(statData, null, 2)}` : "";

            const playerName = statData?.玩家数据?.姓名 || "玩家";
            const objName = statData?.当前活跃对象 || "对象";
            const currentTime = statData?.世界状态?.时间 || "未知时间";

            if (task.type === 'GEN_OBJ') {
                const prompt = CONFIG.prompts.genObject.replace(/{对象}/g, objName);
                const wl = ['【档案模板】', ...objPersonaEntries, bakEntryName, logEntryName];
                const text = await pureGenerate(prompt, "", statStr, "char_data", true, 0, wl, wbName, CONFIG.anchorOffset);
                if (text) {
                    const finalContent = text + "\n" + getTimeMark(currentTime) + getUpdateMark('LastUpdateObj', message_id);
                    success = await upsertStandardEntry(wbName, task.entryName, finalContent, 10, false);
                }
            }
            else if (task.type === 'GEN_PLAYER') {
                const prompt = CONFIG.prompts.genPlayer.replace(/{玩家}/g, playerName);
                const wl = ['【档案模板】', bakEntryName, logEntryName];
                const text = await pureGenerate(prompt, "", statStr, "user_data", true, 0, wl, wbName, CONFIG.anchorOffset);
                if (text) {
                    const finalContent = text + "\n" + getTimeMark(currentTime) + getUpdateMark('LastUpdatePlayer', message_id);
                    success = await upsertStandardEntry(wbName, task.entryName, finalContent, 9, false);
                }
            }
            else if (task.type === 'UPD_OBJ') {
                const prompt = CONFIG.prompts.updObject.replace(/{对象}/g, objName);
                const wl = ['【档案模板】', ...objPersonaEntries, bakEntryName, logEntryName];
                const text = await pureGenerate(prompt, task.content, statStr, "char_data", true, 0, wl, wbName, CONFIG.anchorOffset);
                if (text) {
                    const finalContent = text + "\n" + getTimeMark(currentTime) + getUpdateMark('LastUpdateObj', message_id);
                    success = await upsertStandardEntry(wbName, task.entryName, finalContent, 10, false);
                }
            }
            else if (task.type === 'UPD_PLAYER') {
                const prompt = CONFIG.prompts.updPlayer.replace(/{玩家}/g, playerName);
                const wl = ['【档案模板】', bakEntryName, logEntryName];
                const text = await pureGenerate(prompt, task.content, statStr, "user_data", true, 0, wl, wbName, CONFIG.anchorOffset);
                if (text) {
                    const finalContent = text + "\n" + getTimeMark(currentTime) + getUpdateMark('LastUpdatePlayer', message_id);
                    success = await upsertStandardEntry(wbName, task.entryName, finalContent, 9, false);
                }
            }
            else if (task.type === 'COMP_LOG') {
                const wl = ['【日志模板】'];
                const text = await pureGenerate(CONFIG.prompts.compLog, task.content, "", "log_data", false, 0, wl, wbName, 0);
                if (text) {
                    const finalMarkLine = task.extractedMarkLine !== undefined ? task.extractedMarkLine : Math.max(0, message_id - CONFIG.anchorOffset);
                    const finalTime = task.extractedTime || currentTime;
                    const finalContent = text + "\n" + `日志更新时间: [${finalTime}]\n` + `<!-- LastSummary: ${finalMarkLine} -->\n`;
                    success = await upsertStandardEntry(wbName, task.entryName, ensureTitle(finalContent, BAK_TITLE), 99, false);
                }
            }

            if (success) {
                if (!isManual && typeof toastr !== 'undefined') toastr.success(`后台任务【${taskAlias[task.type]}】执行完毕。`, '任务成功');
            } else {
                if (typeof toastr !== 'undefined') toastr.error(`任务【${taskAlias[task.type]}】未产生有效变更。`, '任务反馈');
            }

        } catch (e) {
            console.error(e);
            if (typeof toastr !== 'undefined') toastr.error(`任务执行中发生未知错误：${e.message}`, '系统异常');
        } finally {
            isRunningAPI = false;
            return success;
        }
    }

    // ==========================================
    // 七、全局消息拦截
    // ==========================================
    async function safeMessageFlow(eventArg, isReRoll = false) {
        try {
            await new Promise(resolve => setTimeout(resolve, 0));
            const message_id = typeof eventArg === 'number' ? eventArg : getLastMessageIdSafe();
            if (message_id <= 0 || isRunningAPI || !getActiveWorldbookName()) return;

            const chatId = getCurrentChatId();
            const floorKey = `${chatId}_${message_id}`;

            await new Promise(res => setTimeout(res, CONFIG.syncDelay));
            if (isRunningAPI) return;

            await enforceWorldbookIsolation('debounced');

            if (isReRoll) {
                return; // 后台生成拦截
            }

            try { await processProfileRecover(message_id); } catch(e){}

            // --- 档案过期警告或静默触发更新 ---
            try { await checkProfileExpiration(message_id); } catch(e){}

            try { await processLogAndRecover(message_id); } catch(e){}
            try { await appendLogSnapshot(message_id); } catch(e){}

            if (floorKey === lastExecutedFloorId) {
                return;
            }

            const pending = await evaluateTasks(message_id);
            if (pending.length > 0) {
                lastExecutedFloorId = floorKey;
                await executeSingleTask(pending[0], message_id, false);
            }
        } catch (e) {
            console.error('[终端流控异常]', e);
            if (typeof toastr !== 'undefined') toastr.error(`系统流程异常: ${e.message}`, '核心错误');
        }
    }

