    async function forceCleanRedundantEntries() {
        if (isRunningAPI) { toastr.warning('任务执行中，请稍后...'); return; }
        const w = getActiveWorldbookName(); const c = getCurrentChatId(); if (!w || !c) return;
        let n = 0;
        await updateWorldbookWith(w, wb => { return wb.filter(e => { if ((e.name.startsWith("对象_") || e.name.startsWith("玩家_") || e.name.startsWith(CONFIG.logEntryName) || e.name.startsWith(CONFIG.bakEntryName)) && e.name.includes("_XQ_") && !e.name.includes(`_XQ_${c}`)) { n++; return false; } return true; }); }, { render: 'immediate' });
