    }

    async function forceDeleteInactiveProfiles() {
        if (isRunningAPI) { toastr.warning('任务执行中，请稍后...'); return; }
        const w = getActiveWorldbookName(); const c = getCurrentChatId(); if (!w || !c) return;
        const statData = getStatData(getLastMessageIdSafe());

        const activeKeys = (statData && statData.交往对象列表) ? Object.keys(statData.交往对象列表) : [];
        let n = 0;

        await updateWorldbookWith(w, wb => {
            return wb.filter(e => {
                if (e.name.startsWith("对象_") && e.name.includes(`_XQ_${c}`)) {
                    const match = e.name.match(/^对象_(.+?)_XQ_/);
                    const objName = match ? match[1] : null;

                    if (objName && !activeKeys.includes(objName)) {
                        n++;
                        return false;
                    }
                }
                return true;
            });
        }, { render: 'immediate' });

        toastr.success(`清理了 ${n} 个历史对象档案。`, '清理完成');
    }

