    async function handleMessageDeleted(arg) {
        try {
            const currentMsgId = getLastMessageIdSafe();
            if (currentMsgId < 0 || !getActiveWorldbookName()) return;

            lastExecutedFloorId = null;

            try { await processLogAndRecover(currentMsgId); } catch(e) {}
            try { await processProfileRecover(currentMsgId); } catch(e) {}
            await enforceWorldbookIsolation('debounced');

            console.log(`[删楼修正] 已重置状态锁并清理冗余数据 (锚点:${currentMsgId})。`);
        } catch (e) { console.error('[删楼处理异常]', e); }
    }

    // ==========================================
    // 九、监听注册与通信中枢
    // ==========================================
    const idleDelay = () => new Promise(resolve => {
        if ('requestIdleCallback' in window) {
            requestIdleCallback(() => setTimeout(resolve, CONFIG.syncDelay), { timeout: 2000 });
        } else {
            setTimeout(resolve, CONFIG.syncDelay);
        }
    });

    const triggerMessageReceived = async (arg) => {
        const message_id = typeof arg === 'number' ? arg : getLastMessageIdSafe();
        await idleDelay();

        const chatId = getCurrentChatId();
        const floorKey = `${chatId}_${message_id}`;

        const isReRoll = (floorKey === lastExecutedFloorId);

        await safeMessageFlow(message_id, isReRoll);
    };

    const registerCoreEvents = () => {
        if (window.tavern_events) {
            eventMakeLast(tavern_events.MESSAGE_SENT, async (arg) => {
                await triggerMessageReceived(arg);
            });

            eventMakeLast(tavern_events.MESSAGE_RECEIVED, async (arg) => {
                await triggerMessageReceived(arg);
            });

            eventMakeLast(tavern_events.MESSAGE_SWIPED, async (arg) => {
                const msgId = typeof arg === 'number' ? arg : getLastMessageIdSafe();
                try { await processLogAndRecover(msgId); } catch(e){}

                // 滑屏时精准传入 true，触发精确等于判定
                try { await processProfileRecover(msgId, true); } catch(e){}

                // console.log('[数据修正] 检测到剧情改写，已清洗失真数据。');
                await idleDelay();
                await safeMessageFlow(msgId, true);
            });

            eventOn(tavern_events.MESSAGE_DELETED, async (arg) => { await handleMessageDeleted(arg); });

            eventOn(tavern_events.CHAT_CHANGED, async () => {
                lastExecutedFloorId = null;

                await idleDelay();
                await enforceWorldbookIsolation('debounced');
                await executeSilentAutoClean();
            });

            eventOnce(tavern_events.APP_READY, async () => {
                await idleDelay();
                await enforceWorldbookIsolation('debounced');
                await executeSilentAutoClean();
            });
        }
    };

    const setupCommunication = () => {
        if (typeof eventOn === 'function') {
