    // === 3. 队列管理与触发模块 ===
    async function handleSwipeAction(direction, vipLevelFromFrontend, msgId) {
        if (matchQueue.length > 0) {
            const target = matchQueue.shift();

            if (direction === 'right') {
                let vipLevel = vipLevelFromFrontend || 0;
                let isHackMode = false;
                try {
                    const storedHack = localStorage.getItem('BlindDate_Hack_Mode');
                    if (storedHack !== null) isHackMode = (storedHack === 'true');
                } catch (e) {}

                let prob = 0.10;
                if (isHackMode) {
                    prob = 1.0;
                } else {
                    if (vipLevel === 1) prob = 0.25;
                    else if (vipLevel === 2) prob = 0.50;
                    else if (vipLevel >= 3) prob = 0.75;
                }

                if (Math.random() <= prob) {
                    try {
                        let likedQueue = [];
                        const likedCached = localStorage.getItem('SillyTavern_BlindDate_Liked');
                        if (likedCached) {
                            likedQueue = JSON.parse(likedCached);
                            if (!Array.isArray(likedQueue)) likedQueue = [];
                        }

                        likedQueue.push(target);
                        if (likedQueue.length > 10) {
                            likedQueue.shift();
                        }

                        localStorage.setItem('SillyTavern_BlindDate_Liked', JSON.stringify(likedQueue));
                        broadcastMessage({ type: 'XQ_LikedUpdated' });
                    } catch (e) {
                        console.error("[心遇后端] 保存喜欢队列失败:", e);
                    }
                }
            }

            saveQueueToCache();
        }

        await checkAndGenerate(msgId);
    }

    async function checkAndGenerate(msgId) {
        if (matchQueue.length <= MATCH_CONFIG.queueThreshold) {
            await triggerGenerateMatches(msgId);
        }
    }

    function saveQueueToCache() {
        try {
            localStorage.setItem('SillyTavern_BlindDate_Queue', JSON.stringify(matchQueue));
        } catch (e) {
            console.error("[心遇后端] 保存缓存队列失败:", e);
        }
    }

    // === 4. 文本拼装与生成引擎模块 ===
    async function getWorldbookEntry(entryName, requireScoped = false) {
        try {
            const wbNames = topWindow.TavernHelper?.getCharWorldbookNames('current') || [];
            const wbName = wbNames ? (wbNames.primary || (wbNames.additional?.length > 0 ? wbNames.additional[0] : null)) : null;
            if (!wbName) return null;

            const wb = await topWindow.TavernHelper.getWorldbook(wbName);

            if (requireScoped) {
                const scopedName = getScopedEntryName(entryName);
                let entry = wb.find(e => e.name === scopedName);
                if (entry && entry.content) return entry.content.trim();
            }

            const entry = wb.find(e => e.name === entryName);
            return entry && entry.content ? entry.content.trim() : null;
        } catch (e) {
            console.error(`[心遇后端] 获取世界书条目 "${entryName}" 失败:`, e);
            return null;
        }
    }

    async function handleSilentChatGeneration(targetName, playerName, msgId) {
        if (isChatGenerating) {
            return;
        }

        if (typeof topWindow.TavernHelper === 'undefined') {
            console.error("[心遇后端] 缺少 TavernHelper，无法请求。");
            return;
        }

        isChatGenerating = true;
        loadConfig();

        let disabledMvuEntriesMap = {};

        const restoreMvuEntries = async () => {
            if (Object.keys(disabledMvuEntriesMap).length === 0) return;
            for (let wbName in disabledMvuEntriesMap) {
                try {
                    await topWindow.TavernHelper.updateWorldbookWith(wbName, wb => {
                        wb.forEach(entry => {
                            if (disabledMvuEntriesMap[wbName].includes(entry.uid)) {
                                entry.enabled = true;
                            }
                        });
                        return wb;
                    }, { render: 'debounced' });
                } catch(e) {
                    console.error("[心遇后端] 恢复世界书条目失败:", e);
                }
            }
            disabledMvuEntriesMap = {};
        };

        try {
            const breakLimit = await getWorldbookEntry("【内置破限】", false) || "";
            const chatTemplate = await getWorldbookEntry("【聊天模板】", false) || "";

            const wbNames = topWindow.TavernHelper.getCharWorldbookNames('current');
            const allWbNames = [wbNames.primary, ...(wbNames.additional || [])].filter(Boolean);

            for (let wbName of allWbNames) {
                await topWindow.TavernHelper.updateWorldbookWith(wbName, wb => {
                    wb.forEach(entry => {
                        if (entry.name && entry.name.toLowerCase().includes('mvu') && entry.enabled) {
                            entry.enabled = false;
                            if (!disabledMvuEntriesMap[wbName]) disabledMvuEntriesMap[wbName] = [];
                            disabledMvuEntriesMap[wbName].push(entry.uid);
                        }
                    });
                    return wb;
                }, { render: 'debounced' });
            }

            if (topWindow.SillyTavern && topWindow.SillyTavern.eventSource) {
                topWindow.SillyTavern.eventSource.once('js_generation_started', restoreMvuEntries);
            }

            let recentMsgs = [];
            if (typeof topWindow.TavernHelper !== 'undefined' && topWindow.TavernHelper.getChatMessages) {
                try {
                    // 优先使用前端传来的 msgId，如果没有则兜底使用 getLastMessageId()
                    const lastId = (msgId !== undefined && msgId !== null) ? msgId : topWindow.TavernHelper.getLastMessageId();
                    const startId = Math.max(0, lastId - (MATCH_CONFIG.logOffset - 1));
                    const rangeStr = startId + '-' + lastId;
                    recentMsgs = topWindow.TavernHelper.getChatMessages(rangeStr);
                } catch (e) {
                    console.error("[心遇后端] 调用酒馆API获取聊天记录失败:", e);
                }
            }

            let wechatMsgs = [];
            try {
                const lastId = (msgId !== undefined && msgId !== null) ? msgId : topWindow.TavernHelper.getLastMessageId();
                const displayLayers = getDisplayLayers();
                const wechatStartId = Math.max(0, lastId - (displayLayers - 1));
                const wechatRangeStr = wechatStartId + '-' + lastId;
                wechatMsgs = topWindow.TavernHelper.getChatMessages(wechatRangeStr);
            } catch (e) {
                console.error("[心遇后端] 获取微信聊天记录失败:", e);
                wechatMsgs = recentMsgs;
            }

            // 提取专属聊天记录，用于补充上下文
            const chatHistoryText = wechatMsgs.map((m, index) => {
                let rawText = m.message;
                if (typeof topWindow.TavernHelper.formatAsTavernRegexedString === 'function') {
                    let source = m.role === 'user' ? 'user_input' : 'ai_output';
                    rawText = topWindow.TavernHelper.formatAsTavernRegexedString(
                        rawText,
                        source,
                        'prompt',
                        { depth: wechatMsgs.length - 1 - index }
                    );
                }
                return rawText;
            }).join("\n\n");

            let exclusiveRecord = "【微信聊天记录】\n";
            const exclusiveRegex = /<微信\s+(user|from)="([^"]+)">([\s\S]*?)<\/微信>/gi;
            let exMatch;
            while ((exMatch = exclusiveRegex.exec(chatHistoryText)) !== null) {
                const type = exMatch[1];
                const bindName = exMatch[2].trim();
                const content = exMatch[3].trim();

                if (bindName === targetName) {
                    if (type === 'user') {
                        exclusiveRecord += `${playerName}：${content}\n`;
                    } else if (type === 'from') {
                        exclusiveRecord += `${targetName}：${content}\n`;
                    }
                }
            }

            // 手动拼装并清洗聊天历史
            let customChatHistoryPrompts = [];
            for (let i = 0; i < recentMsgs.length; i++) {
                let msgObj = recentMsgs[i];
                let rawText = msgObj.message;

                // A. 宏替换
                if (typeof topWindow.TavernHelper.substitudeMacros === 'function') {
                    rawText = topWindow.TavernHelper.substitudeMacros(rawText);
                }

                // B. 正则扩展处理
                if (typeof topWindow.TavernHelper.formatAsTavernRegexedString === 'function') {
                    let source = msgObj.role === 'user' ? 'user_input' : 'ai_output';
                    let destination = 'prompt';
                    rawText = topWindow.TavernHelper.formatAsTavernRegexedString(
                        rawText,
                        source,
                        destination,
                        { depth: recentMsgs.length - 1 - i }
                    );
                }

                // C. EJS 语法渲染
                if (topWindow.EjsTemplate && typeof topWindow.EjsTemplate.evaltemplate === 'function') {
                    try {
                        const env = await topWindow.EjsTemplate.prepareContext({}, msgObj.message_id);
                        rawText = await topWindow.EjsTemplate.evaltemplate(rawText, env);
                    } catch (ejsError) {
                        console.warn("[心遇后端] EJS 渲染失败，跳过此步骤:", ejsError);
                    }
                }

                let role = msgObj.role;
                let content = rawText;

                customChatHistoryPrompts.push({
                    role: role,
                    content: content
                });
            }

            let customPromptsArray = [];
            if (breakLimit) customPromptsArray.push({ role: 'system', content: breakLimit });
            if (chatTemplate) customPromptsArray.push({ role: 'system', content: chatTemplate });

            customPromptsArray.push('world_info_before');
            customPromptsArray.push('world_info_after');
            customPromptsArray.push('chat_history'); // 这里保留占位符，由 overrides 覆盖

            customPromptsArray.push({ role: 'system', content: exclusiveRecord });
            customPromptsArray.push({
                role: 'system',
                content: `请在<thinking>中进行思考，然后以${targetName}的身份回复${playerName}。回复内容必须使用<微信 from="${targetName}">包裹，格式为：\n<微信 from="${targetName}">\n回复内容\n</微信>\n`
            });
            customPromptsArray.push('user_input');

            let genConfig = {
                user_input: `执行指令，生成${targetName}的回复内容。`,
                should_stream: false,
                should_silence: false,
                overrides: {
                    chat_history: {
                        prompts: customChatHistoryPrompts
                    }
                },
                ordered_prompts: customPromptsArray
            };

            if (MATCH_CONFIG.externalApi && MATCH_CONFIG.externalApi.enabled) {
                genConfig.custom_api = {
                    apiurl: MATCH_CONFIG.externalApi.url,
                    key: MATCH_CONFIG.externalApi.apiKey,
                    model: MATCH_CONFIG.externalApi.model,
                    max_tokens: MATCH_CONFIG.externalApi.max_tokens,
                    temperature: MATCH_CONFIG.externalApi.temperature
                };
            }

            let response = await topWindow.TavernHelper.generateRaw(genConfig);

            let responseText = "";
            if (typeof response === 'string') responseText = response;
            else if (response && typeof response === 'object' && response.content) responseText = response.content;

            if (responseText) {
                const regex = /<微信\s+from="([^"]+)">([\s\S]*?)<\/微信>/gi;
                let match;
                let finalChats = [];
                while ((match = regex.exec(responseText)) !== null) {
                    finalChats.push(`<微信 from="${match[1].trim()}">\n${match[2].trim()}\n</微信>`);
                }

                if (finalChats.length > 0) {
                    const combinedResult = finalChats.join('\n');
                    broadcastMessage({
                        type: 'XQ_ChatReplySuccess',
                        targetName: targetName,
                        replyContent: combinedResult
                    });
                } else {
                    console.error("[心遇后端] 未在聊天回复中找到 <微信> 包裹标签！");
                }
