    // === 5. 数据解析模块 ===
    function processAIResponse(responseText, msgId) {
        const regex = new RegExp(`<match_data>([\\s\\S]*?)<\\/match_data>`, 'i');
        const match = responseText.match(regex);

        if (match && match[1]) {
            try {
                let jsonStr = match[1].trim();
                jsonStr = jsonStr.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();

                const responseData = JSON.parse(jsonStr);
                const evaluationData = responseData["本轮评估"] || {};
                const newDataArray = responseData["对象列表"];

                // 捕获并更新用户综合评分缓存
                if (evaluationData["用户综合评分"] !== undefined) {
                    try {
                        localStorage.setItem('BlindDate_Player_Score_Cache', evaluationData["用户综合评分"]);
                    } catch (e) {
                        console.warn("[心遇后端] 写入综合评分缓存失败", e);
                    }
                }

                if (Array.isArray(newDataArray)) {
                    let existNames = new Set();
                    try {
                        const likedCached = localStorage.getItem('SillyTavern_BlindDate_Liked');
                        if (likedCached) {
                            const likedQueue = JSON.parse(likedCached);
                            if (Array.isArray(likedQueue)) {
                                likedQueue.forEach(item => {
                                    if (item && item["姓名"]) {
                                        existNames.add(item["姓名"]);
                                    } else if (item && item["登记信息"] && item["登记信息"]["姓名"]) {
                                        existNames.add(item["登记信息"]["姓名"]);
                                    }
                                });
                            }
                        }
                    } catch(e) {}

                    try {
                        if (typeof topWindow.TavernHelper !== 'undefined' && topWindow.TavernHelper.getVariables) {
                            let targetId = (msgId !== undefined && msgId !== null) ? msgId : 'latest';
                            const vars = topWindow.TavernHelper.getVariables({type: 'message', message_id: targetId});
                            if (vars && vars.stat_data && vars.stat_data['交往对象列表']) {
                                Object.keys(vars.stat_data['交往对象列表']).forEach(name => existNames.add(name));
                            }
                        }
                    } catch(e) {}

                    // 遍历当前推荐队列 matchQueue，把里面的名字也加进黑名单
                    for (let i = 0; i < matchQueue.length; i++) {
                        if (matchQueue[i] && matchQueue[i]["姓名"]) {
                            existNames.add(matchQueue[i]["姓名"]);
                        }
                    }

                    let playerScore = 0;
                    if (evaluationData["用户综合评分"] !== undefined) {
                        playerScore = Number(evaluationData["用户综合评分"]) || 0;
                    } else {
                        try {
                            if (typeof topWindow.TavernHelper !== 'undefined' && topWindow.TavernHelper.getVariables) {
                                let targetId = (msgId !== undefined && msgId !== null) ? msgId : 'latest';
                                const vars = topWindow.TavernHelper.getVariables({type: 'message', message_id: targetId});
                                if (vars && vars.stat_data && vars.stat_data['玩家数据'] && vars.stat_data['玩家数据']['综合评分'] !== undefined) {
                                    playerScore = Number(vars.stat_data['玩家数据']['综合评分']) || 0;
                                }
                            }
                        } catch(e) {}
                    }

                    let activeLikeProb = Math.floor(playerScore / 5) * 0.01;
                    activeLikeProb = Math.min(activeLikeProb, 0.30);

                    let newLikedObjects = [];
                    let finalQueueObjects = [];

                    newDataArray.forEach(obj => {
                        if (obj && obj["姓名"]) {
                            const name = obj["姓名"];
                            if (existNames.has(name)) {
                                return;
                            }
                            // 决定放行这个对象，立刻把它的名字加入黑名单
                            existNames.add(name);
                        }

                        if (Math.random() <= activeLikeProb) {
                            newLikedObjects.push(obj);
                        } else {
                            finalQueueObjects.push(obj);
                        }
                    });

                    if (newLikedObjects.length > 0) {
                        try {
                            let likedQueue = [];
                            const likedCached = localStorage.getItem('SillyTavern_BlindDate_Liked');
                            if (likedCached) {
                                likedQueue = JSON.parse(likedCached);
                                if (!Array.isArray(likedQueue)) likedQueue = [];
                            }

                            newLikedObjects.forEach(obj => {
                                likedQueue.push(obj);
                            });

                            while (likedQueue.length > 10) {
                                likedQueue.shift();
                            }

                            localStorage.setItem('SillyTavern_BlindDate_Liked', JSON.stringify(likedQueue));
                            broadcastMessage({ type: 'XQ_LikedUpdated' });
                        } catch (e) {
                            console.error("[心遇后端] 保存主动喜欢队列失败:", e);
                        }
                    }

                    matchQueue.push(...finalQueueObjects);
                    saveQueueToCache();
                    console.log(`[心遇后端] 成功解析并入库 ${finalQueueObjects.length} 个新对象到推荐队列。当前队列余量: ${matchQueue.length} 个`);

                    broadcastMessage({
                        type: 'XQ_QueueUpdated',
                        count: matchQueue.length,
                        evaluation: evaluationData
                    });
                } else {
                    console.error("[心遇后端] 解析的 JSON 中未找到有效的数组。");
                }
            } catch (parseError) {
                console.error("[心遇后端] JSON 解析失败:", parseError, "\nAI原始截取文本:", match[1]);
            }
        } else {
            console.error(`[心遇后端] 未在回复中找到 <match_data> 包裹标签！返回的原始内容是:\n`, responseText);
        }
    }

    // === 6. 挂载前端按钮模块 ===
    function initFrontendButton() {
        if (typeof TavernHelper === 'undefined') {
            console.warn("[心遇后端] TavernHelper 未加载，无法初始化挂载按钮。");
            return;
        }

        const BUTTON_NAME = '💬';
        const VAR_NAME = '呼出前端时不新建楼层';

        if (typeof getButtonEvent === 'function' && typeof eventOn === 'function') {
            eventOn(getButtonEvent(BUTTON_NAME), async () => {
                try {
                    let shouldAppend = false;

                    // 尝试读取脚本变量，如果读取不到或报错，默认 false 兜底
                    if (typeof getVariables === 'function') {
                        try {
                            const scriptVars = getVariables({ type: 'script' });
                            if (scriptVars && scriptVars[VAR_NAME] === true) {
                                shouldAppend = true;
                            }
                        } catch (varError) {
                            console.warn("[心遇后端] 读取脚本变量失败，使用默认值 false:", varError);
                        }
                    }

                    if (shouldAppend) {
                        // 追加到最新楼层
                        const lastMsgs = TavernHelper.getChatMessages(-1);
                        if (lastMsgs && lastMsgs.length > 0) {
                            const lastMsg = lastMsgs[0];
                            const newText = lastMsg.message + '\n💬';
                            await TavernHelper.setChatMessages([{
                                message_id: lastMsg.message_id,
                                message: newText
                            }]);
                        } else {
                            // 如果当前没有任何楼层，退回到新建楼层
                            await TavernHelper.createChatMessages([{ role: 'user', message: '💬' }]);
                        }
                    } else {
                        // 新建用户楼层
                        await TavernHelper.createChatMessages([{ role: 'user', message: '💬' }]);
                    }
                } catch (error) {
                    console.error("[心遇后端] 挂载前端按钮执行失败:", error);
                }
            });
        }
    }

    // === 启动系统 ===
    initSystem();

})();

