    const TARGET_VOLUME = 50;
    let fadeIntervals = { ambient: null, bgm: null };

    // 音频渐响播放
    function playAudioWithFade(type, url, title, mode) {
        if (!url) return;

        if (fadeIntervals[type]) clearInterval(fadeIntervals[type]);

        if (!CONFIG.enableFade) {
            TavernHelper.setAudioSettings(type, { volume: TARGET_VOLUME, mode: mode });
            TavernHelper.playAudio(type, { title: title, url: url });
            console.log(`[音乐控制] 触发播放 >> 类型:${type} | 标题:${title} | 模式:${mode}`);
            return;
        }

        // 初始化音量为0，设置播放模式
        TavernHelper.setAudioSettings(type, { volume: 0, mode: mode });
        TavernHelper.playAudio(type, { title: title, url: url });

        console.log(`[音乐控制] 渐响播放 >> 类型:${type} | 标题:${title} | 模式:${mode}`);

        const FADE_TIME = 1000; // 渐响总时长
        const FADE_STEP = 100; // 更新频率
        let elapsed = 0;

        fadeIntervals[type] = setInterval(() => {
            elapsed += FADE_STEP;
            const progress = elapsed / FADE_TIME;

            if (progress >= 1) {
                TavernHelper.setAudioSettings(type, { volume: TARGET_VOLUME });
                clearInterval(fadeIntervals[type]);
            } else {
                // 非线性曲线：进度比例的2次方，实现前面平缓后面陡峭
                const currentVol = Math.round(TARGET_VOLUME * Math.pow(progress, 2));
                TavernHelper.setAudioSettings(type, { volume: currentVol });
            }
        }, FADE_STEP);
    }

    const bgmRegex = /<bgm:\s*(.*?)(?:\s*-\s*(.*?))?\s*>/g;

    async function processBgmTags(messageId) {
        if (!CONFIG.enableBgmReplace) return;

        const targetId = messageId !== undefined ? messageId : getLastMessageId();
        // 直接获取包含 message 字段的当前显示文本
        const messages = getChatMessages(targetId);
        if (!messages || messages.length === 0) return;

        const currentMessage = messages[0];
        let messageText = currentMessage.message;
        if (!messageText) return; // 安全检查

        let match;
        let hasChanges = false;
        let newText = messageText;

        while ((match = bgmRegex.exec(messageText)) !== null) {
            const fullMatch = match[0];
            const songName = match[1];
            const artistName = match[2] || '';

            const directUrl = await fetchAndVerifyMusicUrl_Racing(songName, artistName);
            const replacement = directUrl ? directUrl : '';

            newText = newText.replace(fullMatch, replacement);
            hasChanges = true;
        }

        if (hasChanges) {
            await setChatMessages([{
                message_id: targetId,
                message: newText
            }]);
        }
    }

    async function fetchAndVerifyMusicUrl_Racing(songName, artistName) {
        const artistStr = artistName ? `${artistName}的` : '';
        try {
            const result = await Promise.any([
                fetchFromNetease(songName, artistName),
                fetchFromQQ(songName, artistName)
            ]);
            console.log(`[音乐控制] 通过${result.platform}接口找到${artistStr}《${songName}》`);
            return result.url;
        } catch (error) {
            console.log(`[音乐控制] ${artistStr}《${songName}》可能是付费歌曲或版权问题，无法获取`);
            return null;
        }
    }

    async function fetchFromNetease(songName, artistName) {
        const query = artistName ? `${songName}-${artistName}` : songName;
        const searchUrl = `https://api.vkeys.cn/v2/music/netease?word=${encodeURIComponent(query)}`;

        const searchResponse = await fetch(searchUrl);
        const searchData = await searchResponse.json();

        if (!searchData?.data || searchData.data.length === 0) {
            throw new Error('网易云无数据');
        }

        const maxAttempts = Math.min(searchData.data.length, 10);

        for (let i = 0; i < maxAttempts; i++) {
            const songId = searchData.data[i].id;
            if (!songId) continue;

            const detailUrl = `https://api.vkeys.cn/v2/music/netease?id=${songId}`;
            const detailResponse = await fetch(detailUrl);
            const detailData = await detailResponse.json();

            const musicUrl = detailData?.data?.url;
            if (!musicUrl) continue;

            const isValid = await verifyAudioUrl(musicUrl);
            if (isValid) return { url: musicUrl, platform: '网易云' };
        }
        throw new Error('网易云全军覆没');
    }

    async function fetchFromQQ(songName, artistName) {
        const query = artistName ? `${songName}-${artistName}` : songName;
        const searchUrl = `https://api.vkeys.cn/v2/music/tencent?word=${encodeURIComponent(query)}`;

        const searchResponse = await fetch(searchUrl);
        const searchData = await searchResponse.json();

        if (!searchData?.data || searchData.data.length === 0) {
            throw new Error('QQ音乐无数据');
        }

        const list = searchData.data.concat(...searchData.data.map(i => i.grp || []));
        const maxAttempts = Math.min(list.length, 10);

        for (let i = 0; i < maxAttempts; i++) {
            const songId = list[i].id;
            if (!songId) continue;

            const detailUrl = `https://api.vkeys.cn/v2/music/tencent?id=${songId}`;
            const detailResponse = await fetch(detailUrl);
            const detailData = await detailResponse.json();

            const musicUrl = detailData?.data?.url;
            if (!musicUrl) continue;

            const isValid = await verifyAudioUrl(musicUrl);
            if (isValid) return { url: musicUrl, platform: 'QQ音乐' };
        }
        throw new Error('QQ音乐全军覆没');
    }

    function verifyAudioUrl(url) {
        return new Promise((resolve) => {
            const audio = new Audio();
            audio.src = url;

            const timeoutId = setTimeout(() => {
                audio.src = '';
                resolve(false);
            }, CONFIG.verifyTimeout);

            audio.oncanplaythrough = () => {
                clearTimeout(timeoutId);
                resolve(true);
            };

            audio.onerror = () => {
                clearTimeout(timeoutId);
                resolve(false);
            };
        });
    }

    // 核心状态检测
    function checkMusicStatus(forceReplay = false) {
        try {
            const curStat = getStatData('latest');
            let prevStat = getStatData(-2);

            // 如果获取不到上一层，就用当前层兜底
            if (!prevStat) prevStat = curStat;
            if (!curStat) return;

            // 环境音逻辑
            if (CONFIG.enableAmbient && !state.isAmbientPaused) {
                const weather = String(_.get(curStat, '世界状态.天气', ''));
                const location = String(_.get(curStat, '世界状态.地点', ''));

                let targetAmbient = null;
                let targetTitle = "";

                // 按照优先级：1.雷鸣 2.雨声 3.风声 4.闹市 5.马路 6.树林
                if (weather.includes('雷')) { targetAmbient = MUSIC_LINKS.ambient_thunder; targetTitle = "环境_雷鸣"; }
                else if (weather.includes('雨')) { targetAmbient = MUSIC_LINKS.ambient_rain; targetTitle = "环境_雨声"; }
                else if (weather.includes('风')) { targetAmbient = MUSIC_LINKS.ambient_wind; targetTitle = "环境_风声"; }
                else if (["市场", "商场", "街市"].some(loc => location.includes(loc))) { targetAmbient = MUSIC_LINKS.ambient_market; targetTitle = "环境_闹市"; }
                else if (["路上", "车"].some(loc => location.includes(loc))) { targetAmbient = MUSIC_LINKS.ambient_road; targetTitle = "环境_马路"; }
                else if (["林", "山", "野"].some(loc => location.includes(loc))) { targetAmbient = MUSIC_LINKS.ambient_forest; targetTitle = "环境_树林"; }

                if (targetAmbient) {
                    let currentMode = 'repeat_one';
                    if (CONFIG.disableLoop) {
                        currentMode = 'play_one_and_stop';
                    }
                    if (forceReplay || targetAmbient !== state.currentAmbientUrl) {
                        state.currentAmbientUrl = targetAmbient;
                        state.currentAmbientMode = currentMode;
                        playAudioWithFade('ambient', targetAmbient, targetTitle, currentMode);
                    } else if (currentMode !== state.currentAmbientMode) {
                        state.currentAmbientMode = currentMode;
                        if (typeof TavernHelper !== 'undefined' && TavernHelper.setAudioSettings) {
                            TavernHelper.setAudioSettings('ambient', { mode: currentMode });
                        }
                    }
                } else if (!targetAmbient && state.currentAmbientUrl) {
                    // 安全清理并暂停
                    if (fadeIntervals['ambient']) clearInterval(fadeIntervals['ambient']);
                    TavernHelper.pauseAudio('ambient');
                    state.currentAmbientUrl = null;
                }
            } else {
                if (state.currentAmbientUrl) {
                    if (fadeIntervals['ambient']) clearInterval(fadeIntervals['ambient']);
                    TavernHelper.pauseAudio('ambient');
                    state.currentAmbientUrl = null;
                }
            }

            // 剧情音逻辑
            if (CONFIG.enableStory && !state.isPlotPaused) {
                let targetStory = null;
                let targetTitle = "";
                let targetMode = "repeat_one";
                let forceTrigger = false;
                const activeObj = String(_.get(curStat, '当前活跃对象', ''));

                const curTitles = _.get(curStat, '玩家数据.称号列表', {});
                const prevTitles = _.get(prevStat, '玩家数据.称号列表', {});

                // 按照优先级顺序判断

                // 1. 步入婚姻 / 订婚之约
                if (!targetStory) {
                    const curStage = String(_.get(curStat, '玩家数据.恋爱阶段', ''));
                    const prevStage = String(_.get(prevStat, '玩家数据.恋爱阶段', ''));

                    const curMarried = curStage.includes('结婚') || curStage.includes('已婚');
                    const prevMarried = prevStage.includes('结婚') || prevStage.includes('已婚');
                    const curEngaged = curStage.includes('订婚') || curStage.includes('试婚');
                    const prevEngaged = prevStage.includes('订婚') || prevStage.includes('试婚');

                    if (curMarried && !prevMarried) {
                        targetStory = MUSIC_LINKS.story_marry;
                        targetTitle = "剧情_步入婚姻";
                        targetMode = "play_one_and_stop";
                        forceTrigger = true;
                    } else if (curEngaged && !prevEngaged) {
                        targetStory = MUSIC_LINKS.story_engage;
                        targetTitle = "剧情_订婚之约";
                        targetMode = "play_one_and_stop";
                        forceTrigger = true;
                    }
                }

                // 2. 心意相通
                if (!targetStory && activeObj) {
                    const curFav = _.get(curStat, `交往对象列表["${activeObj}"].好感度`, 0);
                    const prevFav = _.get(prevStat, `交往对象列表["${activeObj}"].好感度`, 0);
                    if (curFav >= 100 && prevFav < 100) {
                        targetStory = MUSIC_LINKS.story_fav100;
                        targetTitle = "剧情_心意相通";
                        targetMode = "play_one_and_stop";
                        forceTrigger = true;
                    }
                }

                // 3. 天空之城
                if (!targetStory) {
                    const curContent = String(_.get(curStat, '当前事件.事件内容', ''));
                    const prevContent = String(_.get(prevStat, '当前事件.事件内容', ''));
                    const skyKeys = ['孕', '胎', '早教'];

                    const curHas = skyKeys.some(k => curContent.includes(k));
                    const prevHas = skyKeys.some(k => prevContent.includes(k));

                    if (curHas && !prevHas) {
                        targetStory = MUSIC_LINKS.story_skycity;
                        targetTitle = "剧情_天空之城";
                        targetMode = "play_one_and_stop";
                        forceTrigger = true;
                    }
                }

                // 4. 生日快乐
                if (!targetStory) {
                    const curContent = String(_.get(curStat, '当前事件.事件内容', ''));
                    const prevContent = String(_.get(prevStat, '当前事件.事件内容', ''));
                    const birthdayKeys = ['生日', '生辰', '寿星'];

                    const curHas = birthdayKeys.some(k => curContent.includes(k));
                    const prevHas = birthdayKeys.some(k => prevContent.includes(k));

                    if (curHas && !prevHas) {
                        targetStory = MUSIC_LINKS.story_birthday;
                        targetTitle = "剧情_生日快乐";
                        targetMode = "play_one_and_stop";
                        forceTrigger = true;
                    }
                }

                // 5. 痴心绝对
                if (!targetStory) {
                    const hasTargetTitle = (stat) => {
                        const titles = _.get(stat, '玩家数据.称号列表', {});
                        return Object.entries(titles).some(([titleName, isActive]) => {
                            if (!isActive) return false;
                            return titleName.includes('舔狗') || titleName.includes('纯爱');
                        });
                    };

                    const curHasTitle = hasTargetTitle(curStat);
                    const prevHasTitle = hasTargetTitle(prevStat);

                    if (curHasTitle && !prevHasTitle) {
                        targetStory = MUSIC_LINKS.story_devotion;
                        targetTitle = "剧情_痴心绝对";
                        targetMode = "play_one_and_stop";
                        forceTrigger = true;
                    }
                }

                // 6. 地下情人
                if (!targetStory) {
                    const curHasCaoZei = curTitles['曹贼'] === true;
                    const prevHasCaoZei = prevTitles['曹贼'] === true;

                    if (curHasCaoZei && !prevHasCaoZei) {
                        targetStory = MUSIC_LINKS.story_underground;
                        targetTitle = "剧情_地下情人";
                        targetMode = "play_one_and_stop";
                        forceTrigger = true;
                    }
                }

                // 7. 负心之人
                if (!targetStory) {
                    const curHasFuXinHan = curTitles['负心汉'] === true;
                    const prevHasFuXinHan = prevTitles['负心汉'] === true;

                    if (curHasFuXinHan && !prevHasFuXinHan) {
                        targetStory = MUSIC_LINKS.story_breakup;
                        targetTitle = "剧情_负心之人";
                        targetMode = "play_one_and_stop";
                        forceTrigger = true;
                    }
                }

                // 8. 即兴表演
                if (!targetStory) {
                    const hasSatisfiedMatchmaker = (stat) => {
                        const objList = _.get(stat, '交往对象列表', {});
                        return Object.values(objList).some(obj => {
                            const types = _.get(obj, '对象类型', []);
                            const fav = _.get(obj, '好感度', 0);
                            return types.includes('婚托') && fav >= 40;
                        });
                    };

                    const curHasMatchmaker = hasSatisfiedMatchmaker(curStat);
                    const prevHasMatchmaker = hasSatisfiedMatchmaker(prevStat);

                    if (curHasMatchmaker && !prevHasMatchmaker) {
                        targetStory = MUSIC_LINKS.story_improvise;
                        targetTitle = "剧情_即兴表演";
                        targetMode = "play_one_and_stop";
                        forceTrigger = true;
                    }
                }

                // 9. 重回单身
                if (!targetStory) {
                    const curIsEmpty = Object.keys(_.get(curStat, '交往对象列表', {})).length === 0;
                    const prevIsNotEmpty = Object.keys(_.get(prevStat, '交往对象列表', {})).length > 0;

                    if (curIsEmpty && prevIsNotEmpty) {
                        targetStory = MUSIC_LINKS.story_single;
                        targetTitle = "剧情_重回单身";
                        targetMode = "play_one_and_stop";
                        forceTrigger = true;
                    }
                }

                // 10. 追忆往昔
                if (!targetStory) {
                    const curContent = String(_.get(curStat, '当前事件.事件内容', ''));
                    const prevContent = String(_.get(prevStat, '当前事件.事件内容', ''));

                    const curMatch = (curContent.includes('回忆') || curContent.includes('思念') || curContent.includes('想念')) && (curContent.includes('以前') || curContent.includes('往事') || curContent.includes('过往'));
                    const prevMatch = (prevContent.includes('回忆') || prevContent.includes('思念') || prevContent.includes('想念')) && (prevContent.includes('以前') || prevContent.includes('往事') || prevContent.includes('过往'));

                    if (curMatch && !prevMatch) {
                        targetStory = MUSIC_LINKS.story_summerwind;
                        targetTitle = "剧情_追忆往昔";
                        targetMode = "play_one_and_stop";
                        forceTrigger = true;
                    }
                }

                // 11. 痴情之人
                if (!targetStory && activeObj) {
                    const checkInfatuation = (stat, objName) => {
                        const time = _.get(stat, `交往对象列表["${objName}"].交往时长`, 0);
                        const fav = _.get(stat, `交往对象列表["${objName}"].好感度`, 0);
                        return time > 365 && fav < 50;
                    };

                    const curHas = checkInfatuation(curStat, activeObj);
                    const prevHas = checkInfatuation(prevStat, activeObj);

                    if (curHas && !prevHas) {
                        targetStory = MUSIC_LINKS.story_infatuation;
                        targetTitle = "剧情_痴情之人";
                        targetMode = "play_one_and_stop";
                        forceTrigger = true;
                    }
                }

                // 12. 移情别恋
                if (!targetStory && activeObj) {
                    const curObjList = _.get(curStat, '交往对象列表', {});
                    const objKeys = Object.keys(curObjList);

                    if (objKeys.length >= 2) {
                        const curActiveFav = _.get(curObjList, `["${activeObj}"].好感度`, 0);

                        if (curActiveFav >= 20) {
                            let isCurHighest = true;
                            for (const name of objKeys) {
                                if (name !== activeObj && (_.get(curObjList, `["${name}"].好感度`, 0) >= curActiveFav)) {
                                    isCurHighest = false;
                                    break;
                                }
                            }

                            if (isCurHighest) {
                                let isPrevHighest = true;
                                const prevObjList = _.get(prevStat, '交往对象列表', {});
                                const prevActiveFav = _.get(prevObjList, `["${activeObj}"].好感度`, 0);

                                for (const name of Object.keys(prevObjList)) {
                                    if (name !== activeObj && (_.get(prevObjList, `["${name}"].好感度`, 0) >= prevActiveFav)) {
                                        isPrevHighest = false;
                                        break;
                                    }
                                }

                                if (!isPrevHighest) {
                                    targetStory = MUSIC_LINKS.story_transfer;
                                    targetTitle = "剧情_移情别恋";
                                    targetMode = "play_one_and_stop";
                                    forceTrigger = true;
                                }
                            }
                        }
                    }
                }

                // 13. 获得称号
                if (!targetStory) {
                    for (const title in curTitles) {
                        if (curTitles[title] && !prevTitles[title]) {
                            targetStory = MUSIC_LINKS.story_title;
                            targetTitle = "剧情_获得称号";
                            targetMode = "play_one_and_stop";
                            forceTrigger = true;
                            break;
                        }
                    }
                }

                // 14. 关系变化
                if (!targetStory && activeObj) {
                    const curStatus = _.get(curStat, `交往对象列表["${activeObj}"].交往状态`);
                    const prevStatus = _.get(prevStat, `交往对象列表["${activeObj}"].交往状态`);

                    if (curStatus !== undefined && curStatus !== prevStatus) {
                        targetStory = MUSIC_LINKS.story_relation_change;
                        targetTitle = "剧情_关系变化";
                        targetMode = "play_one_and_stop";
                        forceTrigger = true;
                    }
                }

                // 15. 现金变动
                if (!targetStory) {
                    const curCash = Number(_.get(curStat, '玩家数据.现金余额', 0));
                    const prevCash = Number(_.get(prevStat, '玩家数据.现金余额', 0));

                    if (curCash > prevCash) {
                        targetStory = MUSIC_LINKS.story_cash_in;
                        targetTitle = "剧情_现金到账";
                        targetMode = "play_one_and_stop";
                        forceTrigger = true;
                    } else if (curCash < prevCash) {
                        targetStory = MUSIC_LINKS.story_cash_out;
                        targetTitle = "剧情_现金消费";
                        targetMode = "play_one_and_stop";
                        forceTrigger = true;
                    }
                }

                // 16. 情欲涌动 (最低优先级)
                if (!targetStory && activeObj) {
                    const curDesire = _.get(curStat, `交往对象列表["${activeObj}"].情欲值`, 0);
                    if (curDesire >= 80) {
                        targetStory = MUSIC_LINKS.story_desire;
                        targetTitle = "剧情_情欲涌动";
                        targetMode = "repeat_one";
                        // 持续性状态不加 forceTrigger
                    }
                }

                // 执行播放
                if (targetStory) {
                    if (CONFIG.disableLoop && targetMode === 'repeat_one') {
                        targetMode = 'play_one_and_stop';
                    }

                    if (forceReplay || forceTrigger || targetStory !== state.currentStoryUrl) {
                        state.currentStoryUrl = targetStory;
                        state.currentStoryMode = targetMode; // 记录当前模式
                        playAudioWithFade('bgm', targetStory, targetTitle, targetMode);
                    } else if (targetMode !== state.currentStoryMode) {
                        state.currentStoryMode = targetMode;
                        if (typeof TavernHelper !== 'undefined' && TavernHelper.setAudioSettings) {
                            TavernHelper.setAudioSettings('bgm', { mode: targetMode });
                        }
                    }
                } else if (!targetStory && state.currentStoryUrl && !forceReplay) {
                    // 仅当不是一次性音乐时，才去主动停止。一次性音乐让它自己播完。
                    if (state.currentStoryMode !== 'play_one_and_stop') {
                        if (fadeIntervals['bgm']) clearInterval(fadeIntervals['bgm']);
                        TavernHelper.pauseAudio('bgm');
                    }
                    // 无论是否物理停止，都清理记录，防止一次性音乐残留阻挡下一次的相同触发
                    state.currentStoryUrl = null;
                    state.currentStoryMode = null;
                }
            } else {
                if (state.currentStoryUrl) {
                    if (fadeIntervals['bgm']) clearInterval(fadeIntervals['bgm']);
                    TavernHelper.pauseAudio('bgm');
                    state.currentStoryUrl = null;
                    state.currentStoryMode = null;
                }
            }
        } catch (error) {
            console.error('[音乐控制] 检测发生错误:', error);
        }
    }

    // 统一防抖与调度器
    let scheduleTimer = null;

    const scheduleCheck = (forceInterrupt = false) => {
        if (scheduleTimer) clearTimeout(scheduleTimer);

        if (forceInterrupt) {
            // 时间线变动时的物理打断
            if (state.currentStoryUrl) {
                if (fadeIntervals['bgm']) clearInterval(fadeIntervals['bgm']);
                TavernHelper.pauseAudio('bgm');
                state.currentStoryUrl = null;
                state.currentStoryMode = null;
            }
            if (state.currentAmbientUrl) {
                if (fadeIntervals['ambient']) clearInterval(fadeIntervals['ambient']);
                TavernHelper.pauseAudio('ambient');
                state.currentAmbientUrl = null;
            }
        }

        // 变量更新完毕加渲染缓冲
        scheduleTimer = setTimeout(() => {
            scheduleTimer = null;
            checkMusicStatus(forceInterrupt);
        }, CONFIG.syncDelay);
    };

    // 消息事件监听
    const initListeners = () => {
        if (typeof eventOn === 'function') {
            // 1. 依赖变量更新结束事件
            try {
                eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => scheduleCheck(false));
            } catch (e) {
                console.warn('[音乐控制] Mvu 钩子挂载异常:', e);
            }

            // 2. 时间线变动物理打断与状态重检
            if (typeof tavern_events !== 'undefined') {
                // 滑屏和删除会改变当前时间线，需要打断当前音乐并重新检测
                eventOn(tavern_events.MESSAGE_SWIPED, () => scheduleCheck(true));
                eventOn(tavern_events.MESSAGE_DELETED, () => scheduleCheck(true));
                eventOn(tavern_events.CHAT_CHANGED, () => scheduleCheck(true));

                // 3. BGM 标签替换逻辑
                // AI 回复完毕
                eventOn(tavern_events.MESSAGE_RECEIVED, async (messageId) => {
                    await processBgmTags(messageId);
                });

                // 用户发送消息
                eventOn(tavern_events.MESSAGE_SENT, async (messageId) => {
                    await processBgmTags(messageId);
                });

                // 消息被手动编辑
                eventOn(tavern_events.MESSAGE_UPDATED, async (messageId) => {
                    await processBgmTags(messageId);
                });
            }
        }
    };

    // 控制台通信监听
    const setupCommunication = () => {
        if (typeof eventOn === 'function') {
            eventOn('XQ_ForcePauseAmbient', () => {
                if(!state.isAmbientPaused) {
                    state.isAmbientPaused = true;
                    if (fadeIntervals['ambient']) clearInterval(fadeIntervals['ambient']);
                    TavernHelper.pauseAudio('ambient');
                    state.currentAmbientUrl = null;
                    toastr.info("环境音轨已暂停", "音频控制");
                }
            });
            eventOn('XQ_ForceResumeAmbient', () => {
                if(state.isAmbientPaused) {
                    state.isAmbientPaused = false;
                    toastr.success("环境音轨已恢复", "音频控制");
                    scheduleCheck(true);
                }
            });
            eventOn('XQ_ForcePauseStory', () => {
                if(!state.isPlotPaused) {
                    state.isPlotPaused = true;
                    if (fadeIntervals['bgm']) clearInterval(fadeIntervals['bgm']);
                    TavernHelper.pauseAudio('bgm');
                    state.currentStoryUrl = null;
                    state.currentStoryMode = null;
                    toastr.info("剧情音轨已暂停", "音频控制");
                }
            });
            eventOn('XQ_ForceResumeStory', () => {
                if(state.isPlotPaused) {
                    state.isPlotPaused = false;
                    toastr.success("剧情音轨已恢复", "音频控制");
                    scheduleCheck(true);
                }
            });

            eventOn('XQ_ConfigUpdated', async () => {
                loadConfig();
                scheduleCheck(false);
            });

            // 监听心遇后端发出的全局状态变更
            eventOn('XQ_AppStateChanged', () => {
                scheduleCheck(false);
            });

            // 监听状态栏发出的活跃对象切换
            eventOn('XQ_ActiveObjectChanged', () => {
                scheduleCheck(false);
            });
        }
    };

    // 启动序列
    loadConfig();
    initListeners();
    setupCommunication();
    scheduleCheck(false); // 初始化时发起首次检测

})();

/**
=========================================================================
 楼层自动隐藏器_v3.4
 作者：Berger
=========================================================================
*/

(async () => {
    // 等待 Mvu 框架就绪
    try {
        await waitGlobalInitialized('Mvu');
    } catch (e) {
        console.error('[AutoHider] 缺少 Mvu 框架支持，无法启动。');
        return;
    }

    // 双重宏任务让步，确保垫底启动
    await new Promise(r => setTimeout(r, 0));
    await new Promise(r => setTimeout(r, 0));

    if (typeof SillyTavern === 'undefined' || typeof setChatMessages !== 'function') {
        console.error('[AutoHider] 缺少必要的底层 API (setChatMessages)，无法启动。');
        return;
    }

    // === 保底配置项 ===
    const CONFIG = {
        enable: true,        // [总开关] 隐藏楼层 (默认true启用，控制自动隐藏是否生效)
        incremental: true,   // [模式开关] 增量模式 (默认true启用增量维护，false则改为全量维护)
        keep: 16,
        buffer: 4,
        syncDelay: 500       // 用于避峰延迟的毫秒数
    };

    // 状态记录
    let isHiderActive = false;

    // 用于脏检测 (现在只在启动和配置更新时读取，避免高频IO)
    let currentEnable = null;
    let currentInc = null;
    let currentKeep = null;
    let currentBuf = null;

    // 辅助函数：解析布尔值
    function parseBool(val, defaultVal) {
        if (val === undefined || val === null) return defaultVal;
        if (typeof val === 'boolean') return val;
        if (typeof val === 'string') return val.toLowerCase() === 'true' || val === '1';
        if (typeof val === 'number') return val !== 0;
        return defaultVal;
    }

    // === 动态配置加载 ===
    function loadConfig() {
        const targetWindow = (typeof parent !== 'undefined' && parent.window) ? parent.window : window;
        const globalConfig = targetWindow.XQ_Config || {};

        let newEnable = CONFIG.enable;
        let newInc = CONFIG.incremental;
        let newKeep = CONFIG.keep;
        let newBuf = CONFIG.buffer;

        // 加载总开关
        let enableVal = globalConfig['XQ_Hide_Enable'];
        if (enableVal === undefined) enableVal = localStorage.getItem('XQ_Hide_Enable');
        if (enableVal !== null) newEnable = parseBool(enableVal, true);

        // 加载增量模式开关
        let incVal = globalConfig['XQ_Hide_Incremental'];
        if (incVal === undefined) incVal = localStorage.getItem('XQ_Hide_Incremental');
        if (incVal !== null) newInc = parseBool(incVal, true);

        // 加载保留层数
        let keepVal = globalConfig['XQ_Hide_Keep'];
        if (keepVal === undefined) keepVal = localStorage.getItem('XQ_Hide_Keep');
        if (keepVal !== null) {
            const parsedKeep = parseInt(keepVal, 10);
            if (!isNaN(parsedKeep) && parsedKeep > 0) newKeep = parsedKeep;
        }

        // 加载缓冲层数
        let bufVal = globalConfig['XQ_Hide_Buffer'];
        if (bufVal === undefined) bufVal = localStorage.getItem('XQ_Hide_Buffer');
        if (bufVal !== null) {
            const parsedBuf = parseInt(bufVal, 10);
            if (!isNaN(parsedBuf) && parsedBuf >= 0) newBuf = parsedBuf;
        }

        // 脏检测
        if (currentEnable === newEnable &&
            currentInc === newInc &&
            currentKeep === newKeep &&
            currentBuf === newBuf) {
            return false;
        }

        CONFIG.enable = newEnable;
        CONFIG.incremental = newInc;
        CONFIG.keep = newKeep;
        CONFIG.buffer = newBuf;

        currentEnable = newEnable;
        currentInc = newInc;
        currentKeep = newKeep;
        currentBuf = newBuf;

        console.log(`[AutoHider] 配置已同步: 开关 ${CONFIG.enable}, 保留 ${CONFIG.keep} 层`);
        return true;
    }

    // 避开性能高峰的微小延时助手
    const idleDelay = () => new Promise(resolve => {
        if ('requestIdleCallback' in window) {
            requestIdleCallback(() => setTimeout(resolve, CONFIG.syncDelay), { timeout: 2000 });
        } else {
            setTimeout(resolve, CONFIG.syncDelay);
        }
    });

    function getLastMessageIdSafe() {
        return typeof getLastMessageId === 'function' ? getLastMessageId() : 0;
    }

    // 核心逻辑：执行按需显隐
    async function performHide(forceFull = false, showToast = false) {
        if (!isHiderActive) return;

        const total = getLastMessageIdSafe() + 1;
        if (total === 0) return;

        const updates = [];

        // 如果总楼层小于等于保留阈值
        if (total <= CONFIG.keep) {
            if (showToast && typeof toastr !== 'undefined') {
                toastr.info(`当前仅有 ${total} 层，未达到隐藏阈值 ${CONFIG.keep} 层，暂不隐藏。`, 'AutoHider');
            }

            if (forceFull) {
                // 全量校验：确保0到total-1全是可见状态
                const msgs = getChatMessages(`0-${total - 1}`);
                for (let i = 0; i < msgs.length; i++) {
                    const msg = msgs[i];
                    if (msg && msg.is_hidden !== false) {
                        updates.push({ message_id: msg.message_id, is_hidden: false });
                    }
                }
                if (updates.length > 0) {
                    await setChatMessages(updates, { refresh: 'affected' });
                    console.log(`[AutoHider] 全量维护: 楼层不足，已将实际隐藏的楼层重新显示`);
                }
            }
            return;
        }

        const showStart = total - CONFIG.keep;
        const hideEnd = showStart - 1;

        let checkStart = 0;
        // 增量模式：只检查需要操作的缓冲区和保留区
        if (!forceFull && CONFIG.incremental) {
            checkStart = Math.max(0, hideEnd - CONFIG.buffer);
        }

        // 使用封装好的定向区间获取实际的标准化隐藏状态
        const msgs = getChatMessages(`${checkStart}-${total - 1}`);

        for (let i = 0; i < msgs.length; i++) {
            const msg = msgs[i];
            if (!msg) continue;

            const floorId = msg.message_id;
            // 判断当前楼层预期应该是隐藏还是显示
            const expectedHidden = (floorId <= hideEnd);

            // 状态核对，只有真实状态不符时才构造更新对象
            if (msg.is_hidden !== expectedHidden) {
                updates.push({ message_id: floorId, is_hidden: expectedHidden });
            }
        }

        if (updates.length > 0) {
            await setChatMessages(updates, { refresh: 'affected' });
            if (showToast && typeof toastr !== 'undefined') {
                toastr.success(`已更新历史记录显隐状态，当前保留最新 ${CONFIG.keep} 楼。`, 'AutoHider');
            }
        } else {
            if (showToast && typeof toastr !== 'undefined') {
                toastr.success(`状态已是对齐的，保留最新 ${CONFIG.keep} 楼。`, 'AutoHider');
            }
        }
    }

    // === 功能开关 ===
    async function enableHider(isManual = false) {
        if (isHiderActive && !isManual) return;
        isHiderActive = true;
        // 手动开启时强制全量校验一次
        await performHide(true, isManual);
    }

    async function disableHider(showToast = true) {
        if (!isHiderActive) {
            if (showToast && typeof toastr !== 'undefined') {
                const total = getLastMessageIdSafe() + 1;
                toastr.info(`当前共 ${total} 楼，全部未隐藏。`, 'AutoHider');
            }
            return;
        }

        isHiderActive = false;
        const total = getLastMessageIdSafe() + 1;
        if (total === 0) return;

        const updates = [];
        const msgs = getChatMessages(`0-${total - 1}`);
        for (let i = 0; i < msgs.length; i++) {
            const msg = msgs[i];
            if (msg && msg.is_hidden !== false) {
                updates.push({ message_id: msg.message_id, is_hidden: false });
            }
        }

        if (updates.length > 0) {
            await setChatMessages(updates, { refresh: 'affected' });
        }

        console.log(`[AutoHider] 已取消隐藏所有 ${total} 楼。`);
        if (showToast && typeof toastr !== 'undefined') {
            toastr.warning(`已取消隐藏所有 ${total} 层，自动隐藏已关闭。`, 'AutoHider');
        }
    }

    // 事件响应
    async function handleMessageReceived() {
        if (!isHiderActive) return;
        await idleDelay();
        await performHide(false, false);
    }

    async function handleMessageDeleted() {
        if (!isHiderActive) return;
        // 绝对不要在这里添加任何延迟！这是微任务抢险，赶在组装前翻转被删减露出的楼层！
        await performHide(false, false);
    }

    async function handleChatChanged() {
        if (!isHiderActive) return;
        await idleDelay();
        await performHide(true, false);
    }

    // === 初始化与监听注册 ===
    const registerEvents = () => {
        if (window.tavern_events) {
            // 仅在初始化注册一次
            eventMakeLast(tavern_events.MESSAGE_RECEIVED, handleMessageReceived);
            eventOn(tavern_events.MESSAGE_DELETED, handleMessageDeleted);
            eventOn(tavern_events.CHAT_CHANGED, handleChatChanged);
            eventOnce(tavern_events.APP_READY, handleChatChanged);
        }
    };

    const setupCommunication = () => {
        if (typeof eventOn === 'function') {
            eventOn('XQ_ForceHideFloor', () => enableHider(true));
            eventOn('XQ_ForceShowFloor', () => disableHider(true));

            eventOn('XQ_ConfigUpdated', async () => {
                if (loadConfig()) {
                    if (CONFIG.enable && !isHiderActive) {
                        await enableHider(false);
                    } else if (!CONFIG.enable && isHiderActive) {
                        await disableHider(false);
                    } else if (isHiderActive) {
                        await performHide(true, false);
                    }
                }
            });
        }
    };

    // 启动序列
    const startup = () => {
        loadConfig();
        registerEvents();
        setupCommunication();

        if (CONFIG.enable) {
            isHiderActive = true;
            // 利用APP_READY来做首次扫描
        }
    };

    startup();

})();

(async () => {
    // 宏任务避让，确保靠后启动
    await new Promise(r => setTimeout(r, 0));

    // 等待 MVU 框架就绪
    try {
        await waitGlobalInitialized('Mvu');
    } catch (e) {
        console.error('[难度调节器] Mvu 初始化失败:', e);
        return;
    }

    // 闲置避让助手
    const idleDelay = (delayMs = 500) => new Promise(resolve => {
        if ('requestIdleCallback' in window) {
            requestIdleCallback(() => setTimeout(resolve, delayMs), { timeout: 2000 });
        } else {
            setTimeout(resolve, delayMs);
        }
    });

    let currentDifficulty = localStorage.getItem('XQ_Difficulty_Level') || '困难';
    let dndChats = new Set();
    let eventQueue = [];

    console.log(`[难度调节器] 脚本启动成功，当前难度：${currentDifficulty}`);

    // 监听聊天切换，清空队列
    eventOn(tavern_events.CHAT_CHANGED, () => {
        eventQueue = [];
        console.log(`[难度调节器] 聊天已切换，事件队列已清空`);
    });

    // 应用难度设置
    async function applyDifficultySettings(level) {
        console.log(`[难度调节器] 难度已切换为：${level}`);

        currentDifficulty = level;
        localStorage.setItem('XQ_Difficulty_Level', level);

        let limitEnable = (level === '困难' || level === '现实');
        localStorage.setItem('XQ_Fav_Limit_Enable', limitEnable.toString());
        localStorage.setItem('XQ_Desire_Limit_Enable', limitEnable.toString());

        // 同步到全局配置
        const targetWindow = (typeof parent !== 'undefined' && parent.window) ? parent.window : window;
        targetWindow.XQ_Config = targetWindow.XQ_Config || {};
        targetWindow.XQ_Config['XQ_Fav_Limit_Enable'] = limitEnable;
        targetWindow.XQ_Config['XQ_Desire_Limit_Enable'] = limitEnable;

        eventEmit('XQ_ConfigUpdated');

        try {
            const charWb = getCharWorldbookNames('current');
            const wbName = charWb ? charWb.primary : null;

            if (wbName) {
                await updateWorldbookWith(wbName, wb => {
                    wb.forEach(entry => {
                        if (entry.name === "👥人性与社交" || entry.name === "💕恋爱与情感" || entry.name === "🎭演绎与文风") {
                            entry.enabled = (level !== '简单');
                        }
                        if (entry.name === "🔧剧情与修正") {
                            entry.enabled = (level === '现实');
                        }
                    });
                    return wb;
                }, { render: 'debounced' });
            }
        } catch (e) {
            console.warn(`[难度调节器] 更新世界书失败:`, e);
        }
    }

    // 获取顶层窗口，并在顶层窗口上监听前端发来的 postMessage
    const topWindow = window.top || window.parent || window;

    // 移除旧的监听器，防止脚本重载导致重复绑定
    if (topWindow._xq_difficulty_listener) {
        topWindow.removeEventListener('message', topWindow._xq_difficulty_listener);
    }

    topWindow._xq_difficulty_listener = (event) => {
        if (event.data && event.data.type === 'XQ_SET_DIFFICULTY') {
            applyDifficultySettings(event.data.level);
        }
    };

    topWindow.addEventListener('message', topWindow._xq_difficulty_listener);

    // 监听变量更新结束事件
    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, async (variables) => {
        await idleDelay(300);

        const chatId = SillyTavern.getCurrentChatId();

        if ((currentDifficulty !== '困难' && currentDifficulty !== '现实') || (chatId && dndChats.has(chatId))) {
            return;
        }

        if (!variables) return;

        const eventId = _.get(variables, 'stat_data.当前事件.事件编号', '');
        const currentMsgId = getLastMessageId();

        if (!eventId) return;

        eventQueue = eventQueue.filter(item => currentMsgId - item.messageId <= 50);

        if (eventId.startsWith('N') || eventId.startsWith('X')) {
            const exists = eventQueue.find(item => item.messageId === currentMsgId && item.eventId === eventId);
            if (!exists) {
                eventQueue.push({ eventId: eventId, messageId: currentMsgId });
            }
        }

        let shouldTrigger = false;

        if (eventId.startsWith('X')) {
            shouldTrigger = true;
        } else {
            const recent10 = new Set(eventQueue.filter(i => currentMsgId - i.messageId <= 10 && i.eventId.startsWith('N')).map(i => i.eventId));
            const recent50 = new Set(eventQueue.filter(i => currentMsgId - i.messageId <= 50 && i.eventId.startsWith('N')).map(i => i.eventId));

            if (recent10.size >= 2 || recent50.size >= 3) {
                shouldTrigger = true;
            }
        }

        if (shouldTrigger) {
            // 使用 setTimeout 将弹窗与重处理逻辑脱离当前 MVU 事件循环，防止数据覆盖
            setTimeout(async () => {
                try {
                    const result = await SillyTavern.callGenericPopup(
                        "您的行为疑似新手，需要为您返还本次扣除的好感，并将难度降至‘普通’吗？",
                        SillyTavern.POPUP_TYPE.CONFIRM,
                        "",
                        { okButton: "需要", cancelButton: "不用" }
                    );

                    if (result === SillyTavern.POPUP_RESULT.AFFIRMATIVE) {
                        await applyDifficultySettings('普通');

                        const targetWindow = (typeof parent !== 'undefined' && parent.window) ? parent.window : window;
                        const $btn = targetWindow.$('#extensions_settings2 .mvu-button-wrap .menu_button').filter(function() {
                            return targetWindow.$(this).text().trim() === '重新处理变量';
                        });
                        if ($btn.length > 0) {
                            $btn.click();
                        } else {
                            console.warn(`[难度调节器] 未找到“重新处理变量”按钮`);
                        }

                        await SillyTavern.callGenericPopup("已返还好感并降至‘普通’难度", SillyTavern.POPUP_TYPE.TEXT);
                    } else {
                        if (chatId) {
                            dndChats.add(chatId);
                        }
                        await SillyTavern.callGenericPopup("您仍可以随时手动调节难度", SillyTavern.POPUP_TYPE.TEXT);
                    }

                    eventQueue = [];
                } catch (e) {
                    console.warn(`[难度调节器] 弹窗调用失败:`, e);
                }
            }, 200);
        }
    });
})();

